window.__D("text/pelach-harimon/c003",{"p":[[4801940625,"הוא אדום, דהיינו כענין עבר על מ\"ע הנ\"ל שהפגם רק במדות, אזי כשלג ילבינו ע\"י תשו' שמעורר מוחין שהם העצם והוא לבן, כידוע שגוון לבן הוא גוון עצמי כמבואר בעט\"ר<sup data-n=\"2373\">172</sup> בענין בגדי כה\"ג, ולכן ארי\"צ אם יהיו חטאיכם כשנים הללו שהן סדורות משימ\"ב שהוא ו' מדות מקור העולמות כידוע ע\"פ ששת ימים עשה<sup data-n=\"2374\">173</sup> ולא נא' בששת אלין שית יומין דבהון עבד קוב\"ה כו', ולכן דקדק בלשון סדורות ובאות שהפגם הוא בסדר זמנים כידוע במד\"ר מלמד שהי' סדר זמנים קודם לכן<sup data-n=\"2375\">174</sup>, כידוע שהזמן הוא במל'<sup data-n=\"2376\">175</sup> מלך מלך וימלוך<sup data-n=\"2377\">176</sup> וסדר זמנים בז\"א<sup data-n=\"2378\">177</sup> ומקור הזמן בבינה<sup data-n=\"2379\">178</sup> כו', ולפי שיטת הבבלי מוכרח לפרש אם יאדימו שקאי על פגם המוחין שהם מקור המדות, שהוא ע\"י עברו על מל\"ת, ויצטרך לפרש ענין כצמר יהיו ע\"י תשו' דיוהכ\"פ.\n<b>אבל</b> הירושלמי מפרש באופן אחר שבאמת כל העשר כוחות שבנפש אפי' המוחין אינם רק גווני הנפש אך בזה גופא<sup data-n=\"2380\">179</sup> יש הפרש, כי אפי' מי שפגם גם במוחין עכ\"ז אפשר שיעורר מוחי' היותר עליונים ובהם יושלם הפגם, כמבואר במ\"א שגם בחכ' יש ב' בחי', ויש בפי' והחכ' מאין תמצא<sup data-n=\"2381\">180</sup> ב' פירושים, א' שהחכ' מאין<sup data-n=\"2382\">181</sup> תמצא ליש, ופי' הב' שהחכ' עצמה הוא בחי' אין, וזו היא מדריגה גבוה בחכ' עצמה, נמצא אפי' מי שפגם במוחי' עצמ' (כמדריגת תשו' שקדמה לעולם כנ\"ל) אפשר להשלים הפגם ע\"י המוחי' היותר עליונים וזה הי' מדריגת האבות שהי' עבודתם להוסיף אורות באצי' אפי' במוחין עצמם, וזהו פי' דברי' ר' אליעזר בירושלמי, אם יהיו<sup data-n=\"2383\">182</sup> חטאיכם כשנים שבין שמים לארץ שהוא ת\"ק שנה שהוא מן החכ' עד המל' כנ\"ל, כשלג ילבינו",[["2373","172","<b>לבן הוא גוון עצמי כמבואר בעט\"ר</b>: לא, ב. לב, א. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תפד. וש\"נ. דברים ח\"ד ע' א'רלו-א'רלז."],["2374","173","<b>ששת ימים עשה</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 19 ואילך."],["2375","174","<b>מלמד שהי' סדר זמנים קודם לכן</b>: ראה ב\"ר פ\"ג, ז."],["2376","175","<b>שהזמן הוא במל'</b>: ראה שער היחוד והאמונה פ\"ז. מאמרי אדה\"א דברים ח\"א ע' קלה. וש\"נ. תו\"ח בשלח ח\"א רלד, א וש\"נ. לעיל ע' קטז. לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב על יד הערה 26. ד\"ה בסוכות תשבו תרכ\"ב על יד הערה 25."],["2377","176","<b>מלך מלך וימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך."],["2378","177","<b>וסדר זמנים בז\"א</b>: ראה גם סהמ\"צ להצ\"צ נט, א. קנא, א. מאמרי אדה\"ז תקס\"ה ח\"א ע' שכ ואילך (נו\"א). תקס\"ו ע' מג. ביאוה\"ז להצ\"צ ח\"א ע' רנז. אוה\"ת ח\"ש תשפג, ב. משפטים ע' א'קכא. במדבר ע' פה. פינחס ס\"ע א'קצב ואילך. לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב על יד הערה 28 ואילך."],["2379","178","<b>ומקור הזמן בבינה</b>: ראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב."],["2380","179","<b>אך בזה גופא. . בסידור וכנ\"ל</b>: א: שלא פגם את רצה\"פ שבנפש ע\"י פר\"ע אפי' אם ( ) את המוחין ג\"כ ע\"י שעבר על מל\"ת וכו' עז\"א אם יהיו כשנים ולכן מפרש הירושלמי שהוא כשני האבות שהם תק\"ב שהוא כימי השמים על הארץ, וכנ\"ל בסעי' ד' שהוא מן החכ' עד המל' ומפ' כשלג ילבינו ע\"י גורל דאה\"ר שמעורר רצוה\"פ כנ\"ל ולזה מסיים הירושלמי יתר מכאן דהיינו עבר על כריתות ומב\"ד שאז אינו מועיל לו גם התשובה דיוהכ\"פ כנ\"ל בענין לא יאבה ד' כו' ואז כצמר יהיה שהוא בחי' עתיקא כמבואר בסי' כנ\"ל בסעי' ה( )."],["2381","180","<b>והחכ' מאין תמצא</b>: איוב כח, יב. ראה גם לקמן מאמר ד\"ה את שבתותי תקצ\"ח ובהערה 80."],["2382","181","<b>שהחכ'. . אין</b>: ראה מאמרי אדה\"א במדבר ח\"ב ע' תתנ וע' תתע. סה\"מ תרל\"ח ע' רכז. וש\"נ."],["2383","182","<b>וזהו. . יהיו</b>: בא מופיע קטע זה בסיום המאמר."]]],[4801940630,"ע\"י המשכת מוחי' היותר עליונים כעבודת האבות, ואז יושלם הפגם, יתר מכן דהיינו אם פגם אפי' במדריגת האבות שהם המוחי' היותר עליוני', והוא פי' על אם יאדימו כתולע, אזי נצרך לעורר הרצה\"פ שהוא ע\"י גורל דיוה\"כ, אבל ר' יהושע שבירושלמי מפרש אם יהיו חטאיכם כשנים שהוא כשני האבות, שהם ג\"כ ת\"ק (לבד הב' שנים כנ\"ל) והוא ג\"כ מן החכ' עד המל' כנ\"ל אבל הם פנימי' המוחי' והעולמות ע\"כ בכחם ע\"י עבודתם להוסיף אורות באצי', ואם גם בזה פגמו, אזי כשלג ילבינו ע\"י גורל דיוה\"כ שמעורר רצה\"פ כנ\"ל. יתר מכן דהיינו שעבר על כריתות ומב\"ד ג\"כ שאז אין מועיל לו גם התשו' דיוהכ\"פ כנ\"ל בענין לא יאבה ה' כו', וזהו אם יאדימו ל' מפעיל שמאדים אחרים, כי כמו שהקבעומ\"ש שהוא ענין גורל שבנפש הוא מקור לקבעומ\"צ שאח\"כ כמארז\"ל בתחלה יקבל עליו עומ\"ש<sup data-n=\"2384\">183</sup> ואח\"כ יקבל עליו עומ\"צ, ולכן נק' דרך הוי'<sup data-n=\"2385\">184</sup> שהוא דרך ומבוא לבחי' הוי', כן פריקת עומ\"ש הוא מקור לכל מיני רע כמ\"ש והתברך כו' ואח\"כ כי בשרירות לבי אלך כו', ולכן נק' אוילים מדרך פשעם<sup data-n=\"2386\">185</sup> שהוא דרך ומבוא לפשעים אלו המורדים, וכן נק' דרך רשעים<sup data-n=\"2387\">186</sup>, ולכן אין התיקון לזה כ\"א ע\"י המרירות כנ\"ל בענין תיסרך רעתך, ואז כצמר יהיו שהוא בחי' עתיקא כמבואר בסידור וכנ\"ל, ושני הפי' אמת שצריך לעורר בחי' יותר עמוק בנפש שהוא ע\"י היחידה כנ\"ל בענין תשובת ראב\"ד, ועכ\"ז כצמר יהיו שאין לבנינותו בהירה כ\"כ כי עדיין צריך מירוק וכנ\"ל בענין יסורין ממרקין<sup data-n=\"2388\">187</sup>.\nט) <b>ועכ\"ז</b> יש עצה לזה להגן מן היסורים, כי הנה יש בחי' תולע גם בקדושה, כי עולת תמיד<sup data-n=\"2389\">188</sup> עולת אותיות תולע<sup data-n=\"2390\">189</sup>, ותמיד סובל<sup data-n=\"2391\">190</sup> ב' פירושים לשון רציפות והתמדה, ולשון קביעות הזמן, וקאי על תורה ותפלה, כי בתורה נאמר והגית יומם ולילה<sup data-n=\"2392\">191</sup>, ותפלה כנגד תמידים תקנום<sup data-n=\"2393\">192</sup>, ולא שהכוונה שהמוחין דהשגת התורה והמדות דהתפעלות אהוי\"ר שבתפלה הוא התיקון לזה, כי מאחר דקיימינן באותו שכבר פגם את הרצה\"פ שבנפשו ג\"כ א\"כ כבר המוח והלב שלו פגומים ומטומטמים, ולא יהי' לו אהוי\"ר בתפלה, ולא יתאמת לו השגת התורה, רק דוקא אותיו' התורה והתפלה וכן אותיות סידור שבחו של מקום כי עלינו לשבח ג\"כ גימט' תולע<sup data-n=\"2394\">193</sup>, כי הנה מבואר במדרש ע\"פ אל תיראי תולעת יעקב<sup data-n=\"2395\">194</sup> כו' למה נמשלו",[["2384","183","<b>בתחלה יקבל עליו עומ\"ש</b>: ראה ברכות יג, א (במשנה)."],["2385","184","<b>דרך הוי'</b>: לשון הכתוב וירא יח, יט."],["2386","185","<b>אוילים מדרך פשעם</b>: תהלים קז, יז."],["2387","186","<b>דרך רשעים</b>: לשון הכתוב תהלים א, ו."],["2388","187","<b>ממרקין</b>: א:. . סי' ז' ובזה יתבארו כל הדקדוקים הנ\"ל דסי' א."],["2389","188","<b>עולת תמיד</b>: פינחס כח, ו."],["2390","189","<b>עולת אותיות תולע</b>: בלקו\"ת חוקת נז, ב מציין: בפע\"ח (שער ה' פ\"ג) ושם: ותולע יחזור לעולת. ראה גם אוה\"ת פינחס ע' א'קכב ושם: בעמה\"מ שער י\"א (כנצ\"ל: ש\"י) פ\"ו דנ\"ב ע\"ג. מ\"ח מסכת תפלת העשי' פ\"ד, מ\"ד. סידור האריז\"ל תפלת העשי' (פ' התמיד). שעה\"כ דרושי תפלת השחר דרוש ג."],["2391","190","<b>סובל</b>: א: נושא וסובל."],["2392","191","<b>והגית </b>[א ניתוסף: בו]<b> יומם ולילה</b>: יהושע א, ח."],["2393","192","<b>ותפלה כנגד תמידים תקנום</b>: ראה ברכות כו, ב. לקו\"ת פינחס עז, ג."],["2394","193","<b>עלינו לשבח ג\"כ גימט' תולע</b>: ראה גם אוה\"ת כאן ע' א'קפז. חוקת ע' תשסה. ע' תתי. סה\"מ תרכ\"ט כאן ע' שמו."],["2395","194","<b>אל תיראי תולעת יעקב</b>: ישעי' מא, יד. ראה תנחומא בשלח ט. זהר בראשית קעח, א. אוה\"ת חוקת כרך ו ע' א'תתעט. וש\"נ."]]],[4801940635,"כנס\"י לתולעת מה התולעת הזה אין כחו אלא בפיו שמכה ארזים בפיו, כך כנס\"י אין כחם אלא בפיהם, ופי' ארזים היינו הגסות כמארז\"ל מי שהגביה א\"ע כארז<sup data-n=\"2396\">195</sup> מה תקנתו ישפיל א\"ע כאזוב, כי הפר\"ע עיקרו בא מצד הגסות שהוא מקור כל מיני רע, ותקנתו להכות הארזים הוא בפיו דהיינו ע\"י אותיות התו' והתפלה, כי ארז\"ל שמט\"ט קושר כתרים<sup data-n=\"2397\">196</sup> לקונו מתפלותיהם של ישראל, כמו שאנ\"ר שכל הנמצאים נחלקים דרך כלל לד' סוגים כוללים דצח\"מ, והדומם למטה מכולם והמדבר הוא למעלה מכולם, והם כנגד ד' יסודות<sup data-n=\"2398\">197</sup> ארמ\"ע<sup data-n=\"2399\">198</sup> ואנו רואים שהכתר הוא מאבנים שהוא דומם היותר אחרון במדריגה ונעשית<sup data-n=\"2400\">199</sup> כתר על מין היותר גבוה דהיינו על ראשו של מלך שהוא הגבוה ומשובח שבמין המדבר ועי\"ז נעשה מלך דוקא, אך באמת לא מכל הדוממין עושין כן כ\"א דוקא מאבנים טובות שהן בהירות ומאירות דוקא, כי זהו דבר פלא שהדומם שעיקרו יסוד העפר יהי' מבהיק כאש שהוא היסוד היותר נעלה ויהי' מנוקה כ\"כ מהעפרורית, ולכן הוא יותר משובח מהמדבר בעצם, ולכן עושין מזה דוקא כתר ועטרה, וכן בנפש האדם יש בחי'<sup data-n=\"2401\">200</sup> אלו, הדומם הוא האותיות והצומח הם המדות שצומחים מקטנות לגדלות, והחי הוא השכל שמתנענע ממקום למקום, היינו מחסדים לגבו', והמדבר הוא עצם החכ', ולעשות כתר הוא שינוי רצון למי שפגם בכח הרצון שבנפשו, וכן למעלה פגם בבחי' הרצה\"פ כנ\"ל בענין לא יאבה כו', ולעשות רצון מחדש כמו יהי רצון הוא דוקא ע\"י אותיות התורה והתפלה וסידור שבחיו של מקום שמעורר את אותיות עצמיי' שבנפש, כי הנפש מליאה אותיות<sup data-n=\"2402\">201</sup>, ודוקא כשהם מנוקים מעפרורית והגשמה ומבהיקים כאש, דהיינו שהם בתכלית הביטול והשפלות וההכנעה כפי' הפשוט של תולע כמ\"ש ואנכי<sup data-n=\"2403\">203</sup> תולעת<sup data-n=\"2404\">202</sup> כו', וכמו ואלה שמות הגבורים כו' הוא עדינו העצני וארז\"ל שהי' מעדן עצמו כתולעת<sup data-n=\"2405\">204</sup>, ועי\"ז יוכל לתקן בחי' תולע שבלעו\"ז ויגן מן היסורים ויוליד רצון מחדש למעלה לתקן נפשו ולעורר עליו ר\"ר ממקור הרחמים, ויטהר נפשו באזוב כמארז\"ל מה תקנתו ישפיל א\"ע כאזוב כו', ועי\"ז תכבסני באזוב ואטהר<sup data-n=\"2406\">205</sup> כו'.",[["2396","195","<b>מי שהגביה א\"ע כארז</b>: ראה פסיקתא דר\"כ פ' פרה (לה, א)."],["2397","196","<b>שמט\"ט קושר כתרים</b>: ראה זהר בראשית לז, ב. הנסמן בסה\"מ תש\"ח ע' 202."],["2398","197","<b>דצח\"מ. . ד' יסודות ארמ\"ע</b>: ראה ע\"ח שער קיצור אבי\"ע ש\"נ, פ\"י. סה\"מ תרל\"ח ע' לח הערה 120."],["2399","198","<b>ארמ\"ע</b>: א ניתוסף: כי הדומם עיקרו יסוד העפר וצומח עיקרו הוא יסוד המים והחי עיקרו יסוד הרוח והמדבר עיקרו יסוד האש, ובמ\"א מבואר שהחי עיקרו יסוד האש והמדבר עיקרו יסוד הרוח כי באמת יש בזה שני שיטות ושניהן אמת כמ\"ש במ\"א."],["2400","199","<b>במדריגה ונעשית</b>: שם: והסוג היותר פחות וגרוע נעשה."],["2401","200","<b>יש בחי'</b>: שם: יש ד' בחי'."],["2402","201","<b>הנפש מליאה אותיות</b>: ראה ע\"ח שער טנת\"א ש\"ה, פ\"ג. לקמן מאמר ד\"ה אם בחוקותי הג' ובהערה 42."],["2403","203","<b>ואנכי תולעת</b>: א: תולעת יעקב — ישעי' מא, ד."],["2404","202","<b>ואנכי תולעת</b>: תהלים כב, ז."],["2405","204","<b>ואלה שמות הגבורים. . מעדן עצמו כתולעת</b>: שמו\"ב כג, ג [ושם: אלה]. ראה מוע\"ק טז, ב."],["2406","205","<b>תכבסני </b>[א: תחטאני]<b> באזוב ואטהר</b>: תהלים נא, ט."]]],[4801940107,"<b>מאת הרה\"ח ר' הלל נבג\"מ זכותו יגן עלי ועכ\"י א\"ס, </b>\nשנת ש\"ש אנכי על רב טו\"ב לבית ישראל"],[4801940171,"<b>ענין</b><sup data-n=\"2407\">1</sup> התפילות<sup data-n=\"2408\">2</sup> דיוהכ\"פ, כתוב בסידור<sup data-n=\"2409\">3</sup> שהוא כנגד ה' חסדים, וכפי שחשבתי מקדם<sup data-n=\"2410\">4</sup> סדרם בפרט הוא כך, תפלת ערבית כנגד חסד שבהוד דע\"י, כי מדת לילה הוא בחי' מל'<sup data-n=\"2411\">5</sup> ואיהי בהוד<sup data-n=\"2412\">6</sup>, משא\"כ תפלת שחרית הוא מדת יום שהוא בחי' ז\"א<sup data-n=\"2413\">7</sup> ואיהו בנצח<sup data-n=\"2414\">8</sup>, לכן התפלה הוא כנגד חסד שבנצח דע\"י כו', ותפלת מוסף הוא כנגד חסד שבת\"ת דע\"י, וידוע דת\"ת הוא כולל כל המדות<sup data-n=\"2415\">9</sup> ולכן נק' תפארת מל' פארות וענפים לכן בו עיקר העבודה בז\"פ כורעים<sup data-n=\"2416\">10</sup>, גם כל סדר העבודה אומרים בתפלה זו, ותפלת המנחה הוא כנגד חסד שבגבורה דע\"י ותפלת נעילה הוא כנגד חסד שבחסד דע\"י כו'.\n<b>עתה</b> נפל במחשבתי שאפשר לומר באופן אחר, ע\"ד העליות דלע\"ל [כי יוהכ\"פ מעין לע\"ל<sup data-n=\"2417\">11</sup> ], ולעתיד כתי' ישכיל עבדי<sup data-n=\"2418\">12</sup> ירום ונשא וגבה מאד, וכתוב בב\"ז<sup data-n=\"2419\">13</sup> שהוא כנגד חכ\"ס וגולגלתא וחג\"ת דע\"י ושם כתוב לאמר שמאד הוא מסט' דיעקב הוא עלי' היותר גבוה, וכפ\"ז<sup data-n=\"2420\">14</sup> נוכל לומר שגם כאן הוא כן, והנה חכ\"ס וגולגלתא הגם שבהם מלובש חו\"ג דע\"י<sup data-n=\"2421\">15</sup> מ\"מ א\"א לומר שמהות המדות מלובשי' בהם כי הם נבדלים בערך רק ע\"כ אינו מאיר בהם רק הארת המדות ונוכל לקרות הארה זאת בשם נו\"ה דעשי' [כי אעפ\"י שההארה היא בחי' חו\"ג מ\"מ מאירים ע\"י החסדים שבנו\"ה דע\"י כו' וד\"ל]. וזהו כנגד תפלת ערבית ושחרית וכפ\"ז תפלת מוסף הוא כנגד חסד שבחסד דע\"י ולהיות החסד שבחסד כולל כל החסדים לכן נאמר בתפלה זו עיקר העבודה כנ\"ל, ותפלת המנחה כנגד חסד שבגבורה דע\"י כו', וזהו שתי עליות דונשא וגבה, ותפלת נעילה הוא כנגד ת\"ת דע\"י שזהו העלי' הנק' מאד כו'. וההפרש בין הכוונות אינו רק בתפלת מוסף ונעילה, שלפי פי' הא' מוסף בת\"ת ונעילה בחסד ולפי פי' הב' מוסף בחסד ונעילה בת\"ת כו', ואפשר לומר ששניהם אמת כו' וד\"ל.",[["2407","1","<b>ענין התפילות דיוה\"כ</b>: מאמר זה הוא כנראה מר' הלל וכנרשם בהכותרת."],["2408","2","<b>התפילות</b>: בסידור שבהערה הבאה לאחרי הפתיחה אומר: הנה שרש ענין חמש תפלות יו\"כ. ואולי גם כאן צ\"ל: ה' תפילות."],["2409","3","<b>בסידור</b>: שער יוה\"כ רנ, סע\"ד ואילך."],["2410","4","<b>מקדם</b>: אוצ\"ל מקודם."],["2411","5","<b>לילה. . מל'</b>: ראה זהר בא לח, ב."],["2412","6","<b>ואיהי בהוד</b>: ראה ע\"ח שער אנ\"ך שי\"ט, פ\"ט. לקו\"ת שה\"ש כח, ב ובהנסמן במ\"מ לשם. מאמרי אדה\"ז הקצרים ע' ה. מאמרי אדה\"א נ\"ך ע' מ. וש\"נ."],["2413","7","<b>יום. . ז\"א</b>: טעמי המצות להאריז\"ל פ' בראשית. קהלת יעקב מערכת יום בשם הזהר."],["2414","8","<b>ואיהו בנצח</b>: נסמן לעיל בהערה 6."],["2415","9","<b>דת\"ת הוא כולל כל המדות</b>: ראה לקו\"ת שה\"ש מז, ד. תו\"ח יתרו רנה, ג."],["2416","10","<b>בז\"פ כורעים</b>: כ\"ה בהכת\"י."],["2417","11","<b>יוהכ\"פ מעין לע\"ל</b>: ראה לקו\"ת להאריז\"ל נח ו, יג. מאמרי אדה\"א דברים ח\"ג ע' תתקיג. וש\"נ. תו\"ח וארא ח\"א עה, ד. וש\"נ."],["2418","12","<b>ישכיל עבדי</b>: ישעי' נב, יג."],["2419","13","<b>וכתוב בב\"ז</b>: וישב כג, א."],["2420","14","<b>וכפ\"ז</b>: וכפירוש זה."],["2421","15","<b>חכ\"ס וגולגלתא. . חו\"ג דע\"י</b>: ראה ע\"ח שער א\"א שי\"ג, פ\"ו ופ\"ז."]]],[4801940108,"<b>רשימה מדברים מאדמו\"ר זי\"ע יום ש\"ק פ' אמור שנת הנ\"ל [תקצ\"ח] בליבאוויטש</b>\n<b>ונקדשתי</b> בתוך בנ\"י<sup data-n=\"2422\">1</sup> אני הוי' מקדישכם<sup data-n=\"2423\">2</sup>. להבין איך יתקדש בתוך בנ\"י אשר לא נערוך אליו קדושתו<sup data-n=\"2424\">3</sup> וכמאמר כי קדוש אני קדושתי למעלה מקדושתכם<sup data-n=\"2425\">4</sup>, וגם קושי' זאת יקשה על מה שאנו אומרים נקדישך<sup data-n=\"2426\">5</sup> איך ביכולתינו להקדישו בקדושתו ולעשות בו קדושה כיון שאינה בערכנו כלל. ולהבין כל הנ\"ל י\"ל ענין ג\"פ קדוש שארז\"ל ע\"ז<sup data-n=\"2427\">6</sup> משל למלך שעשה שלש עטרות<sup data-n=\"2428\">7</sup> אחת הניח בראשו ושנים נתן בראש בניו. וגם להבין מארז\"ל בחולין שיש ג' כתות מלאכים<sup data-n=\"2429\">8</sup> כת א' אומרת קדוש וכת ב' אומרת קדוש קדוש וכת ג' אומרת ג\"פ קדוש ולמה לא יאמרו כל כת וכת ג\"פ קדוש. אך להבין ענין קדוש יש להקדים מה שנאמר בנזיר קדוש יהי' גדל פרע שער ראשו<sup data-n=\"2430\">9</sup> מה ענין גידול השער לקדושה.\n<b>וי\"ל</b> ענין השם שקורין רז\"ל לא\"ס בשם הקב\"ה שבודאי שם זה הוא מצד עצמותו ית' המתלבש בעולמות כי למהו\"ע אין שם שיכילהו ולא מצאו שם אחר שיכיל ענין התלבשותו ית' בעולמות, הענין הוא שאין התלבשות אוא\"ס ית' בעולמות ע\"ד התלבשות הנשמה בגוף שהתלבשותה הוא בקירוב הערך פי' שאע\"פ שעצם הנפש הוא רוחני ואינה בערך גשמי כלל מ\"מ בבואה בגוף נעשה ירידה והשפלה בעצם חיות הנפש [שהוא הארה מעצמות הנפש הנק' מקיפים] עד שמתמזג בחומר איברי הגוף בכל או\"א לפי ערכו<sup data-n=\"2431\">10</sup>, כמו בחומר המוח מתמזג עד שנעשה ממנו שכל וכן בחומר הלב נעשה ממנו מדות וראי' בעין ושמיעה באוזן והילוך ברגל, והטעם הוא לפי שחומר המוח הוא חומר דק וזך ולכן מקבל אור רוחני ביותר שהוא בחי' שכל כו' משא\"כ חומר הרגל שהוא חומר גס לכן יתגשם בו האור ביותר עד שנעשה ממנו הילוך, ונמצא זה מורה שיש שינויים בחיות הנפש מהתלבשותה בחומר שכל שהחומר יותר גס יפעול בו הגשמה ביותר, ועוד ראי' ממה שהנפש תתפעל ממאורעות הגוף כמו האכילה או רעבון שע\"י אכילה יתחזק חיבורה בגוף וע\"י",[["2422","1","<b>ונקדשתי בתוך בנ\"י</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nהנחה זו היא ממאמר ד\"ה זה שנדפס אח\"כ בלקו\"ת אמור לא, א. וראה בהנרשם במ\"מ לשם."],["2423","2","<b>ונקדשתי. . אני הוי' מקדישכם</b>: אמור כב, לב."],["2424","3","<b>לא נערוך אליו קדושתו</b>: פיוט יגדל. ראה תו\"א בשלח סב, ג. לקו\"ת (מטות פא, ב) יו\"כ ע, א. תו\"ח בשלח ח\"א קסג, א. וש\"נ."],["2425","4","<b>כי קדוש אני קדושתי למעלה מקדושתכם</b>: קדושים יט, ב. ויק\"ר פכ\"ד, ט."],["2426","5","<b>שאנו אומרים נקדישך</b>: נוסח הקדושה. ראה גם לקו\"ת שלח נא, ג."],["2427","6","<b>ע\"ז</b>: ניתוסף ע\"פ ד."],["2428","7","<b>משל למלך שעשה שלש עטרות</b>: ראה ויק\"ר פכ\"ד, ח. מאמרי אדה\"א הנחות תקע\"ז ע' עה. וש\"נ."],["2429","8","<b>בחולין שיש ג' כתות מלאכים</b>: צא, סע\"ב."],["2430","9","<b>קדוש יהי' גדל פרע שער ראשו</b>: נשא ו, ה."],["2431","10","<b>הנפש. . בחומר איברי הגוף. . לפי ערכו</b>: ראה לקו\"ש אמור כרך כז ע' 382."]]],[4801940172,"הרעבון יתחלש וכן מהעדר השינה יתבלבל כלי המוח וע\"י השינה יתחזק כו' וע\"כ לומר שהתלבשותה הוא בקירוב הערך, משא\"כ למעלה בענין התלבשות אוא\"ס בעולמות אע\"פ שמתצמצם בירידה והשפלה גדולה להוות העולמות יותר מהשפלת הנפש בגוף, כי הנפש אינה רק מחי' בלבד אבל חומר הגוף יש לו קיום בפ\"ע<sup data-n=\"2432\">11</sup> משא\"כ למעלה הוא מהוה בירידתו בעולמות אפי' בחי' היש כי ממך הכל<sup data-n=\"2433\">12</sup> כו', אעפ\"כ אין ירידה והשפלה זאת פועל בו שום שינוי כי באמת הוא קדוש ומובדל אפי' אחר התלבשותו להיות מהוה העולמות כמו קודם שנברה\"ע ממש בלי שום שינוי כלל, וכן אע\"פ שהוא קדוש ומובדל מ\"מ הוא מהוה העולמות ע\"י התלבשותו בהם. וזהו אין קדוש כהוי'<sup data-n=\"2434\">13</sup> כי כל הקדושות מורים על הבדלת הערך כמו הרוחני' עם הגשמי' שאין הגשמי' בערך הרוחני' [ולכן אין עצם הרוחני מתחבר רק הארתו בלבד] אבל הוא ית' אע\"פ שהוא קדוש מ\"מ הוא הוי' מהוה מאין ליש ממש, ונמצא שב' בחי' אלו והוא מה שהוא קדוש ומובדל ומה שהוא מתלבש בעולמות אין זה שני דברים נבדלים כלל ח\"ו רק בחי' א' ממש, כי עצמות קדושתו הוא המתלבש בעולמות ואעפ\"כ אין התלבשות פועל שום שינוי ח\"ו כי גם אחר ההתלבשות הוא קדוש ומובדל כמו קודם שנברה\"ע ממש [וזהו הוא מקומו ש\"ע<sup data-n=\"2435\">14</sup> ואין העולם מקומו איהו תפיס כו' ולמדת\"ב<sup data-n=\"2436\">15</sup> שאע\"פ שהוא מקומו ש\"ע מ\"מ בבחי' זאת עצמו אין העולם מקומו ואע\"ג דאיהו תפיס כו' מ\"מ למדת\"ב דבבחי' דאיהו תפיס בזה עצמו למדת\"ב ואין זה שני בחי' כלל וזהו הקב\"ה ולא קדוש וברוך כו'].\n<b>אך</b> א\"כ הדבר שאין התלבשות הנפש בגוף דוגמא כלל לבחי' התלבשות אוא\"ס ית' בעולמות א\"כ למה ארז\"ל מה הקב\"ה ממלא את כל העולם אף הנשמה<sup data-n=\"2437\">16</sup> ממלאה את<sup data-n=\"2438\">17</sup> כל הגוף דמשמע שהם בדוגמא אחת. אך הענין הוא שיש ב' בחי' גילוי אור ושפע מאא\"ס ית' בעולמות הא' הוא בחי' סוכ\"ע שעז\"א את השמים ואת הארץ אני מלא<sup data-n=\"2439\">18</sup> בהשוואה כי הוא שורה בהעלם למעלה ולמטה כא'<sup data-n=\"2440\">19</sup> וכמאמר והקדוש בשמים ובארץ<sup data-n=\"2441\">20</sup> שכמו שהוא קדוש בארץ כ\"ה קדוש בשמים בהשוואה א' ממש, ובבחי' התלבשות זאת שמתלבש בהם בהעלם בהשוואה א' בזה גופא מהוה את כולם כא' ממש [והיינו ע\"י שנותן כח ועוז בממכ\"ע כמשי\"ת וכמבואר בענין ביאור המאמר אנת הוא שלימו<sup data-n=\"2442\">21</sup> כו'], אך א\"כ הי' התהוות כללות היש בלתי ריבוי והתחלקות כלל",[["2432","11","<b>חומר הגוף יש לו קיום בפ\"ע</b>: ראה סידור ערב שבת קסה, ד ואילך. אוה\"ת וירא כרך ד ע' תשמב. סה\"מ עזר\"ת ע' קסה."],["2433","12","<b>כי ממך הכל</b>: דהי\"א כט, יד."],["2434","13","<b>אין קדוש כהוי'</b>: שמו\"א ב, ב."],["2435","14","<b>הוא מקומו ש\"ע</b>: ראה ב\"ר פס\"ח, ט. הנסמן בתו\"ח בראשית מג, א הערה 2. סה\"מ תרכ\"ט ע' קסט. וש\"נ."],["2436","15","<b>איהו תפיס כו' ולמדת\"ב</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. תו\"ח נח סו, ג הערה 30."],["2437","16","<b>מה הקב\"ה. . אף הנשמה</b>: ראה ברכות י, א."],["2438","17","<b>את</b>: ניתוסף ע\"פ ד."],["2439","18","<b>את השמים. . מלא</b>: ירמי' כג, כד. ראה גם לקמן מאמר ד\"ה את שבתותי תקצ\"ח ובהערה 85."],["2440","19","<b>כא'</b>: אב: כבפנים. ד: בהשוואה [וממעל לתיבה זו כתב: ד\"ר ד' רוחות] כא' ממש."],["2441","20","<b>והקדוש בשמים ובארץ</b>: ראה ברכת ישתבח. מאמרי אדה\"א שמות ח\"ב ס\"ע תכב. וש\"נ. דברים ח\"א ע' קפג. וש\"נ."],["2442","21","<b>ביאור המאמר אנת הוא שלימו</b>: הוא ד\"ה לה\"ע המאמר ואנת הוא שלימו דכולהו מיום ו' פ' אמור תקצ\"ח שנאמר לפני מאמר זה. הנחת ר' הלל יודפס בע\"ה בספרו פלח הרמון. ראה אוה\"ת בראשית כרך ד' ס\"ע תשמו ואילך."]]],[4801940230,"וגם לא הי' שום גילוי מאתו ית' בעולמות, אך יש עוד בחי' א' והוא הנק' ממכ\"ע שהוא בחי' גילוי אור הנמשך מאתו ית' להחיות העולמות וגם מבחי' זאת נמצא מציאות העולמות בריבוי והתחלקות כמאמר אלף אלפים ישמשוני'<sup data-n=\"2443\">22</sup> מספר גדוד א' ולגדודיו אין מספר וכן געה\"ע וגעה\"ת שבכאו\"א יש ריבוי מדריגות לאין שיעור, וזהו שני בחי' דמחי' ומהווה כי ההתהוות הוא מבחי' סוכ\"ע שנותן כח ועוז בבחי' הנק' ממכ\"ע להוות ריבוי רבבות עולמות לאין שיעור, ובחי' מחי' הוא בחי' ממכ\"ע שהוא מה שנמשך גילוי אוא\"ס ב\"ה וית'<sup data-n=\"2444\">23</sup> בבחי' העולמות בבחי'<sup data-n=\"2445\">24</sup> גילוי ממש והיינו שבחי' עולמות ירגישו מציאותו איך שהוא מחי' ומהוה אותם בתמידות ובלעדו המה אין ואפס ממש, ובחי' זאת דממכ\"ע היא הבאה בסדר והדרגה בכל עולם ועולם לפי\"ע בעולם האצי' איהו וחיוהי כו' וגרמוהי כו' חד<sup data-n=\"2446\">25</sup> בתכלית ובבי\"ע המה בבחי' ביטול היש בלבד וגם בהם יש חילוקי מדריגות לאין שיעור מצד מיעוט האור ממדריגה למדריגה כו' בבחי' הארה והארה דהארה כו'. והנה בבחי' זאת שמחי' העולמות הוא בדוגמת הנשמה הממלאה את הגוף שהיא באה בחילוקי מדריגות ג\"כ בכל אבר לפי מזגו ותכונתו וע\"ז ארז\"ל מה הקב\"ה כו'.\n<b>והנה</b> שני מדריגות אלו הוא בחי' עדאתכ\"ס ועדאת\"ג כי עלמא דאתכסי' הוא מה שנמצא בהעלם בעולמות [שהוא בחי' מה שנק' הקב\"ה כנ\"ל כו'] ועדאת\"ג הוא מה שנמשך בבחי' גילוי להחיותם [... שזהו בחי' שכינה וכמאמר ושכנתי בתוכם<sup data-n=\"2447\">26</sup> כו']. והנה על בחי' עדאת\"ג נאמר ומבשרי אחזה אלוק<sup data-n=\"2448\">27</sup>, שמבחי' הנשמה שבגוף נוכל לראות בעין השכל בבחי' גילוי ממש בחי' אלקות המחי' ומהוה כל העולמות שכמו שחיות הנפש בגוף אינו מושג מהותו כלל בשום אופן ואעפ\"כ נרגש מציאותו בבירור גמור כמו שרואה בעין ממש כך ע\"י ראית העין על עולמות הגשמיי' כמו שמים וארץ הגשמיי' וראיית עין השכל בעולמות הרוחני' מזה ירגיש מציאות<sup data-n=\"2449\">28</sup> הבורא המחי' ומהוה אותם כאלו רואה בעיניו ממש, אך הרגשת המציאות זה הוא רק בחי' זיו והארה האלקי' המחי' ומהוה את כל העולמות אך מבחי' ראי' זאת יעלה ויגיע למדריגה יותר נעלה מזה והוא בחי' לאסתכלא ביקרא דמלכא<sup data-n=\"2450\">29</sup> שהוא בחי' רוממות והפלאת עצמות אוא\"ס איך שהוא נשגב לבדו ונבדל בערך מבחי' השתלשלות [ובזה יתפרש מבשרי אחזה אלק ממש כו'], אך איך יגיע מבחי' ראית עין השכל בחיות האלקי המלובש בהשתלשלות שהוא רק זיו והארה מעצם המהות דאוא\"ס ואיך יגיע מזה לבחי' הראי' והסתכלות ברוממות עצם המהות [שנק' יקרא",[["2443","22","<b>אלף אלפי' ישמשוני'</b>: דניאל ז, י. חגיגה יג, ב."],["2444","23","<b>ב\"ה וית'</b>: אב: ב\"ה. ד: ית'."],["2445","24","<b>העולמות בבחי'</b>: ניתוסף ע\"פ ד. אב: כבפנים."],["2446","25","<b>איהו וחיוהי. . כו' </b>[ד: ליתא]<b> חד</b>: ראה ת\"ז בהקדמה ג, ב."],["2447","26","<b>ושכנתי בתוכם</b>: תרומה כה, ח."],["2448","27","<b>ומבשרי אחזה אלוק</b>: איוב יט, כו."],["2449","28","<b>ירגיש מציאות</b>: אב: כבפנים. ד: יורגש כח."],["2450","29","<b>לאסתכלא ביקרא דמלכא</b>: ראה זהר מקץ קצט, א. בראשית לח, א-ב. פקודי רמז, ב. תרומה קלד, א."]]],[4801940283,"דמלכא], הענין הוא שיש בבחי' אור וזיו ג\"כ ב' בחי' הא' בחי' גילוי הזיו דאוא\"ס להחיות העולמות שבא ונמשך בדרך השתלשלות הארה והארה דהארה כו' והב' התכללות האור והזיו הזה במקורו שהוא עצם המהות דאוא\"ס שנק' מאור, וזהו כי נשגב שמו לבדו<sup data-n=\"2451\">30</sup> שגם שמו שהוא בחי' אור וזיו נשגב לבדו מצד שנכלל ובטל בעצם המהות דאוא\"ס ורק הודו שהוא בחי' גילוי הארה והארה דהארה הוא המתגלי' על ארץ ושמים להחיותם ומזה הוא מקור חיותם והתהוותם מאין ליש, וזהו ג\"כ מ\"ש כי עמך מקור חיים<sup data-n=\"2452\">31</sup> ולא כתיב כי אתה מקור חיים, דא\"כ הוה משמע שהוא בעצמו ית' הוא מקור החיים אבל באמת אינו כן דאפי' מקור הכללי דחיות כל העולמות שהוא בחי'<sup data-n=\"2453\">32</sup> חכ' דאצי' הוא ג\"כ עמך בטל וטפל אליך להיותו בחי' אור וזיו בלבד וטבע הזיו ליכלל וליבטל במקורו כו' וד\"ל.\n<b>ועם</b> זה יובן ענין מבשרי אחזה הנ\"ל שאע\"פ שתחלת הראי' בעין שכלו הוא בבחי' הארה מעצמות אלקות בלבד המחי' ומהוה את כל העולמות שנק' מקור חיים כנ\"ל מ\"מ מצד שבחי' מקו\"ח שהוא האור והזיו הוא נכלל ומתייחד במקורו שהוא עצם המאור לכן אחרי הראי' דהשתלשלות יעלה ויגיע למדריגת לאסתכלא ביקרא דמלכא שהוא רוממות עצם המאור כו' וד\"ל. והנה ידוע דמדריגת לאסתכלא הנ\"ל שהוא בחי' העלאה מלמטה למעלה אין זה עדיין תכלית הכוונה, רק פנימי' הכוונה להיות לו דירה בתחתונים שהוא בחי' המשכת גילוי המאור מלמעלה למטה [וזהו בחי' גילוי המאור באור בחי' גילוי הסובב בממלא ולא בחי' ביטול והתכללות האור במאור שהוא בחי' התכללות הממלא בסובב כו' וד\"ל]. והנה המשכת הגילוי הזה א\"א להיות רק ע\"י תומ\"צ בגשמיות שע\"י נתגלה בחי' סובב בממלא.\n<b>והנה</b> עם זה יובן מה שנאמר בנזיר קדוש יהי' גדל פרע שער ראשו, כי בחי' התגלות הסובב בממלא נק' בחי' שערות ומבשרי אחזה שיש ב' מיני שפע וחיות הנמשך מן המוח, הא' המשכת החיות ממנו בכל האיברים שבא בקירוב ובבחי' התקשרות עם כל האיברים ע\"י גידי המוח עד שבהחתך באיזה אבר אפי' בצפרני הרגל ירגיש במוח איזה כאב ושפע הזאת באה בדרך עו\"ע כו', והמשכה הב' הוא מה שנמשך מן המוח בחי' שערות שזהו מותרות<sup data-n=\"2454\">33</sup> בעלמא שאינו נוגע כלל לפנימי' החיות שבמוח עד שבהחתך אותם לא יכאב כלל ולא ירגיש במוח כלל אבל מ\"מ יש להם יניקה מן המוח ושייכות אליו וראי' שבהמשכתם ירגיש במוח ויניקתם הוא דרך גומות שבראש כו', ככה למעלה כבי' המשכות החיות דממכ\"ע בעולמות הוא בא בקירוב הערך עד\"מ חיות המוח באברים כנ\"ל ושפע זאת בא בדרך השתלשלות ממדריגה למדריגה עד שמתמעט האור וחיות במיעוט אחר מיעוט כו'. אכן המשכת בחי' סוכ\"ע שהוא בחי' המהו\"ע דאוא\"ס א\"א לעולמות לקבל המשכה וגילוי זאת בקירוב הערך רק שבא ונמשך בדרך דילוג הערך ולכן התגלות זאת נק' בשם",[["2451","30","<b>כי נשגב שמו לבדו</b>: תהלים קמח, יג."],["2452","31","<b>כי עמך מקור חיים</b>: תהלים לו, י."],["2453","32","<b>בחי'</b>: ניתוסף ע\"פ ד."],["2454","33","<b>שערות שזהו מותרות</b>: ראה מאמרי אדה\"א ויקרא ח\"ב ע' תשעח. וש\"נ. נ\"ך ס\"ע קעו ואילך. תו\"ח ח\"ש קכג, סע\"ג ואילך."]]],[4801940333,"שערות, וזהו וע\"י יתיב כו' שער רישי' כעמר נקי<sup data-n=\"2455\">34</sup> פי' ע\"י הוא בחי' סוכ\"ע שנעתק מבחי' יומין עילאין כמאמר המתנשא מימות עולם כי ימות עולם הוא בחי' ששת ימים דז\"א<sup data-n=\"2456\">35</sup> שהוא בחי' מדות עליונות שנמשכים בבחי' מקור להחיות ולהוות כל העולמות ביום הראשון נמשך בחי' חסד דז\"א במאמר יהי אור<sup data-n=\"2457\">36</sup> כו' וכמאמר ששת ימים כו' שית יומין עילאין דבהון עביד קוב\"ה שו\"א<sup data-n=\"2458\">37</sup> וכו' ובחי' זאת נק' ממכ\"ע אבל בחי' סוכ\"ע שהוא מהו\"ע אוא\"ס ית' הוא נעתק ומובדל מבחי' זאת דממכ\"ע ולכן נק' עתיק יומין שנעתק ומובדל מבחי' יומין<sup data-n=\"2459\">38</sup> עילאין דז\"א ונק' קדוש כנ\"ל, ולכן ההתגלות ממנו הוא בבחי' שערות בלבד, וזהו ושער רישי' שזהו בחי' התגלות שלו בעולמות שנק' ושער רישי' בלבד כו' וד\"ל. והנה בחי' המשכות קדושתו ית' בעולמות הוא בבחי' שערות כנ\"ל אנו ממשיכין ע\"י תומ\"צ שאנו עושין בגשמי' והעיקר ע\"י סומ\"ר שאנו מקדשין ומבדילין עצמינו מדבר האסור [או אפי' מדבר המותר וכמאמר קדש עצמך במותר<sup data-n=\"2460\">39</sup> כו'] ועי\"ז אנו ממשיכין בחי' קדושתו העצמי' עלינו ע\"י מעהמ\"צ וכמו שאנו מברכין אשר קדשנו במצותיו<sup data-n=\"2461\">40</sup>, ולכן גם הנזיר שהזיר א\"ע מן היין וקידש א\"ע להיות קדוש ומובדל מתאוות שתיית היין כו' ועי\"ז נתעלה להיות כלי לבחי' המשכות קדושתו ית' שהוא בחי' המשכות מהו\"ע ית' הנמשך ומתגלה בבחי' שערות בלבד ולכן צריך לעשות כדוגמא עליונה שהוא בחי' גידול פרע שער וזהו קדוש יהי' גדל פרע שער ראשו כו' וד\"ל, וזהו מה שנאמר בו איש כי יפליא לנדור<sup data-n=\"2462\">41</sup> כו' שממשיך עליו מבחי' פלא העליון קדושת המהו\"ע ית' כו' וד\"ל.\n<b>ומעתה</b> י\"ל מארז\"ל בענין ג' כתות הנ\"ל שכת א' אומרת פ\"א קדוש כו', כי הנה ידוע שיש ג' בחי' שרפים בבריאה וחיות ביצי' ואופנים בעשי'<sup data-n=\"2463\">42</sup>, אך יש בכל עולם בפרט ג' בחי' דשרפים ואופנים וחיות [כמבואר בביאור דאני לדודי כו' יעו\"ש<sup data-n=\"2464\">43</sup> ] ובחי' השרפים שבכל עולם המה האומרים קדוש<sup data-n=\"2465\">44</sup> [כי אופנים וחיות אומרים ברוך כו' וכמאמר והאופנים כו' מתנשאים כו' ואומרים ברוך<sup data-n=\"2466\">45</sup> כו'] אך השרפים",[["2455","34","<b>וע\"י. . כעמר נקי</b>: דניאל ז, ט."],["2456","35","<b>המתנשא מימות עולם. . דז\"א</b>: ע\"פ ברכת יוצר. ראה זהר ויקרא טו, א. מאמרי אדה\"א ויקרא ח\"א ע' רכה. וש\"נ."],["2457","36","<b>חסד. . יהי אור</b>: בראשית א, ג. ראה גם אוה\"ח לזהר בראשית מו, א. מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. תו\"ח תצוה ח\"ב שיט, א. וש\"נ."],["2458","37","<b>ששת ימים. . עביד קוב\"ה שו\"א</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ."],["2459","38","<b>עתיק יומין שנעתק ומובדל מבחי' יומין</b>: ראה לקו\"ת כאן לא, ד. שלח לט, ד. שעה\"י קכו, א ובהערה 5."],["2460","39","<b>קדש עצמך במותר</b>: ספרי ראה יד, כא. יבמות כ, א. ראה שע\"ת נז, ב ובהערה 20."],["2461","40","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."],["2462","41","<b>איש כי יפליא לנדור</b>: נשא ו, ב [בדילוג — ראה שאילתות בחוקותי ריש שאילתא קיו. סהמ\"צ להצ\"צ ע' מד]."],["2463","42","<b>שרפים. . ואופנים בעשי'</b>: ראה סידור שער האלול רל, א. מאמרי אדה\"א ויקרא ח\"א ע' מד. וש\"נ. לעיל ע' פ. וש\"נ."],["2464","43","<b>בביאור דאני לדודי כו' יעו\"ש </b>[ב' תיבות אחרונות ליתא בב]: נדפס בסידור שבהערה שלפנ\"ז."],["2465","44","<b>השרפים. . האומרים קדוש</b>: ישעי' ו, ג. ראה תוס' שבהערה שלאח\"ז."],["2466","45","<b>אופנים וחיות אומרים ברוך. . והאופנים. ֿ. ברוך</b>: ברכת יוצר. יחזקאל ג, יב. ראה תוד\"ה ברוך חולין צב, רע\"ב."]]],[4801940380,"דבריאה אומרים פ\"א קדוש ודיצי' ב\"פ קדוש ודעשי' ג\"פ קדוש כו'. והנה להבין בחי' השרפים דבריאה האומרים פ\"א קדוש, הנה ידוע בענין יוצר אור ובורא חושך<sup data-n=\"2467\">46</sup> שעולם הבריאה הוא בחי' חושך והעלם ונק' עלמין סתימין דלא אתגלייין<sup data-n=\"2468\">47</sup> כו' ושרשו בבחי' התכללות האור כמו שהוא נכלל בעצם המאור ולכן בחי' השרפים דבריאה משיגים קדושתו ית' איך שהוא קדוש ומובדל מגדר גילוי אור עד שכל מיני הארות וגילויים הנמשכים ממנו המה בטלים ונכללים בעצמות ממש עד שאין עוד מלבדו לאחר שנברה\"ע כמו קודם שנברה\"ע בלי שום שינוי כלל [... והשגתם בבחי' זאת הוא מצד שמאיר בהם חב\"ד דאצי' כידוע דאימא עילאה בתלת ספירן מקננא בעולם הבריאה<sup data-n=\"2469\">48</sup> כו'], והנה ע\"י השגה זאת נמשך בהם תשוקה ברשפי אש לצאת מגדר הכלי שלהם ולהיות נכללים ובטלים באוא\"ס הסוכ\"ע ותשוקה זאת פועל בהם ביטול היש מכל וכל לכן נק' שרפים [ע\"ש שריפה<sup data-n=\"2470\">49</sup> וכיליון מבחי' היש שלהם לגמרי כו'] ולכן נאמר שרפים עומדים ממעל לו<sup data-n=\"2471\">50</sup> ממעל לשכינתא פי' שכינה הוא בחי' ממכ\"ע שהוא בחי' זיו והארה המחי' את כל העולמות בכאו\"א לפי מדריגתו ולהיות שתשוקתם ליכלל באוא\"ס הסוכ\"ע לזאת הוא כאלו הם עומדים ממעל לשכינתא כו' [... כידוע בענין מאמר הזוהר מאן דכסיף אע\"ג דלא יכיל<sup data-n=\"2472\">51</sup> שבחא איהו וכידוע בשם הבעש\"ט נ\"ע דבכ\"מ שהמח' והרצון מקושרים<sup data-n=\"2473\">52</sup> שם הוא כל הנפש כו'], ויתפרש ג\"כ ממעל לו' שהוא בחי' המדות דאצי'<sup data-n=\"2474\">53</sup> מקור הזיו דממכ\"ע כו'.\n<b>והנה</b> להבין ענין התשוקה שבהם ליכלל בבחי' סוכ\"ע שזהו בודאי בחי' הארת הסובב המאיר עליהם אע\"פ שהם נבראים מאין ליש יובן דוגמא לזה מענין קי\"ס, דהנה ידוע דים ויבשה הוא עלמא דאתכסי' ועדאת\"ג<sup data-n=\"2475\">54</sup> וכמו ההפרש למטה בים הגשמי שכל הנבראים שבים שהוא בחי' דגים שבים המה נכללים במקורם שהוא הים המכסה עליהם מכל צד וכל עיקר חיותם הוא מן המים וכאשר פורשים מיד מתים, כך הוא נשמות ומלאכים עליונים שבבחי' עלמא דאתכסי' המה מובלעים בתכלית הביטול במקורם וכמו נשמת מרע\"ה דכתיב בו מן המים משיתיהו<sup data-n=\"2476\">55</sup> [... וע\"כ",[["2467","46","<b>יוצר אור ובורא חושך</b>: ישעי מה, ז. ראה פע\"ח שער הק\"ש ש\"ח, פ\"א. הנסמן בתו\"ח בשלח ח\"א קמד, ג הערה 41. סה\"מ תרכ\"ז ע' רפו. וש\"נ."],["2468","47","<b>עלמין סתימין דלא אתגליין</b>: ת\"ז בהקדמה יז, א."],["2469","48","<b>דאימא עילאה. . מקננא בעולם הבריאה</b>: תניא פל\"ט בשם התיקונים — ת\"ז ת\"ו כג, א. ראה מאמרי אדה\"א דברים ח\"א ע' רסב. וש\"נ. קונטרסים ע' תכג. וש\"נ."],["2470","49","<b>שרפים [ע\"ש שריפה</b>: ראה סה\"מ תרל\"ח ע' טז הערה 138."],["2471","50","<b>שרפים עומדים ממעל לו</b>: ישעי' ו, ב. ראה זהר אחרי עט, ב. הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתקמח. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 221. סה\"מ תרל\"ח ע' טו הערה 136 (ושם גם בשם הבעש\"ט)."],["2472","51","<b>מאן דכסיף אע\"ג דלא יכיל</b>: ראה זהר נח סט, ב."],["2473","52","<b>בשם הבעש\"ט נ\"ע דבכ\"מ שהמח' והרצון מקושרים</b>: ראה גם לקמן מאמר ד\"ה וספרתם הה' ובהערה 222."],["2474","53","<b>ממעל לו'. . המדות דאצי'</b>: ראה פלח הרמון תרומה ע' רצג."],["2475","54","<b>דים ויבשה הוא עלמא דאתכסי' ועדאת\"ג</b>: ראה לעיל ע' פב. וש\"נ. מאמרי אדה\"א שמות ח\"א ע' חצר. וש\"נ."],["2476","55","<b>מן המים משיתיהו</b>: שמות ב, י."]]],[4801940424,"שלא הי' אפשר לו לפרוד מבחי' ביטולו במקורו ולכן לא רצה בענין השליחות כו' באמרו כי כבד פה<sup data-n=\"2477\">56</sup> כו'] וכן כל ת\"ח שנמשלו לדגים שבים<sup data-n=\"2478\">57</sup> כו', אבל בחי' יבשה למעלה הוא ע\"ד דוגמא יבשה הגשמי שכל הנבראים המתהווים ממנה המה נפרדים ממקורם וחיותם הוא ג\"כ מדברים אחרים שיוכלו לחיות באויר זמן רב, כך למעלה בחי' נשמות ומלאכים שבבחי' עלמא דאתגלי' אע\"פ שעובדים ה' באהוי\"ר מ\"מ זה גופא הוא בחי' יש, מציאות אה' ומציאות יראה רק שבהעלם מלובש באהוי\"ר זאת הביטול לאין האלקי כו', והנה כאשר הפך ים ליבשה<sup data-n=\"2479\">58</sup> שהים נתגלה ביבשה או שהיבשה נכללה בים ויהי' איך שיהי' הרי נתגלה מציאות הביטול שבנשמות ומלאכים הכלולים בימא עילאה ונתגלה ביטול זה בנבראים שביבשה עד שגם בהם נמשך ונתגלה בחי' ביטול מהותם לגמרי מכל וכל כו' וד\"ל.\n<b>והנה</b> ע\"ד דוגמא זאת הוא בחי' ביטול השרפים דאע\"פ שהמה נבראים שנתהוו מאין ליש כדוגמת נבראים שביבשה מ\"מ מאיר בהם הארת הסוכ\"ע עד שמתבטלים ממהותם מכל וכל כו' ולכן אומרים קדוש שהוא ענין המשכת הסובב המאיר עליהם כו' אבל המה אומרים רק פ\"א קדוש להיות שעבודתם הוא רק בחי' הרצוא שהוא בחי' הצמאון והתשוקה ליכלל באוא\"ס הסוכ\"ע בעא\"ע, וזהו בחי' כת א' שהוא בחי' שרפים דבריאה כו' אבל כת הב' אומרים ב\"פ קדוש שזהו בחי' מלאכים דיצי' [... בחי' השרפים שביצי' כנ\"ל] שזהו בחי' יוצר אור כי שרש היצי' הוא בחי' גילוי האור מהעלם אוא\"ס הסוכ\"ע שנמשך להחיות העולמות שזהו בחי' שוב המשכת הביטול דהרגשת התכללות האור במאור שיהי' נמשך בכלי שהוא בחי' אהוי\"ר וכידוע בענין ברוך ה' אלקי ישראל מן העולם ועד העולם<sup data-n=\"2480\">59</sup> שהוא מעדאתכ\"ס לעדאת\"ג ולכן אומרים ב\"פ קדוש בחי' המשכת הרצוא שבשרפים דעולם הבריאה שיהי' נמשך בהם בהעלם ויתלבש בבחי' הכלי שלהם בבחי' שוב [... וע\"י פ\"א קדוש מעוררים התגלות הרצוא שמקבלים בחי' זאת משרפים דבריאה ופעם ב' דקדוש ממשיכים בבחי' התלבשות דשוב אך גם המשכתם בבחי' שוב הוא בבחי' רוחניו' בלבד לזאת המלאכים דעשי' שהוא בחי' השרפים דעשי' אומרים ג\"פ קדוש שהוא ההמשכה למטה מטה עד שיהי' נמשך בחי' גילוי אלקות גם למטה בעשי' הגשמי' כו' וד\"ל].\n<b>והנה</b> ע\"ד דוגמא דמלאכים כך הוא בנשמות שבגופים למטה רק להיות שהנשמה שבגוף כאו\"א מישראל הוא בחי' כללי'<sup data-n=\"2481\">60</sup> [ולא פרטי' כמלאכים כידוע] ולזאת",[["2477","56","<b>כי כבד פה</b>: שמות ד, י."],["2478","57","<b>ת\"ח שנמשלו לדגים שבים</b>: כ\"ה בכ\"מ — ראה ברכות סא, ב. שה\"א פה, ב ובהערה 10."],["2479","58","<b>הפך ים ליבשה</b>: תהלים סו, ו. ראה פלח הרמון יתרו ר\"ע רנד. פקודי ע' שמה. מאמרי אדה\"א ויקרא ח\"א ע' ריב ואילך. וש\"נ. שה\"א עא, ב ובהערה 10."],["2480","59","<b>ברוך ה'. . ועד העולם</b>: תהלים קו, מח. דהי\"א טז, לו. ראה זהר ויצא קנג, ב. מאמרי אדה\"א דברים ח\"א ע' קכד. וש\"נ. ש\"א עה, א ובהערה 11."],["2481","60","<b>שהנשמה. . בחי' כללי'</b>: ראה סה\"מ תרל\"ח ע' שא ואילך ובהנסמן בריש המאמר שם."]]],[4801940464,"כולם אומרים ג\"פ קדוש [... והנה בחי' ג\"פ קדוש שאומרים בקדושה הוא המשכת קדושה עליונה דבחי' סוכ\"ע בג' לבושים מחודו\"מ דהיינו מח' והשגת התורה ודבורו בד\"ת ובעשי' מעהמ\"צ עד שיהי' כולו בחי' כלי לקדושה עליונה כמאמר בקרבך קדוש<sup data-n=\"2482\">61</sup> אך הכוונה<sup data-n=\"2483\">62</sup> להמשכת קדושה זאת הוא מקודם בק\"ש בג' מיני אהבות כמשי\"ת כו' וד\"ל]. והנה להבין ענין ג\"פ קדוש בעבודת הנשמות שבגופים ילה\"ק ענין ואהבת בכל לבבך בשני יצריך<sup data-n=\"2484\">63</sup>, דהנה כתיב שאו ידיכם קדש<sup data-n=\"2485\">64</sup> וברכו את הוי', כי הנה ידיכם הוא בחי' ב' ידים עליונים שמזה נמשך ב' בחי' דמס\"נ בכאו\"א בנה\"א ונה\"ט ובתחלה באחד נמשך מסי\"נ בנה\"א ובחי' ועד הוא להמשיך גם בחי' מסי\"נ בנה\"ט ועי\"ז נעשה אח\"כ גילוי ואהבת שהוא התשוקה בלב לצאת מגדרי הכלי ותתפשט האהבה מלבושי' להיות מי לי בשמים<sup data-n=\"2486\">65</sup> ועמך לא חפצתי כו' רק כלה שארי ולבבי<sup data-n=\"2487\">66</sup> לו לבדו, ואה' זאת מתפשטת ופועלת גם בנה\"ט וזהו בכל לבבך שני חללי הלב משכן התפשטות נה\"א ומשכן נה\"ט שיכללו בתשוקה א' להוי' א' שבא ממסי\"נ שבמוח מהתבוננות דאחד ועד כנ\"ל, וזהו ידיכם שני ידים יד ימין מקור הממשיך התשוקה בנה\"א ויד שמאל מקור הפועל תשוקת נה\"ט ג\"כ כו', וההכנה לזה הוא בסדר התפלה שמקודם שהוא התבוננות דברוך שאמר והי' העולם שזהו איך שכל המאמרות המה מאמר א'<sup data-n=\"2488\">67</sup> בלבד ולזאת כולא קמי' כלא חשיב<sup data-n=\"2489\">68</sup> כביטול דיבור א' לגבי נפש המדברת כמבואר בלק\"א<sup data-n=\"2490\">69</sup> ואח\"כ בויברך דוד אתה הוי' לבדך שהוא בחי' הרגשת ביטול והתכללות האור במאור לגמרי שהוא איך שהוא ואין<sup data-n=\"2491\">70</sup> עוד מלבדו ולזה מזכירין אח\"כ קי\"ס שהוא ג\"כ בחי' גילוי דהתכללות האור במאור כנ\"ל שנק' בחי' ים כו' ומזה בא אח\"כ לבחי' מסי\"נ דאחד ועד כנ\"ל.\n<b>וזהו</b> שאו ידיכם קדש שהוא ענין מסי\"נ הנ\"ל שמגיע בבחי' קדש שלמעלה מבחי' קדוש<sup data-n=\"2492\">71</sup> שהוא בחי' התכללות האור במאור [... וע\"ד הקבלה הוא בחי' אין דחכמה שכלול ובטל בלמעלה מן החכמה שהוא בחי' כתר ועד רום המעלות לפני הצמצום חכמה הכלולה ברצה\"פ שבעצמי' כו', ואח\"כ וברכו את הוי' שהוא התגלות אור מחכמה לבינה שזהו בחי' יחוד או\"א שאינו בבחי' מקור להשתלשלות רק התגלות אור העצמי מאין ליש אמיתי, ואך מזה נעשה כתר לז\"א שהוא בחי' עלי' הרצון להיות מקור לעולם הנפרד ועד רום המעלות הוא בחי' גילוי שעשועי' העצמי' בחי' חו\"ב שבעצמי' להיות מקור להיטיב שזהו בחי' ח\"ח<sup data-n=\"2493\">72</sup> שבעצמות וזהו\"ע",[["2482","61","<b>בקרבך קדוש</b>: הושע יא, ט."],["2483","62","<b>הכוונה</b>: ד: ההכנה."],["2484","63","<b>ואהבת בכל לבבך בשני יצריך</b>: ואתחנן ו, ה [בדילוג] ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."],["2485","64","<b>שאו ידיכם קדש</b>: תהלים קלד, ב. ראה גם פלח הרמון שה\"ש ע' מו. לקו\"ת שה\"ש כא, ג."],["2486","65","<b>מי לי בשמים</b>: תהלים עג, כה."],["2487","66","<b>כלה שארי ולבבי</b>: תהלים שם, כו."],["2488","67","<b>שכל המאמרות המה מאמר א'</b>: ראה לקמן מאמר ד\"ה כי תבואו וכו' ושבתה תר\"ט. וש\"נ."],["2489","68","<b>כולא קמי' כלא חשיב</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["2490","69","<b>כביטול דיבור א'. . בלק\"א</b>: פ\"כ."],["2491","70","<b>שהוא ואין</b>: בד: שאין."],["2492","71","<b>קדש שלמעלה מבחי' קדוש</b>: ראה לקו\"ת אמור (בהביאור כאן) לג, ב ואילך."],["2493","72","<b>ח\"ח</b>: חפץ חסד."]]],[4801940499,"העטרה שנתן בראשו כמשי\"ת כו' וד\"ל] ואח\"כ וברכו את הוי' שנעשה בחי' התגלות אור למעלה בשם הוי' דע\"ס ספי'<sup data-n=\"2494\">*73</sup>* דאצי' שהמה בחי' מקור להשתלשלות דבי\"ע, וזהו קדוש הא' שאין עדיין ממנו שום גילוי למטה בהשתלשלות העולמות דבי\"ע ובנפש זהו בחי' אה' דבכל לבבך שהוא לצאת מגדרי הכלי שהוא בחי' רצוא, ואח\"כ קדוש הב' הוא בחי' אה' דבכל נפשך שהוא הרצון לאדבקא מח' במח' ודיבור בדיבור ואח\"כ בכל מאודך הוא בחי' הרצון שבמעהמ\"צ שזהו בחי' קדוש הג' וע\"י קדוש הב' נמשך בחי' גילוי אוא\"ס למטה ברוחני' העולמות דבי\"ע וע\"י קדוש הג' נמשך למטה מטה בחיצוני' העולמות עד עשי' גשמי' כמאמר וימלא כבודו את כל הארץ<sup data-n=\"2495\">73</sup> כו' וד\"ל. ועד\"ז יובן ענין ג' עטרות הנ\"ל א' נתן בראשו שזהו בחי' קדוש הא' שהוא בחי' המשכה למעלה בשם הוי' עצמו ועז\"נ בעטרה שעטרה לו אמו<sup data-n=\"2496\">74</sup> שעטרה זאת עושין מלמטה דנש\"י שבגופים ע\"י מסי\"נ שלהם באחד ועד כנ\"ל [... וכשנמשך בחי' העטרה הנ\"ל למעלה נעשה מזה ג\"כ בחי' גילוי בנפש שהוא בחי' אה' דבכל לבבך אך אין זה נחשב לבחי' גילוי והמשכה למטה כיון דאהבה זאת היא בחי' רצוא לצאת מגדרי הכלי] וזהו העטרה שנתן בראשו ושנים בראש בניו שזהו ב\"פ קדוש שהוא בחי' ההמשכה למטה שזהו בחי' תומ\"צ שזהו בחי' ההמשכה בפנימי' וחיצוני' העולמות כו' וד\"ל.\n<b>ועתה</b> יובן ענין ונקדשתי בתוך בנ\"י, פי' התעוררות העצמי' דאוא\"ס להיות נמשך בבחי' קדוש הראשון שזהו עיקר התחלת הגילוי וממילא נמשך אח\"כ ב\"פ קדוש [כי הרצוא מעורר השוב כו'], וענין התעוררות זאת הוא מתוך בנ\"י שהוא בחי' תוכיות נקודת לבבם שמתעורר לצאת מהעלם אל הגילוי שזהו בחי' ניצוץ האלקי המתגלה באהבה דבכל לבבך כנ\"ל [והתעוררות לצאת לידי גילוי הוא ע\"י הנפוח באש שהוא בחי' רוח בינתו שבסדר התפלה מברוך שאמר והי' העולם עד ק\"ש כנ\"ל שעי\"ז מתרחב הניצוץ האלקי לצאת מגדרי הכלי עד שפועל תשוקת כליון זה בכל כחות הנפש כו' וד\"ל]. וזהו מפני שיבה תקום<sup data-n=\"2497\">75</sup> והדרת פני זקן מפני שיבה הוא בחי' ספה\"ע והדרת פני זקן הוא מ\"ת וכמארז\"ל במ\"ת נדמה להם כזקן<sup data-n=\"2498\">76</sup> כי על הספה\"ע נאמר שבעה שבועות תספר לך<sup data-n=\"2499\">77</sup> מהחל חרמש בקמה<sup data-n=\"2500\">78</sup> כי קמה הוא בחי' קומה שהוא בחי' היש וחרמש בקמה הוא בחי' ביטול היש שזהו ענין ספרה\"ע שסופרים היום יום שממשיכים הארת מדות עליונות במדות שבנה\"א ועי\"ז נתלבש נה\"א בנה\"ט לברר בחי' המדות שבנה\"ט בבחי' אתכפי' ואתהפכא ואהבה זאת מעורר למעלה בחי' קדש העליון שיהי' נמשך בבחי' קדוש הא' שזהו מפני שיבה לפני בחי' שערות לעורר שיהי' נמשך בחי' קדושה דשערות כנ\"ל, וענין תקום היינו שיהי' נמשך בחי' ביטול הנ\"ל בכל פרטי כחות נה\"ט עד שיהי' בחי' קומה שלימה בבחי' ביטול וכענין",[["2494","*73","<b>ספי'</b>: ד: ליתא."],["2495","73","<b>וימלא כבודו את כל הארץ</b>: תהלים עב, יט."],["2496","74","<b>בעטרה שעטרה לו אמו</b>: שה\"ש ג, יא."],["2497","75","<b>מפני שיבה תקום</b>: קדושים יט, לב."],["2498","76","<b>במ\"ת נדמה להם כזקן</b>: ראה מכילתא בשלח טו, ג. יתרו כ, ב."],["2499","77","<b>שבעה שבועות תספר לך</b>: פ' ראה טז, ט."],["2500","78","<b>מהחל חרמש בקמה</b>: ראה לקו\"ת במדבר טו, ד. טז, ד. יז, ג."]]],[4801940531,"הביטול דתפילה שנק' בשם עמידה כו' [והתעוררות זאת הוא דייקא מצד בירור דנה\"ט מצד שרשה בתוהו שקדמה לבחי' תיקון<sup data-n=\"2501\">79</sup> תוכל לעורר בחי' קודש העליון שלמעלה מקדוש להיות נמשך קדוש הא'] ואח\"כ והדרת פני זקן שהוא מ\"ת המשכת ב\"פ קדוש דתומ\"צ שזהו בחי' השוב שאחר הרצוא דספה\"ע וזהו שארז\"ל במ\"ת נדמה להם כזקן בחי' תפארת ומלכות<sup data-n=\"2502\">80</sup> שזהו בחי' שערות עליונות דקדושה כנ\"ל וד\"ל.\n<b>אני</b> הוי' מקדישכם, פי' שיכול האדם לומר מי אנכי שאגיע למדריגות כאלו לעורר קודש העליון ולהמשיך ג\"פ קדוש שהוא בחי' ג' עטרות הנ\"ל ולזה אמר אני הוי' מקדישכם המוציא אתכם מאמ\"צ כו', שכמו שביצי\"מ אע\"פ שהי' בתכלית השפלות במ\"ט שע\"ט<sup data-n=\"2503\">81</sup> מ\"מ<sup data-n=\"2504\">82</sup> ברגע קטן נתעלו לתכלית העילוי שנגלה עליהם ממה\"מ הקב\"ה<sup data-n=\"2505\">83</sup> כו' עד שהיו בתכלית הביטול בחי' מורא גדול, וזהו ג\"כ הכח לעורר בתמידות כל בחי' ומדריגות הנ\"ל דבחי' רצוא שהוא בחי' האהבה דבכל לבבך ואח\"כ השוב דבכל נפשך כו' וההמשכה בפו\"מ דתומ\"צ כו', אך בתנאי שיהי' ולא תחללו את שם קדשי<sup data-n=\"2506\">84</sup> להיות שכל בחי' ונקדשתי וגם בחי' אני הוי' מקדישכם הוא הכל בבחי' וע\"ט, אך צ\"ל מתחילה בחי' סומ\"ר בתכלית וגם לשמור א\"ע מגיאות והתנשאות שלא יהי' בחי' נפרד ח\"ו וכאמרם כאלו דוחק רגלי השכינה<sup data-n=\"2507\">85</sup> כו' וזהו ולא תחללו שלא לעשות חלל<sup data-n=\"2508\">86</sup> והפסק בינו לבין אוא\"ס ח\"ו ועי\"ז ממילא יהי' אני הוי' מקדישכם שישרה בנפשו הכח ועוז מלמעלה שיוכל לבוא לכל מדריגות הנ\"ל כנ\"ל וד\"ל.",[["2501","79","<b>בתוהו שקדמה לבחי' תיקון</b>: ראה תו\"א בשלח סה, ד. לקו\"ת אמור לז, ד. וש\"נ."],["2502","80","<b>תפארת ומל'</b>: ד: תומ\"צ."],["2503","81","<b>מאמ\"צ. . במ\"ט שע\"ט</b>: ראה ז\"ח יתרו לא, א."],["2504","82","<b>מ\"מ</b>: ניתוסף ע\"פ ד."],["2505","83","<b>שנגלה עליהם ממה\"מ הקב\"ה</b>: הגדה ש\"פ פיסקא מצה זו."],["2506","84","<b>ולא תחללו את שם קדשי</b>: התחלת הכתוב ונקדשתי — אמור כב, לב."],["2507","85","<b>כאלו דוחק רגלי השכינה</b>: ראה ברכות מג, סע\"ב. חגיגה טז, א. קדושין לא, א."],["2508","86","<b>ולא תחללו שלא לעשות חלל</b>: ראה מאמר ד\"ה זה במאמרי אדה\"ז תקס\"ב ח\"ב ע' שפו ואילך. תו\"ח תצוה ח\"ב שנז, ב. וש\"נ. לקמן מאמר ד\"ה את שבתותי תקצ\"ח על יד הערה 122."]]],[4801940109,"<b>שבת במדבר ביום אחר הסעודה [תרי\"ד]</b>\n<b>דבר</b> אל בני ישראל ואמרת אליהם מועדי ה' כו' מקראי קודש כו' אלה הם<sup data-n=\"2509\">1</sup> מועדי<sup data-n=\"2510\">2</sup>. להבין הכפל שכפל אלה הם מועדי יובן ע\"פ המבואר ברמב\"ן בהקדמה לפי' התו'<sup data-n=\"2511\">3</sup> שכל התורה הוא כשלישי המדבר כי כל הנביאים אמרו הי' דבר ה' אלי<sup data-n=\"2512\">4</sup> ונמצא שהם המה המדברים אבל כל התורה כתי'<sup data-n=\"2513\">5</sup> וידבר ה' אל משה כו' ומי האומר מאמר הזה כ\"א הי' משה המדבר הי' צריך לכתוב וידבר ה' אלי ואם הוי' הוא המדבר הי' צ\"ל דברתי אל משה אלא ע\"כ לומר שהמדבר הוא בחי' שלישי כו', ופי' אדמו\"ר הזקן<sup data-n=\"2514\">6</sup> נ\"ע<sup data-n=\"2515\">7</sup> שהכוונה הוא כך כי הוי' הוא בחכ\"ע<sup data-n=\"2516\">8</sup> והדיבור הוא בחי' המשכה מפנימי' חכ\"ע בבחי' משה יסו\"א [... או דעת<sup data-n=\"2517\">9</sup> דז\"א<sup data-n=\"2518\">10</sup> ] ולאמר לבנ\"י היינו להמשיך המשכה הזאת בבנ\"י שהם בחי'<sup data-n=\"2519\">11</sup> נו\"ה<sup data-n=\"2520\">12</sup> כו' והמספר שכך דיבר הוי' אל משה בכדי לאמר לבנ\"י הוא בחי'<sup data-n=\"2521\">13</sup> עצמו' המאציל<sup data-n=\"2522\">14</sup> שלמעלה הרבה מבחי' חכ\"ע [... והוא ממשיך הגילוי ע\"י סיפורו בנש\"י דבי\"ע וכך הוא המדה שבכדי שיוכל להיות נמשך בבי\"ע צ\"ל ההמשכה ממקום גבוה יותר והיינו מבחי' עצמו' המאציל שלמעלה הרבה מבחי' סובב וממלא כו']. ועם זה יובן ענין כפל ל' הנ\"ל כי הנה המועדים הם יומין דחול רק שנמשך בהם בחי' קודש דחכ\"ע לכן נק' בשם מקראי קודש<sup data-n=\"2523\">15</sup> ופסח הוא בחסד ושבועות בגבו' וסוכות בת\"ת<sup data-n=\"2524\">16</sup> כו'. וזהו מועדי הוי' שהם בחי' המועדים חג\"ת שהם מיוחדים בהוי' בחי' אא\"ס המלובש בתוכם כי איהו וחיוהי וגרמוהי חד<sup data-n=\"2525\">17</sup> [... וגם יתפרש שנמשך בהם תוס' אורות מבחי' הוי' דחכ\"ע הנק' קדש ולכן נק' מקראי",[["2509","1","<b>דבר אל בני ישראל. . אלה הם מועדי</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה המאמר שנדפס לאח\"ז ובהנסמן בריש המאמר שם.\nמאמר זה הובא במאמר שלאח\"ז."],["2510","2","<b>דבר. . קודש כו'. . מועדי</b>: אמור כג, ב [תיבת כו' הובא בכל הכת\"י]."],["2511","3","<b>המבואר ברמב\"ן בהקדמה לפי' התו'</b>: ראה פתיחת הרמב\"ן עה\"ת קרוב לתחלתו."],["2512","4","<b>הי' דבר ה' אלי</b>: ראה רמב\"ן דפוס ראשון. סה\"מ תרל\"ח ע' שלג ובהערות 15-16."],["2513","5","<b>כל התורה כתי'</b>: ראה רמב\"ן שם."],["2514","6","<b>ופי' אדמו\"ר הזקן</b>: השווה המאמר שנדפס לאח\"ז. פלח הרמון יתרו ע' ריז. ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע קסא ואילך."],["2515","7","<b>נ\"ע</b>: ב: נבג\"מ."],["2516","8","<b>הוי' הוא בחכ\"ע</b>: ראה זהר רע\"מ פינחס רנה, רע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלה."],["2517","9","<b>משה יסו\"א. . דעת דז\"א</b>: ראה לקו\"ש שמות כרך ו ע' 244 ואילך."],["2518","10","<b>יסו\"א. . דעת דז\"א</b>: ראה ע\"ח שער הכללים פ\"י. הובא בלקו\"ש שם ע' 245."],["2519","11","<b>בבנ\"י שהם בחי' נו\"ה</b>: ראה ת\"ז רתמ\"ח. טעמי המצות וספר הליקוטים להאריז\"ל ר\"פ תשא. מאו\"א מערכת בנ\"י אות נב וביאיר נתיב שם."],["2520","12","<b>נו\"ה</b>: ב: נה\"י. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תשנט הובא בסה\"מ תרל\"ח ע' רפט."],["2521","13","<b>בחי'</b>: ניתוסף ע\"פ ב."],["2522","14","<b>עצמו' המאציל</b>: ראה פלח הרמון שם."],["2523","15","<b>המועדים. . בשם מקראי קודש</b>: אמור כג, ב. ד. לז. ראה זהר אמור צד, א. סידור שער המועדים ריז, ב. ביאוה\"ז קרח צב, ד ואילך. מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרסו ואילך. לקו\"ת ויקרא א, ג."],["2524","16","<b>ופסח. . בת\"ת</b>: ראה גם לקמן מאמר ד\"ה לה\"ע ההפרש בין שליו\"ט תר\"ב ובהערה 136."],["2525","17","<b>איהו וחיוהי וגרמוהי חד</b>: ראה ת\"ז בהקדמה ג, ב."]]],[4801940173,"קודש כנ\"ל. ..] אשר תקראו אותם במועדם הוא ההמשכה בבחי' המל' דאצי' ולכן ת\"א על תיבת במועדם בזמניהון<sup data-n=\"2526\">19</sup> כו'<sup data-n=\"2527\">18</sup> שהוא בחי' המל' מקור הזמן<sup data-n=\"2528\">20</sup> כו'<sup data-n=\"2529\">21</sup>. אלה הם מועדי כי שרש המועדים הוא למעלה מחכ\"ע שהם חג\"ת שברצון כו' וזהו מאמר עצמות המאציל שלמעלה מבחי' חכ\"ע שהוא המספר כנ\"ל שהמועדים הם מועדי מיוחדים בעצמותי כו', וכן עד\"ז הו\"ע המצות יש ג' בחי'<sup data-n=\"2530\">22</sup> ע\"ד המועדים הא' מצות המלך<sup data-n=\"2531\">23</sup> כו' והב' רמ\"ח פיקודין רמ\"ח אברין דמלכא<sup data-n=\"2532\">24</sup> ונק' מצות הוי'<sup data-n=\"2533\">25</sup> והג' שרשם בבחי' אורחין דגולגלתא<sup data-n=\"2534\">26</sup> ונק' מצותי<sup data-n=\"2535\">27</sup> כו' וד\"ל.",[["2526","19","<b>ת\"א. . במועדם בזמניהון</b>: אמור כג, ד."],["2527","18","<b>אשר. . כו'</b>: ד: מחק כל זה כאן, והעתיקו לקמן על יד הערה 21 עם הוספה."],["2528","20","המל' מקור הזמן ראה שער היחוד והאמונה פ\"ז. לעיל מאמר ד\"ה מנין שקושרין לשון של זהורית ובהערה 175."],["2529","21","<b>כו'</b>: ד הוסיף עה\"ג: ואח\"כ בפ\"ד [ בפסוק ד] אמר אשר תקראו. . הזמן כו'. המובא לעיל בפנים על יד הערה 18."],["2530","22","<b>המצות יש ג' בחי'</b>: ראה לקו\"ת במדבר יז, א (ובהנסמן בריש המאמר שם)."],["2531","23","<b>מצות המלך</b>: ראה אסתר ג, ג. מאמרי אדה\"א שמות ח\"א ע' יא. וש\"נ. נ\"ך ע' רלה. ש\"א ע' נו."],["2532","24","<b>רמ\"ח. . אברין דמלכא</b>: ראה ת\"ז ת\"ל (עד, סע\"א). תניא רפכ\"ג. סידור שער החנוכה רפ, א. שע\"ת עב, ג הערה 17."],["2533","25","<b>מצות הוי'</b>: ויקרא ד, ב. ראה גם סה\"מ תרל\"ח ע' שלב הערה 6."],["2534","26","<b>שרשם בבחי' אורחין דגולגלתא</b>: ראה זהר אד\"ר נשא קכט, א. קלו, א."],["2535","27","<b>מצותי</b>: תולדות כו, ה. בשלח טז, כח. יתרו כ, ו. ועוד. ראה סה\"מ תרל\"ח שם."]]],[4801940110,"<b>יום אסרו חג השבועות דשנת כת\"ר</b>\n<b>וידבר</b> הוי' כו' דבר אל בנ\"י כו' אלה הם מועדי<sup data-n=\"2536\">1</sup> כו'. להבין כפל לשון שבתחלה א' מועדי הוי' ואח\"כ כפל פעם אחרת אלה הם מועדי<sup data-n=\"2537\">2</sup>, וגם למה שינה בתחלה לדבר בל' נסתר מועדי הוי' ובסוף דיבר בל' מדבר בעדו אלה הם מועדי כו' [... וברשימה דלעיל דמ\"ה<sup data-n=\"2538\">3</sup> מבואר שם עוד דקדוק א' מה שאח\"כ בפסוק ד' אחר שביאר ענין השבת כפל עוד לומר אלה מועדי הוי' כו' וסיים אשר תקראו אותם במועדם כו' והתרגום תרגם ע\"ז די תערעון יתהון בזמניהון כו'. ..]. הנה לשון הרמב\"ן בהקדמתו לתורה<sup data-n=\"2539\">4</sup> שמשרע\"ה כתב תולדות כל הדורות הראשונים ויחוס עצמו ותולדותיו ומקריו כשלישי המדבר כו' ולכן גם בענין כתיבת המצות נאמר וידבר",[["2536","1","<b>וידבר הוי' כו' אלה הם מועדי</b>: הנחת ר' הלל מדרוש הצ\"צ.\nמדרוש הצ\"צ נדפסו שתי הנחות, הנחת כ\"ק אדמו\"ר מהר\"ש נדפסה באוה\"ת אמור כרך ג ע' תתלז. והנחה אחת נדפסה באוה\"ת אמור כרך ד ע' א'עה. וראה גם מאמר ד\"ה זה בסה\"מ תרל\"ח ע' שלב ובהנרשם בריש המאמר שם."],["2537","2","<b>וידבר. . אלה הם מועדי</b>: אמור כג, א. ב."],["2538","3","<b>וברשימה דלעיל דמ\"ה</b>: הכוונה להמאמר שנדפס לפנ\"ז."],["2539","4","<b>לשון הרמב\"ן בהקדמתו לתורה</b>: ראה פתיחת הרמב\"ן על התורה (בשינויים ובתוס' ביאור)."]]],[4801940174,"הוי' אל משה ולא כתב הי' דבר ה' אלי כמו שאר הנביאים שמדברים בלשון זה, הוא ג\"כ מטעם זה כי נכתבה כשלישי המספר על שנים אחרים ומספר שכך דיבר הוי' אל משה כו'. וכתב עוד ואל יקשה בעיניך ענין משנה תורה שכותב בו ל' מדבר בעדו ואתחנן אל ה'<sup data-n=\"2540\">5</sup> כו' ואתפלל<sup data-n=\"2541\">6</sup> כו', להיות כי תחלת הספר הוא אלה הדברים אשר דיבר משה<sup data-n=\"2542\">7</sup> אל כל ישראל שהוא ג\"כ כאחד המספר שכך דיבר משה אל כל ישראל והוא ג\"כ השלישי המספר כל התורה כו' ולכן הוא מספר בל' אומרם שכך אמר משה ואתחנן כו'. וכתב הטעם לכתיבת התורה בל' זה מפני שקדמה לבריאת העולם כו' והיתה כתובה באש שחורה<sup data-n=\"2543\">8</sup> ע\"ג אש לבנה והנה משה כסופר המעתיק מספר קדמון וכותב יעו\"ש.\n<b>והנה</b> אדמו\"ר הזקן נ\"ע אמר שכוונת הרמב\"ן הוא עצמות המאציל כו' [... ע' ברשימה דלעיל<sup data-n=\"2544\">9</sup>. ..] וצריך להבין כל הנ\"ל, גם להבין ענין כל כתיבת המצות שנכתבה בדרך סיפור מעשה ולא בדרך ציווי ואזהרה לעשות [... כי הגם שכתוב בל' ציווי כמו דבר אל בנ\"י ויקחו לי תרומה<sup data-n=\"2545\">10</sup> כו' או כי תבואו אל הארץ ושבתה<sup data-n=\"2546\">11</sup> כו' מ\"מ כיון שתחלת הדברים הוא וידבר הוי' כו' נראה הל' שאין עיקר הכוונה הציווי רק עיקר הכוונה הוא הסיפור לספר איך ציווה ה' אל משה לדבר אל בנ\"י וכנ\"ל שהל' הוא כשלישי המדבר כו'. ..], לבד פ' משפטים אינו כתיב בתחלתו וידבר כו' והל' נכתב בדרך ציווי ואזהרה כו'. ועוי\"ל מ\"ש כמה פעמים אני הוי' דמשמע ששם הוי' הוא ידוע ומושג ובאמת אני הוי' לא שניתי<sup data-n=\"2547\">13</sup> כי לית מאן דתפיס בי'<sup data-n=\"2548\">14</sup> וא\"כ אינו מושג כלל<sup data-n=\"2549\">12</sup> והוא בתכלית ההעלם כמאמר הידוע לית מחשבה תפיסא בי' כלל<sup data-n=\"2550\">15</sup> כו'.\n<b>והנה</b> להבין כל הנ\"ל י\"ל ענין התו\"מ כי הנה אמרז\"ל תלמוד גדול מפני שמביא לידי מעשה<sup data-n=\"2551\">16</sup> וא\"כ כל עיקר הלימוד הוא לידע איך לעשות המצות, וא\"כ יקשה ממש\"א בירושלמי ע\"פ וכל חפצים לא ישוו בה<sup data-n=\"2552\">17</sup> שאפי' כל מצותי' של תורה אינם שווים לדבר א' מן התורה כו', ובתלמודא דידן מחלק<sup data-n=\"2553\">18</sup> בין מצוה שאפשר לעשות ע\"י אחרים שאין מבטלין ת\"ת בשבילה ובין מצוה שא\"א לעשות ע\"י אחרים",[["2540","5","<b>ואתחנן אל ה'</b>: ואתחנן ג, כג."],["2541","6","<b>ואתפלל</b>: עקב ט, כו."],["2542","7","<b>אלה הדברים אשר דיבר משה</b>: דברים א, א."],["2543","8","<b>והיתה כתובה באש שחורה</b>: ראה רש\"י שה\"ש ה, טז (ד\"ה שחורות). הנסמן במאמרי אדה\"א בראשית ע' תקכג."],["2544","9","<b>אדמו\"ר הזקן אמר. . ברשימה דלעיל</b>: המאמר שנדפס לפנ\"ז."],["2545","10","<b>דבר. . ויקחו לי תרומה</b>: תרומה כה, ב."],["2546","11","<b>כי תבואו אל הארץ ושבתה</b>: בהר כה, ב [בדילוג]."],["2547","13","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2548","14","<b>לית מאן דתפיס בי'</b>: זהר רע\"מ פינחס רכה, א."],["2549","12","<b>אני הוי'. . ידוע ומושג. . אינו מושג כלל</b>: לך טו, ז. ויצא כח, יג. ועוד. ראה גם סה\"מ תרל\"ח ע' שלב ובהערה 10."],["2550","15","<b>לית מחשבה. . כלל</b>: ראה ת\"ז בהקדמה יז, א."],["2551","16","<b>תלמוד גדול. . מעשה</b>: ראה קדושין מ, ב."],["2552","17","<b>וכל חפצים לא ישוו בה</b>: משלי ח, יא. ראה ירושלמי פאה פ\"א, ה\"א."],["2553","18","<b>ובתלמודא דידן מחלק</b>: ראה מוע\"ק ט, ב."]]],[4801940231,"שמבטלים ת\"ת בשבילה ולפי הנ\"ל שעיקר התלמוד הוא בכדי לידע איך לעשות המצוה א\"כ הי' צריך לבטלה אפי' בשביל מצוה שאפשר לעשותה ע\"י אחרים כמו הפרשת תרומה שאפשר לעשותה ע\"י שליח<sup data-n=\"2554\">19</sup> מ\"מ מצוה בו יותר מבשלוחו<sup data-n=\"2555\">20</sup> יותר טוב שיעשה הוא<sup data-n=\"2556\">21</sup> המצוה בעצמו ויבטל ת\"ת כיון שעיקרה אינה אלא ידיעת המצות כו', ועכ\"ל שמצות ת\"ת מצד עצמו הו\"ע גדול מאד אפי' הלימוד שאינו נצרך למעשה כמו סדר קדשים בזה\"ג<sup data-n=\"2557\">22</sup> יש מצוה גדולה בלימודו, אך ראי' זאת אינה מכרחת כ\"כ כי נוכל לומר כי המצוה בלימוד ס' קדשים מטעם מהרה יבנה בהמ\"ק כו' ולכן הלימוד הוא נצרך למעשה, אך ראי' יותר ברורה הוא ממה שהנשמות בגעה\"ע לומדים את התורה כידוע במאמר רבה בר נחמני<sup data-n=\"2558\">23</sup> כו' והמה פטורים מן המצות ועכ\"ל דהתלמוד הו\"ע גדול מצד עצמו לא בשביל ידיעת המצות בלבד כו' ומאמר תלמוד גדול שמביא לידי מעשה יש בו פי' אחר [... כמשי\"ת, ועוד דממקומו הוא מוכרע דא' נמנו וגמרו תלמוד גדול וקאי על פלוגתא דלעיל איזה מהם גדול תלמוד או מעשה וא' שנמנו וגמרו תלמוד גדול והכוונה שהוא גדול מן המעשה ואיך אמר מפני שמביא לידי מעשה א\"כ המעשה גדול ועל כרחך לומר כדלקמן כו'. ..].\n<b>אך</b> להבין כ\"ז צ\"ל במה שמצינו שיש הפרש בין תורה למצוות, שהמצות הם תלוי' בזמן ומקום כמו מצות הקרבנות הם במקום בהמ\"ק<sup data-n=\"2559\">24</sup> דוקא וכן בזמן בכלל ביום<sup data-n=\"2560\">25</sup> ולא בלילה ובפרט מצות מוסף שבת שני כבשים<sup data-n=\"2561\">26</sup> וברגלים באין<sup data-n=\"2562\">28</sup> פרים בני בקר<sup data-n=\"2563\">29</sup> שנים<sup data-n=\"2564\">27</sup><sup data-n=\"2565\">30</sup> כו' וצריך להקריב כ\"א במועדו ובזמנו ואם יחליף של זה בזה אינה מצוה כלל ולא יגרום יחוד עליון כלל, וכן מצות התלוי' בזה\"ז<sup data-n=\"2566\">31</sup> הם תלויות בזמן דווקא כמו מצות ישיבת סוכה בחודש תשרי מט\"ו ועד כ\"ב בו ואם ישב בניסן בסוכה אינה מצוה כלל, וכן אכילת מצה בחודש ניסן מט\"ו בו ועד כ\"ב בו ואם יאכל מצה בימי הסוכות איננה מצוה כלל, משא\"כ לימוד התורה אינה תלוי' בזמן ומקום כלל כידוע דכל העוסק בתורת עולה<sup data-n=\"2567\">32</sup> כאלו הקריב עולה ונעשה עי\"ז יחוד עליון שנעשה ע\"י הקרבנות ואף שאינו כהן ואין כאן בהמ\"ק ומזבח בנוי ואין הזמן גרמא עד\"מ שלומד הלכות מוסף שבת גורם היחוד עליון הנעשה ע\"י מוסף שבת [... רק כיון",[["2554","19","<b>הפרשת תרומה. . ע\"י שליח</b>: ראה תרומות פ\"ד, מ\"ד."],["2555","20","<b>מצוה בו יותר מבשלוחו</b>: קדושין מא, א. ראה שו\"ע אדה\"ז הל' שבת סר\"נ, ס\"ד ובקו\"א שם. תבואות שור סכ\"ח, סקי\"ד."],["2556","21","<b>הוא</b>: ניתוסף ע\"פ אד."],["2557","22","<b>בזה\"ג</b>: ניתוסף ע\"פ אד."],["2558","23","<b>שהנשמות. . רבה בר נחמני</b>: ב\"מ פו, א."],["2559","24","<b>הקרבנות הם במקום בהמ\"ק</b>: ראה פ' ראה יב, ה ואילך. רמב\"ם הל' מעשה הקרבנות רפי\"ח."],["2560","25","<b>הקרבנות הם. . ביום</b>: ראה תו\"כ צו ז, לח. זבחים צח, א."],["2561","26","<b>מוסף שבת שני כבשים</b>: ראה סהמ\"צ להרמב\"ם מ\"ע מא."],["2562","28","<b>באין</b>: אבד: בא ע'. ה: באופן אחר."],["2563","29","<b>ע' פרים בני בקר</b>: ראה פינחס כט, יג ואילך."],["2564","27","<b>וברגלים באין פרים בני בקר שנים</b>: פינחס כח, יט. כז."],["2565","30","<b>שנים</b>: לפי אבד שבהערה 28-9 אוצ\"ל: אלים שנים."],["2566","31","<b>התלוי' בזה\"ז</b>: ה: הנהוגים בזה\"ג."],["2567","32","<b>דכל העוסק בתורת עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."]]],[4801940284,"שהיחוד נעשה ע\"י הלימוד בלבד שהוא בדיבור לכן אינו נמשך רק ברוחניות בפנימי' העולמות משא\"כ ע\"י מעשה הקרבנות בזמן בהמ\"ק הי' נמשך בחיצוניות העולמות ולכן הי' בחי' אלקות דלמעלה מן הטבע בהתגלות וכמו אש של מעלה שהי' יורד<sup data-n=\"2568\">33</sup> כו', מקום ארון אינו מן המדה<sup data-n=\"2569\">34</sup> כו', משא\"כ עכשיו אותותינו לא ראינו<sup data-n=\"2570\">35</sup> כו' מצד שאין הגילוי בחיצוניות העולמות אלא בפנימיות כנ\"ל וד\"ל. וכן<sup data-n=\"2571\">36</sup> עד\"ז אפשר יכול להיות היינו כאשר לומד הלכות סוכה שהוא כאילו קיים מצות סוכה והיינו כנ\"ל שממשיך אור העליון למטה כמו כשיושב בסוכה בימי הסוכות כן ממשיך המשכה זאת ע\"י הלימוד אפי' כשלומדה שלא בזמנה<sup data-n=\"2572\">37</sup> רק שממשיך בפנימי' ולא בחיצוני' כמו כשממשיך ע\"י מעהמ\"צ עצמה שממשיך גם בחיצוני' כו' וד\"ל.\n<b>אך</b> להבין כל הנ\"ל י\"ל ענין המאמר שהתורה קדמה לעולם<sup data-n=\"2573\">38</sup> וכמ\"ש ואהי' אצלו אמון<sup data-n=\"2574\">39</sup> כו' ונאמר ה' קנני ראשית דרכו<sup data-n=\"2575\">40</sup> והיינו שהתורה קדמה גם לעולם הנאצל<sup data-n=\"2576\">41</sup> כי שרשה בעצמות המאציל כו'. והענין הוא כי התורה הוא בחי' חכמה<sup data-n=\"2577\">42</sup> רק שהיא בחי' חכה\"ק בעצמיות המאציל, והנה מבשרי אחזה שבחי' חכ' הוא בחי' קו המדה למדוד כל דבר באיזה אופן יהי' ואח\"כ הוא עושה ע\"פ מה שנמדד בחכמתו כן למעלה מתחלה נמדד בעצמו' המאציל כל אופן ההשתלשלות מרכ\"ד עד סוכ\"ד באיזה אופן יהי' ואח\"כ נמשכו כל ההשתלשלות באופן שכבר נמדד בעצמות המאציל וכן כל היחודים הנעשים ע\"י המצות נמדדו כבר בעצמו' המאציל באיזה אופן יהי' היחוד, היינו כאשר יעשו בנ\"י כך וכך ימשיכו בחי' יחוד עליון דקוב\"ה ושכינתי' שהוא בחי' תוס' אורות על המדה הקצובה בראשית ההשתלשלות בבחי' העולמות, ותוס' זה מרובה באין ערוך על העיקר, וזהו נק' יחוד קוב\"ה ושכינתי'<sup data-n=\"2578\">43</sup> כי שכינה הוא שוכן בתחתונים שהוא בחי' החיות אלקי המחי' את כל העולמות כו' וקוב\"ה הוא בחי' הסובב כו' [היינו עצמות המהות שלמעלה מגילוי אור בחי' סובב האמיתי. ..] והיחוד הוא בחי' תוס' אורות הנמשכים מבחי' סובב הנ\"ל לבחי' ממכ\"ע וזה נמדד בעצמו' המאציל באיזה אופן יומשך היינו הקרבן כאשר יעשה איש הישראלי בכל הדקדוקים אזי יומשך ע\"י תוס' אורות בכל הפרצופים דאצילות אפי'",[["2568","33","<b>אש של מעלה שהי' יורד</b>: ראה תו\"כ ויקרא א, ז. ערובין סג, א. מאמרי אדה\"א דברים ח\"ד ע' א'תפה. וש\"נ."],["2569","34","<b>מקום ארון אינו מן המדה</b>: יומא כא, א."],["2570","35","<b>אותותינו לא ראינו</b>: תהלים עט, ד."],["2571","36","<b>וד\"ל וכן</b>: אד: וד\"ל (וכן. ה חסר דף. וכנצ\"ל: וד\"ל. ..) וכן."],["2572","37","<b>כאשר לומד הל' סוכה. . כאילו קיים. . אפי' כשלומדה שלא בזמנה</b>: ראה גם לקו\"ת במדבר יג, א. מאמרי אדה\"ז תקס\"ב ח\"א ע' רד. ח\"ב ע' תמו ואילך. ע' תמח ואילך. תו\"ח ויקהל ח\"ב שצג, א. וש\"נ. סה\"מ תרל\"ח ע' שלד הערה 42. לקמן מאמר ד\"ה לה\"ע ההפרש בין שבת ליו\"ט תר\"ב על יד הערה 126."],["2573","38","<b>שהתורה קדמה לעולם</b>: פסחים נד, א."],["2574","39","<b>ואהי' אצלו אמון</b>: משלי ח, ל."],["2575","40","<b>ה' קנני ראשית דרכו</b>: משלי יח, כב."],["2576","41","<b>שהתורה קדמה גם לעולם הנאצל</b>: ראה מאמרי אדה\"ז תקס\"ז ע' ריג. תו\"ח וארא ח\"א עט, ד. וש\"נ."],["2577","42","<b>התורה הוא בחי' חכמה</b>: ראה גם מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקי ובהנסמן במ\"מ לשם."],["2578","43","<b>יחוד קוב\"ה ושכינתי'</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 75 ואילך. תו\"ח וארא ח\"א נא, ג."]]],[4801940334,"בי\"ע, משא\"כ כשיחסר דקדוק א' היינו שיקבל בשמאל הקרבן פסול<sup data-n=\"2579\">44</sup> ולא יומשך כלום על ידו, וכ\"ז נמדד בעצמות המאציל באיזה אופן תהי' עשיות המצות, ומדידה זאת נמדד ע\"פ חכמת עצמות המאציל וחכ' זאת נק' תורה, וכן נמדד בעצמות אופן הרחקת יניקות החיצונים באיזה אופן יהי' והיינו ענין הל\"ת לא תאכל חלב ודם<sup data-n=\"2580\">45</sup> כו' וד\"ל, ולכן התורה שלפנינו כתיב בה שני דברים, בתחלת התורה כתיב סדר הבריאה איך היתה ע\"י עשרה מאמרות והגם שכתוב בה רק סדר הבריאה הגשמי מ\"מ כ\"ה הסדר עד רום המעלות אפי' עולם העליון שבמחה\"ק דא\"ק נמשך ג\"כ ע\"י עשרה מאמרות העליונים הנמשכים מעצמות המאציל ע\"י צמצום כו', ואח\"כ מהחודש הזה לכם<sup data-n=\"2581\">46</sup> עד גמירא כתיב בה איכות עשיית המצות באיזה אופן יעשו אותם בנ\"י והל\"ת שצריכים בנ\"י להשמר מהם לא לעשות אותם בכדי להרחיק אותם יניקת החיצונים כנ\"ל, והיינו מפני ששני הדברים נמדדו בחכמת עצמות המאציל איכות ההשתלשלות ואיכות עשיית המצוה ואיכות השמירה דל\"ת כו' וד\"ל.\n<b>וביאור</b> הדברים, ידוע המאמר בריש הורמנותא דמלכא<sup data-n=\"2582\">47</sup> גליף גליפו בטהירו עילאה כו', הענין הוא כי בחי' העצמות גם בשם א\"ס לא יתכן לקרותו כי הוא נבדל מגדר גילוי לגמרי רק ע\"י ירידת העצמות בדרך דילוג גדול שהוא הרצון הפועל דילוג זה נתגלה בעצמותו בחי' א\"ס והיינו מל' דא\"ס שבחי' זאת בלבד יתכן לקרותה א\"ס אך לא למעלה הימנו כך אמור בשם הה\"מ נ\"ע<sup data-n=\"2583\">48</sup>, וזהו הורמנותא דמלכא רצון ומח' דאנא<sup data-n=\"2584\">49</sup> אמלוך<sup data-n=\"2585\">50</sup> כו', אך להיות שבחי' מל' דא\"ס הוא מקור להשפיע עולמות לאין שיעור וגם כל עולם הי' בבחי' א\"ס לזאת נתגלה בחי' חכ' ברצון זה למדוד באיזה אופן יהי' ההשתל' היינו שיהי' במספר קצוב וגם כל עולם יהיה במדה ושיעור באופן הגבלתו גבול רוחני או גבול גשמי וזהו\"ע גליף גליפו בטהי\"ע. ופי' שיער בעצמו בכח<sup data-n=\"2586\">51</sup> מה שעתיד להיות בפועל כי פועל הוא המשכת כל העולמות לאחר הצמצום מרכ\"ד עד סוכד\"ר כ\"ז נמדד בכח עצמי' המאציל לפני הצמצום כו'. אך ידוע שכל ההשתלשלות הוא רק הארה דהארה מעצמי' המאציל אך ע\"י המצות נמשך שפע פנימי' מעצמו' האור וגם זה נמדד בחכ' זאת כי תיבות מה שעתיד להיות מרבה הכל בין שפע החיצוני' דהשתל' בין שפע הפנימי' הנמשך ע\"י תומ\"צ כו'. והנה שרש חכ' זאת היא למעלה מן הרצון כי היא מבחי' כוונה הפנימי'",[["2579","44","<b>שיקבל בשמאל הקרבן פסול</b>: ראה זבחים טו, ב. רמב\"ם הל' ביאת מקדש פ\"ה, הי\"ח."],["2580","45","<b>לא תאכל חלב ודם</b>: ראה ויקרא ג, יז."],["2581","46","<b>מהחודש הזה לכם</b>: בא יב, ב."],["2582","47","<b>בריש הורמנותא דמלכא</b>: ראה זהר בראשית טו, א. לקמן מאמר ד\"ה אם בחוקותי הג' הערה 61."],["2583","48","<b>העצמות גם בשם א\"ס לא יתכן. . בשם הה\"מ נ\"ע</b>: ראה גם לעיל ס\"ע טו ובהערה 155."],["2584","49","<b>הורמנותא. . רצון ומח' דאנא אמלוך</b>: ראה מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תשי. תקס\"ח ח\"א ע' שכד. שעה\"י קטז, ב. ש\"א פב, ב."],["2585","50","<b>דאנא אמלוך</b>: ראה מאמרי אדה\"ז תקס\"ח ח\"א ע' ז ”וכמ\"ש בזהר בפי' וימלוך אנא אמלוך\". הנסמן במאמרי אדה\"א דברים ח\"ג ע' תתצד. וראה גם לקמן ביאור על מאמר ד\"ה את שבתותי תרי\"ב ע' תטו."],["2586","51","<b>שיער בעצמו בכח</b>: ראה מק\"מ לזהר בראשית טו, א. מאמרי אדה\"א קונטרסים ע' רא. וש\"נ."]]],[4801940381,"שברצון הנ\"ל כמבואר במ\"א, וזהו\"ע התורה שקדמה לעולם כו', וזהו ענין המבואר ברמב\"ן<sup data-n=\"2587\">52</sup> שהיתה כתובה באש שחורה ע\"ג אש לבנה כי אש לבנה הוא בחי' מל' דא\"ס שנמשך מבחי' חסד דא\"ס והיינו מה שעלה ברצונו להיטיב כו' והוא בחי' לבנונית פשוטה חסד בלתי מוגבל ואש שחורה היינו האותיות דגליף גליפו שנמשכים מחכמה עצמי' המאציל למדוד איכות הגילוי שיתגלה הן בפנימי' והן בחיצוניות שכ\"ז הוא בחי' גבורה לכן נק' אש שחורה כו' וד\"ל. ..].\n<b>והנה</b> כאשר איש הישראלי לומד את התורה הוא ממשיך ע\"י לימודו שני דברים הנ\"ל, הא' הארה חיצוני' לצורך קיום העולמות ולכן התורה היא קיום העולמות כמאמר אם לא בריתי<sup data-n=\"2588\">53</sup> כו' וגם ממשיך שפע הפנימי' דתומ\"צ וממשיכו למטה באצילות וגם בפנימי' העולמות דבי\"ע אך אין כלים לאור זה אך ע\"י המצות עושים כלים לאור זה הנמשך ע\"י התורה וזהו כי נר מצוה ותורה אור<sup data-n=\"2589\">54</sup> כי ע\"י התורה ממשיכים האור בלבד וע\"י המצות נעשים הכלים הנק' נר כו' [... והנה ג' בחי' כלים יש הא' בבחי' הכתר ששם שרשי הכלים דאצילות, והב' בחי' הכלים דאצילות והג' כלים דמל' דאצילות שעל ידם נמשך האור בבי\"ע וכ\"ז נעשה ע\"י המצות ע\"י הביטול פשוט של המצוה שנעשית מצד גזירת מלך נעשים כלים דמל' וע\"י כוונת המצות נעשים כלים דאצילות וזהו ענין הנק' איברים דמל' וע\"י ביטול הרצון שאחר הכוונה כו' נעשים הכלים דכתר וזהו\"ע ארחין דגלגלתא וזהו\"ע מצותי ומצות הוי', אך התורה ממשיך האור בכל בחי' כלים הנ\"ל, כי שרשה בכוונה הפנימי' הנמשך מעונג הנעלם שהוא בחי' אור כי תענוג הוא בחי' אור כו' וד\"ל. ..].\n<b>והנה</b> עם כל הנ\"ל יובן מה שאין מבטלין ת\"ת בשביל מצוה שאפשר לעשותה ע\"י אחרים כי לימוד התורה הוא ענין מצ\"ע<sup data-n=\"2590\">55</sup> כי ע\"י לימוד התורה נמשך שפע הפנימי' והעצמות בכל העולמות ולכן נצרך ללמוד<sup data-n=\"2591\">56</sup> אפי' הלכות שאינם צריכים ללמוד בזה\"ג כמו קדשים וטהרות וכן מחמת זה לומדים נשמות בג\"ע את התורה הכל בכדי להמשיך אור העליון דעצמותו ומהותו בכל העולמות, אך אור נצרך להתקבל במקבל דוקא בבחי' הנבראים והעיקר בנש\"י המלובשים בגופים גשמיי' כו' לכן צריך לעשות כלים לאור זה כי בלתי הכלים לא יתקבל במקבל ומה בצע ברב השפע אם לא תתקבל במקבל וע\"י המצות נעשים כלים לאור התורה ולכן מצוה שא\"א לעשותה ע\"י אחרים מוכרח לבטל הת\"ת בשבילה, אך מצוה שאפשר לעשותה ע\"י אחרים אין מבטלין כו' כי יותר טוב ללמוד התורה להמשיך שפע האור בתמידות והכלי תעשה ע\"י אחרים כו' וד\"ל. ועם זה יובן שענין לימוד התורה היא מצוה בעצם מפני שעל ידה ממשיכים אור העליון ואין ענינה ידיעת המצות בלבד ומש\"א גדול תלמוד שמביא לידי מעשה הכוונה שמביא האור ושפע העליון בבחי' המצות כי המצות הם בחי' כלים והתורה ממשיך אורות בכלים כו' וד\"ל.",[["2587","52","<b>ברמב\"ן</b>: אד ניתוסף: זצ\"ל. ה כבפנים. וראה לקמן הערה 63."],["2588","53","<b>אם לא בריתי</b>: ירמי' לג, כה."],["2589","54","<b>כי נר מצוה ותורה אור</b>: משלי ו, כג."],["2590","55","<b>מצ\"ע</b>: אד: מצוה מצ\"ע."],["2591","56","<b>ללמוד</b>: ה: ליתא."]]],[4801940425,"ומעתה יובן מ\"ש בכמה מקומות אני הוי' כו' [... כמו את שבתותי תשמרו ומקדשי תיראו אני הוי'<sup data-n=\"2592\">57</sup> כו'. ..] כי הוי' הוא בחי' י\"ס דאצילות י' חכ' ה' בינה<sup data-n=\"2593\">58</sup> כו' ואני הוא אותיות אין<sup data-n=\"2594\">59</sup> שהוא אור הכתר<sup data-n=\"2595\">60</sup> הממוצע<sup data-n=\"2596\">61</sup> בין המאציל לנאצלים ולכן אומר שע\"י מצות אלו כו' [דמצות שמירת שבת וכיוצא] אני בעצמי מתחבר להתלבש בשם הוי' ולא כמו ההשתלשלות שאינו מאיר רק הארה בעלמא מעצמי' המאציל בחכ\"ע רק עצמי' המאציל ממש נמשך ומתלבש בחכ\"ע והחיבור הוא ע\"י אני שהוא בחי' כתר הממוצע כנ\"ל וד\"ל. והנה עם זה יובן מה שהתורה אינה תלוי' בזמן כלל מצד שהתורה ממשיך אור העליון בכלים וזאת צריך להמשיך בתמידות ולכן נאמר בה והגית בו יומם ולילה<sup data-n=\"2597\">62</sup> אך עשיית הכלים המלבישים את האור שהם המצות שהכוונה בהם ההמשכה בעולמות הנבראים מאין ליש תלוי בזמן כי עולמות הנבראים הם בזמן ומקום ולכן המשכת העצמות הנמשך בהם ע\"י המצות צ\"ל לכאו\"א זמן מיוחד המסוגל לזאת ההמשכה כו' וד\"ל.\n<b>ומעתה</b> יובן ענין הנ\"ל בשם הרמב\"ן<sup data-n=\"2598\">63</sup> שהתורה נאמרה כשלישי המדבר וכן נכתבה בלשון זה כי הנה ענין וידבר הוי' הוא אוא\"ס שבחכ\"ע, אל משה הוא יסוד אבא או בינה או דעת דז\"א<sup data-n=\"2599\">64</sup>, לאמר בחי' מל'<sup data-n=\"2600\">65</sup> ואח\"כ וידבר אל בנ\"י נו\"ה<sup data-n=\"2601\">66</sup> [... כי כללות בנ\"י שהם נש\"י דבי\"ע המלובשים בגופים גשמיי' שרשם מבחי' המוחין דמל' שמקבלת מוחין מבחי' נו\"ה דז\"א ולכן נק' כרעא דאבוה כרגל המוליך את הראש ממקום למקום כן הם ממשיכים אחד האמת המלובש בפנימיות חכ\"ע בארץ הגשמי' ולכן נאמר ומי כעמך ישראל<sup data-n=\"2602\">67</sup> גוי אחד בארץ היינו שממשיכים אחד האמת בארץ הגשמי כו' וד\"ל. ..], והנה לשון זה הי' כתוב בעצמו' המאציל באותיות דגליף גליפו בטהי\"ע כי שם נמדד כך שיומשך מבחי' שם הוי' אל משה וע\"י משה יומשך לבחי' המל' ואח\"כ יתגלה לבנ\"י נשמות שבגופים כו', ואח\"כ כשבא הדבר לידי פועל אחר מ\"ת אז נתגלו אותיות אלו שבעצמות המאציל באצילות ועי\"ז הגילוי נעשה כן באצילות שנמשך אוא\"ס מחכ\"ע דאצילות לבחי' שרש נשמת משה שבאצילות ואח\"כ נמשך המשכה זאת לנש\"י דבי\"ע המלובשים בגופים וגילוי זה",[["2592","57","<b>את שבתותי. . אני הוי'</b>: קדושים יט, ל. בהר כו, ב."],["2593","58","<b>הוי'. . י' חכ' ה' בינה</b>: ראה זהר ויקרא יז, א. תו\"ח ויצא קסז, ג הערה 38."],["2594","59","<b>ואני הוא אותיות אין</b>: ראה פרדס שער אם הא\"ס הוא הכתר ש\"ג, פ\"א. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקמד־ מאמרי אדה\"א דברים ח\"א ע' רלד־ הנחות תקע\"ז ע' ב."],["2595","60","<b>אין שהוא אור הכתר</b>: ראה זהר שלח קנח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"ב ע' תנח־ הנחות תקע\"ז שם."],["2596","61","<b>הכתר הממוצע</b>: ראה ע\"ח שער דרושי אבי\"א שמ\"ב, פ\"א. תו\"ח שמות ח\"א יא, ג הערה 509."],["2597","62","<b>והגית בו יומם ולילה</b>: יהושע א, ח."],["2598","63","<b>הרמב\"ן</b>: א ניתוסף: ז\"ל. ד ניתוסף: זצ\"ל. ה כבפנים. וראה לעיל הערה 52."],["2599","64","<b>משה הוא יסוד אבא או בינה או דעת דז\"א</b>: ראה לקו\"ש שמות כרך ו ע' 244 ואילך."],["2600","65","<b>לאמר בחי' מל'</b>: ראה אוה\"ת אמור כרך ד (כאן) ע' א'עט. סה\"מ תרל\"ח ע' תקיט."],["2601","66","<b>בנ\"י נו\"ה</b>: ראה ת\"ז רתמ\"ח. טעמי המצות וספר הליקוטים להאריז\"ל ר\"פ תשא. מאו\"א מערכת בנ\"י אות נב וביאיר נתיב שם."],["2602","67","<b>ומי כעמך ישראל</b>: דהי\"א יז, כא. ראה גם לעיל ע' סו."]]],[4801940465,"שנגלה מעצמות המאציל אותיות אלו בכח זה הגילוי נפעל כן באצילות כנ\"ל, אך מי המשיך גילוי אותיות אלו שהיו חקוקים בעצמות המאציל הוא הדיבור שבעצמות המאציל [... כמו באדה\"ת המגלה מה שהוא משוער במחשבתו בהעלם ע\"י דיבורו כו'. ..], ומהו הדיבור שבעצמו' המאציל הוא בחי' כתר הממוצע בין המאציל לנאצלים הוא הנק' דיבור של עצמות המאציל שהוא בחי' אחרונה שבעצמו' המאציל וע\"י נעשה מקור להשפעה בנאצלים שפע זאת הפנימי' דתורה כו' [... כמו באדה\"ת הדיבור הוא בחי' אחרונה שבו וע\"י נעשה מקום להשפעת התלמיד המקבל ממנו כו'. ..].\n<b>ובזה</b> יובן לשון הרמב\"ן שבעת גילוי הוי' למשה להמשיך אליו התורה באיכות עשיי' המצות הי' מלובש בזה כח עצמו' המאציל לפעול זה הגילוי וכח זה הי' מלובש בדיבורו שהוא כתר הממוצע כנ\"ל והוא המדבר וממשיך זה הגילוי כנ\"ל וד\"ל, ונמצא שהדיבור והסיפור שכך כתו' בתורה הקדומה וידבר הוי' אל משה הוא עצמות המאציל וע\"י סיפורו נעשה ונמשך שפע זאת באצילות בבחי' חכ\"ע ונעשה ג\"כ באצילות כך שנמשך מחכ\"ע למשה וממנו נמשך לבחי' המל' ולבנ\"י כו' וד\"ל. והנה אח\"כ בעת הכתיבה [... ויש בזה ב' דיעות אם נכתבה כל פרשה בזמנה ומועדה או נכתבה כל התורה בסוף שנת הארבעים<sup data-n=\"2603\">68</sup> כו'. ..], נמשך מחדש כח עצמו' המאציל ע\"י כתר הממוצע להלביש כל התורה באותיות הכתב [... והטעם שנצרך לזה כי ע\"י הדיבור שדיבר לא נמשך שפע התורה רק בעולמות הרוחני' עד עולם היצירה ועד בכלל, אך ע\"י הכתיבה נתלבש שפע הפנימי' דתורה בעשי' גשמי' כו' וד\"ל. ..]. ובזה יובן לשון הרמב\"ן שמשה כסופר המעתיק מספר קדמון כו', הנה ספר קדמון הם האותיות דגליף גליפו נק' קדמון ע\"ש שקדמה גם לעולם הנאצל דא\"ק כו' ומשם נמשך כח שיומשכו אותיות אלו ויתלבשו באותיות הכתב, וכח זה הוא ע\"י עתיק הממוצע כו' כנ\"ל, וכח זה נתלבש בנשמת משה והוא הי' המעתיק להלבישם באותיות הכתב ע\"י כח זה דעתיק שהי' מלובש בנשמתו בעת הכתיבה ובכח זה העתיק אותם ולכן נק' בשם מעתיק כו'.\n<b>ועתה</b> י\"ל לשון שארי הפסוקים עם הקדמה הנ\"ל, וי\"ל פסוק כי ביום הזה יכפר<sup data-n=\"2604\">69</sup> שהוא ג\"כ מאמר עצמו' המאציל בלשון נסתר שיכפר ויסלח עוונותי' וכח זה הוא מבחי' סדכ\"ס<sup data-n=\"2605\">70</sup> שלמעלה מבחי' המאציל כו' [... כי מאציל הוא בחי' מל' דא\"ס עם האותיות דגליף גליפו כו' משא\"כ סדכ\"ס הוא בחי' עונג הנעלם בעצמות ששם שרש נש\"י, והוא הסיבה לרצון ומח' דאנא אמלוך ונק' נמלך בנש\"צ<sup data-n=\"2606\">71</sup> כאמור בשם הרה\"מ נ\"ע<sup data-n=\"2607\">72</sup> כו'. ..], ומשם נמשך סליחת עוונות לישראל דוקא כו', וזהו לפני הוי' תטהרו<sup data-n=\"2608\">73</sup> [... ונוכל לומר בד\"א לפני הוי' שבעצמות והוא הוי' שלפני הפ\"ט<sup data-n=\"2609\">74</sup> ובחי' זה",[["2603","68","<b>ב' דיעות. . שנת הארבעים</b>: גיטין ס, א."],["2604","69","<b>כי ביום הזה יכפר</b>: אחרי טז, ל. ראה גם לעיל מאמר ד\"ה זה בסופו."],["2605","70","<b>סדכ\"ס</b>: ראה זהר בהקדמה ב, א. ועוד."],["2606","71","<b>נמלך בנש\"צ</b>: ראה ב\"ר פ\"ח, ז. רו\"ר פ\"ב, ג. לקו\"ש פ' החודש כרך טז ע' 487 בהערה. שע\"ת קטו, ב."],["2607","72","<b>בשם הרה\"מ נ\"ע</b>: ראה גם לעיל ע' סח. וש\"נ."],["2608","73","<b>לפני הוי' תטהרו</b>: המשך הכתוב כי ביום הזה יכפר."],["2609","74","<b>הפ\"ט</b>: ה: הפסיק טעמא."]]],[4801940500,"הוי' נק' בחי' ע\"ס הגנוזות<sup data-n=\"2610\">75</sup> כו', אך כח ומקור דסליחות עוונות הוא גם לפני הוי' זה שהוא בחי' סדכ\"ס הנ\"ל שלמעלה גם מבחי' הוי' שבעצמות כו' וד\"ל. ..], וכ\"ז מדבר ומספר עצמות המאציל שדיבורו הוא כתר הממוצע כנ\"ל וממשיך ע\"י סיפורו כח זה דסדכ\"ס להיות סליחת עוונות וזדונות נעשו כזכיות<sup data-n=\"2611\">76</sup> [... וזהו תטהר\"ו בגי' כת\"ר<sup data-n=\"2612\">77</sup>. ..].\n[והנה להבין ענין וידבר כו' זאת חוקת התורה<sup data-n=\"2613\">78</sup> כו' הוי' לאמר וכתוב בכה\"ח<sup data-n=\"2614\">79</sup> שהכוונה אשר הוי' שבז\"א דיבר אל משה שע\"י חוקת הפרה יתחברו הוי' דאריך בבחי' אמירה דחכ\"ע וציווה מל' צוותא<sup data-n=\"2615\">80</sup> והתחברות, ולפי הנ\"ל הי' כתוב לשון זה בתוה\"ק שבעצמות המאציל ואיך יתפרשו שם ב\"פ הוי', והנלפע\"ד בד\"א, אשר גם בעצמות יש ב' בחי' הוי' רצון הפשוט להיטיב ומח' דאנא אמלוך פעל שיתגלה שתי מדות אלו חסד ומל' בבחי' עצמות והתגלות בחי' מל' יתכן לקרות בשם א\"ס כמאמר בשם הרה\"מ נ\"ע, והנה כמו למטה התגלות המדות מן הרצון הוא ע\"י החו\"ב כן לפני הצמצום התגלות שתי מדות אלו הוא ע\"י הרצון שנתלבש בחו\"ב שבעצמות ועי\"ז נתגלו שתי מדות אלו, ונמצא יש בזה בחי' הוי' כי י\"ה הוא בחי' החו\"ב ובחי' ו\"ה הוא בחי' גילוי החסד דא\"ס שכולל כל המדות הוא בחי' ו', ובחי' גילוי המל' דא\"ס הוא בחי' ה' אחרונה כו', שהוא בחי' מקור להשפעה, וקוש\"י הוא הרצון<sup data-n=\"2616\">81</sup> המתלבש בחו\"ב. והנה שם הוי' זה הוא מקור להשפעת עולמות רק שהוא מקור להשפיע עד אין שיעור, אך הנה ידוע שפנימית הרצון הוא העונג רק עונג זה הוא עונג פרטי ונמשך מבחי' תענוג הפשוט שנק' שעשועי המלך בעצמותו<sup data-n=\"2617\">82</sup>, הוא בחי' אור המאיר לעצמו שהוא גילוי אור עצמותו כמ\"ש ונבדל בערך מהיות מקור להשפעה אך כאשר בא העצמות לכלל גילוי אור ממילא נגלו כל הי\"ס שבהעלם עצמו' שבאים לכלל גילוי אור, וזהו שעשועים יום יום כי שעשועים הוא גילוי אור העצמות, ויום יום הוא בחי' חו\"ב<sup data-n=\"2618\">83</sup> הכוללים כל הי\"ס שמתגלים בבחי' אור לעצמו ואינם עדיין בבחי' מקור להשפעה, וכמו באדה\"ת כאשר הוא בבחי' תענוג ושמחה ומרומם בעצמות נפשו נגלים בו כל הכחות הקבועים ונטועים בעצמות נפשו בבחי' גילוי אור וממילא הוא מוכן לכל מיני השפעה וכאשר יעוררו אותו להשפיע יתהווה בו רצון להשפיע אבל קודם ההתעוררות לא נגלה בו עדיין מקור להשפיע כי הוא",[["2610","75","<b>ע\"ס הגנוזות</b>: ראה פרדס שער סדר האצי' ש\"ה, פ\"ד. שער הצחצחות שי\"א. וראה שם פ\"ג. הנסמן במאמרי אדה\"א דברים ח\"א ע' שמו־ שעה\"י — לקו\"ב — קפט, ג-ד הערה 2."],["2611","76","<b>וזדונות נעשו כזכיות</b>: ראה יומא פו, ב. מאמרי אדה\"א בראשית ע' סג. וש\"נ."],["2612","77","<b>תטהר\"ו בגי' כת\"ר</b>: בלקו\"ת אחרי כו, רע\"ד מציין: לרמ\"ז ס\"פ אחרי."],["2613","78","<b>וידבר כו' זאת חוקת התורה</b>: חוקת יט, א. ב."],["2614","79","<b>בכה\"ח</b>: ה: בכתבי החסידו'. ראה לקו\"ת חוקת נז, ג (בהמאמר ובהביאור. ושם: עתיק)."],["2615","80","<b>וציווה מל' צוותא</b>: המשך הכתוב זאת חוקת. ראה בהערה שלפנ\"ז. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 114. תו\"ח נח סג, ב ובהערה 28."],["2616","81","<b>וקוש\"י הוא הרצון</b>: ראה זהר ויקרא י, ב. פרדס שער שם בן ד' שי\"ט, פ\"ב. אגה\"ת פ\"ד. הנסמן במאמרי אדה\"א קונטרסים ע' תכז."],["2617","82","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל."],["2618","83","<b>שעשועים יום יום. . חו\"ב</b>: משלי ח, ל. ראה גם לעיל ע' עו. וש\"נ."]]],[4801940532,"מרומם ונבדל מבחי' מקור להשפעה וכידוע המאמר דהוה קבדח טובא<sup data-n=\"2619\">84</sup> כו', ונמצא שיש בחי' הוי' בבחי' שעשועי' העצמי' שהוא גילוי הי\"ס הגנוזות בהעלם עצמות בבחי' גילוי אור שהוא בחי' הוי' השני כי הוי' הוא בחי' י\"ס י' חכ' כו', ובזה יתפרש זאת חוקת התורה שהיא מצות פרה אדומה שעל ידה יתחבר הוי' שבשעשועים העצמיי' בבחי' לאמר שהוא רצון הפשוט המתלבש בחו\"ב לגלות שתי מדות דחסד ומל' דא\"ס שנק' מאמר להיותו מקור להשפעה כו' וד\"ל. ..]. [... והנה זהו פי' הלשון<sup data-n=\"2620\">85</sup> כמו שהי' כתוב בתוה\"ק ואח\"כ נתגלה לשון זה באבי\"ע ע\"י שלישי המדבר שהוא עצמות המאציל שדיבורו הוא כתר הממוצע ואח\"כ נתלבש באותיות הכתב ג\"כ ע\"י בחי' עתיק הממוצע כנ\"ל באריכות וד\"ל. ..].\n<b>ועתה</b> יש להבין ענין משנה תורה שכתוב הלשון שמשה הוא המדבר כמו ואתחנן אל הוי' כו' ואתפלל גם בעד אהרן<sup data-n=\"2621\">86</sup> כו', והנה קושי' זו כבר תירצה הרמב\"ן שתחלת הספר הוא אלה הדברים אשר דיבר משה כו' והוא ג\"כ סופר<sup data-n=\"2622\">87</sup> השלישי שהוא עצמות המאציל<sup data-n=\"2623\">88</sup> והוא מספר ב' אומרים<sup data-n=\"2624\">89</sup> כנ\"ל בתחלת המאמר. אך מה שיש להעיר בזה הוא משארז\"ל שמשנה תו' משה מפי עצמו אמרן<sup data-n=\"2625\">91</sup> דמשמע מזה שבמשנה תו' משה הוא המדבר ולא כמו<sup data-n=\"2626\">90</sup> בספרים הראשונים שעצמו' המאציל הוא המדבר כו'. ויובן בהקדם מ\"ש בכהאריז\"ל שיסוד ומל' הם ב'<sup data-n=\"2627\">93</sup> בחי' חותם וחותם<sup data-n=\"2628\">92</sup> הראשון הוא בחי' יסוד וחותם השני הוא במל' כו' [והוא עד\"מ חותם הנחקק בשעוה כו'] ולכן קוראים משנה תורה בליל הושענא רבה כי אז זמן חותם השני כו', והענין הוא כי ד' ספרים הראשונים נמשכו ונתגלו באצילות עצמו וזה הגילוי הי' מספיק לדור המדבר שהם דור דיעה<sup data-n=\"2629\">94</sup> מבחי' עלמא דאתכסייא כו' אך לדור שאחריהם שנכנסו לא\"י הם היו למטה מהם במדריגה כי שרש נשמתם הוא מבחי' עלמא דאתגלייא ולכן לא הספיק להם הגילוי שבד' ספרים הראשונים והוצרך משה רבינו ע\"ה לומר להם משנה תורה ושם כופל כל הדינים ועי\"ז נמשך הגילוי שבד' ספרים הראשונים מאצילות לבי\"ע ע\"י המל' הנק' חותם ואז יכולים ג\"כ הנשמות דעלמא דאתגלייא לקבל אור התורה כו' ולכן נק' משנה תורה כו' מל' משנה למלך<sup data-n=\"2630\">95</sup>",[["2619","84","<b>דהוה קבדח טובא</b>: ראה ברכות ל, ב. לעיל שם הערות 13-14."],["2620","85","<b>הלשון</b>: אד: ל' הרמב\"ן — ראה לשון הרמב\"ן שנעתק בריש המאמר."],["2621","86","<b>ואתפלל גם בעד אהרן</b>: עקב ט, כ. הכתוב שהובא ברמב\"ן הוא כנראה פסוק כו — ראה לעיל הערה 6."],["2622","87","<b>סופר</b>: אד: מספר. ה: סיפור."],["2623","88","<b>שהוא עצמות המאציל</b>: ה: [שהוא עצמות המאציל]."],["2624","89","<b>ב' אומרים</b>: אד: על ב' אומרים. ה: בל' אומרם."],["2625","91","<b>שמשנה תו' משה מפי עצמו אמרן</b>: ראה מגילה לא, ב. מאמרי אדה\"א שמות ח\"ב ע' שלא. וש\"נ. סה\"מ תרל\"ח ע' שלג הערה 20."],["2626","90","<b>מה. . כמו</b>: ניתוסף ע\"פ ה."],["2627","93","<b>ב'</b>: ניתוסף ע\"פ אד."],["2628","92","<b>שיסוד ומל'. . חותם וחותם</b>: ראה פע\"ח שער הלולב שכ\"ט, פ\"ד."],["2629","94","<b>לדור המדבר שהם דור דיעה</b>: ראה זהר בשלח סב, ב. פע\"ח שער חה\"מ שכ\"א, פ\"א. מאמרי אדה\"א דברים ח\"א ע' עו. וש\"נ."],["2630","95","<b>משנה תורה. . משנה למלך</b>: ראה גם מאמרי אדה\"ז תקס\"ח ח\"א ע' רכד. לקו\"ת במדבר טו, ג. יז, ג. תו\"ח שמות ח\"א יד, ד."]]],[4801940558,"כו' כי מלך הוא מל' דאצילות כמ\"ש בבחי' אצילות עצמו שעל ידה נגלו כל האורות עליונים הגנוזים בתורה לנשמות דאצילות שהם מבחי' עלמא דאתכסייא כנ\"ל, ומשנה למלך הוא מל' דמל' דאצילות הנעשית כתר לברי' יצי' עשי' שע\"י בחי' זאת נגלו כל האורות הנ\"ל גם לנשמות דבי\"ע כו'. והנה ידוע שבאצילות עצמו מאיר אוא\"ס ע\"י אמצעות החכ\"ע<sup data-n=\"2631\">96</sup> בלבד כו' והגם שנמשך בכל עולם האצילות שהן זו\"נ דאצילות ע\"י הבינה ואין הבינה משמשת אלא לבחי' מעבר בלבד ולא נשתנה השפע דח\"ע על ידה כו' משא\"כ כשנצרך להאיר בבי\"ע מוכרח להתלבש בבחי' בינה והיינו המסך שבין אצילות לבריאה<sup data-n=\"2632\">97</sup> ששרשו מבחי' בינה<sup data-n=\"2633\">98</sup> כידוע וממילא נשתנה השפע שבאצילות ואז יכולים גם נש\"י דבי\"ע לקבל זה הגילוי. והנה ידוע דמשה זכה לבינה<sup data-n=\"2634\">99</sup> וזהו משה מפי עצמו אמרן כי פי עצמו הוא בחי' הבינה המדבר בפיו בכדי להמשיך אור התורה לנשמות דעלמא דאתגלייא כו'. ונמצא המובן מכל הנ\"ל אשר כל התורה ואפי' משנה תורה קדמה לעולם והיתה כתובה באש שחורה ע\"ג אש לבנה היינו האותיות דגליף גליפו בטהירו עילאה כנ\"ל ואח\"כ נמשכה באצילות ע\"י כתר הממוצע כו' והוא המדבר ומספר שכך כתוב בתורה הקדומה וע\"י דיבור זה נעשה באצילות ג\"כ שנמשך דבר הוי' היינו חכ\"ע אל משה היינו יסוד אבא ומשם נמשך במל' והיינו לאמר ומשם אל בנ\"י שהם בחי' נו\"ה ברא כרעא דאבוה<sup data-n=\"2635\">100</sup> אך בד' ספרים הראשונים לא נשתנית השפע רק נמשכה דרך מעבר בלבד כנ\"ל ומשנה תורה נמשך ע\"י התלבשות גמור בפי משה שהוא בחי' בינה ולכן נתקבל עי\"ז אור התורה לדור שנכנס לא\"י, אך כח זה המלביש שהוא בחי' בינה פי משה שנק' מסך שרשו יותר גבוה והוא כענין תושבע\"פ ששרשה בבחי' סופר למעלה מתושב\"כ שנק' ספר<sup data-n=\"2636\">101</sup> כו'.\n<b>והנה</b> עם כל הנ\"ל יובן ענין הפסוק דמועדי הוי' דמש\"א וידבר הוי' היינו אוא\"ס שבחכ\"ע שנק' הוי' כמ\"ש הוי' בחכ'<sup data-n=\"2637\">102</sup> והוא דיבר והמשיך למשה והודיע לו מועדי הוי' הוי' זה הוא אוא\"ס שבמדות דאצילות שמתייחד במל' דאצי' שהוא מקור הזמן בזמנים<sup data-n=\"2638\">103</sup> אלו הכתובים אח\"כ וכמ\"ש בפ' ד' אשר תקראו אותם במועדם ותרגם ע\"ז די תערעון יתהון בזמניהן שהוא בחי' המל' מקור הזמן כנ\"ל. ואח\"כ אמר אלה הם מועדי ומאמר זה אומר עצמו' המאציל שהוא המדבר ע\"י כתר הממוצע הנ\"ל ואומר שהיחודים האלו הנעשים בזמנים אלו הם מיוחדים בעצמותי ואני הוא המייחד",[["2631","96","<b>שבאצילות. . החכ\"ע</b>: בלקו\"ת תזריע כג, ב מציין לע\"ח שמ\"ז, פ\"ג [ובדפו\"א פ\"ב]. ראה גם הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תקי."],["2632","97","<b>המסך שבין אצילות לבריאה</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פ\"ד. פי\"ג. מאמרי אדה\"א דברים ח\"ג ע' תתפא. וש\"נ."],["2633","98","<b>המסך. . ששרשו מבחי' בינה</b>: ראה ע\"ח שם פי\"ג."],["2634","99","<b>דמשה זכה לבינה</b>: ראה ר\"ה כא, ב. מאמרי אדה\"ז תקס\"ח ח\"א ע' קפה. שעה\"י קי, א."],["2635","100","<b>ברא כרעא דאבוה</b>: ראה ע\"ח שער פרקי הצלם שכ\"ד, פ\"א בשם רז\"ל. מאמרי אדה\"א קונטרסים ע' שלט. וש\"נ. תו\"ח ויקהל ח\"ב שצו, א הערה 118."],["2636","101","<b>תושבע\"פ. . סופר למעלה מתושב\"כ שנק' ספר</b>: ראה ס\"י פ\"א, מ\"א. לקו\"ת תצא לח, ג. סוכות פ, ב. שה\"ש ז, א."],["2637","102","<b>ה' בחכ' </b>[א ניתוסף: יסוד והניח מקום פנוי. ד ניתוסף: יסד ארץ]: משלי ג, יט."],["2638","103","<b>בזמנים</b>: א: ובזמנים."]]],[4801940576,"כי הוא מתלבש במדות דחג\"ת לייחדם במל' כי כך עלה ברצונו שבזמנים אלו יתייחדו ג\"כ יחודים אלו בזמנים אלו עלו במח' עצמו' המאציל ומצידו וכחו נעשו היחודים בזמנים אלו כו' [... והנה זה הלשון הי' כתוב ג\"כ בתוה\"ק ושם הפי' ג\"כ הוי' הראשון דחכ\"ע הגנוז בעצמו' והוי' השני הם מדות הגנוזות בעצמו' שמתייחדים עם המל' דא\"ס כו' ואלה הם מועדי שכך עלה בכוונה הפנימי' שנתלבשה ברצון ומח' דאנא אמלוך הנק' נמלך כמבואר במ\"א [ושרש כוונה זאת הוא בעונג הנעלם שבעצמות כו'] שבזמנים אלו יתייחדו כו' וד\"ל. ..]."],[4801940111,"<b>שב\"ק ויצא תר\"ב</b>\n<b>להבין</b> ענין ההפרש בין שבת ליו\"ט<sup data-n=\"2639\">1</sup>, שבשבת אנו אומרים מקדש השבת דקדושה וקיימא<sup data-n=\"2640\">2</sup> משבת בראשית וביו\"ט אנו אומרים מקדש ישראל והזמנים ישראל דקדשינהו לזמנים<sup data-n=\"2641\">3</sup>, והיינו ע\"י ראש ב\"ד שאומר<sup data-n=\"2642\">4</sup> מקודש החדש וממילא נתקדש הרגל שחל בחדש ההוא, ביום המוגבל בחדש ההוא ע\"פ התורה, ולמה הוא כן שקדושת יו\"ט דייקא יהי' תלוי בישראל, ולא קדושת שבת כו'. ועוד י\"ל בענין הכתוב אלה מועדי הוי' אשר תקראו אותם במועדם<sup data-n=\"2643\">5</sup>, אלה הם מועדי<sup data-n=\"2644\">6</sup>, ומתורגם על מועדי הוי'<sup data-n=\"2645\">7</sup>, מועדי<sup data-n=\"2646\">8</sup> דהוי', וכן בסוף הפסוק<sup data-n=\"2647\">9</sup>, וכן בכל התורה<sup data-n=\"2648\">10</sup>, זולת על אותם במועדם, מתורגם בזמניהון, ולמה הוא כן. ועוד י\"ל בתיקון הנוסח של התפלה שתיקנו לומר מקדש ישראל והזמנים, כלשון התרגום על אותם במועדם, ולמה לא תקנו לומר מקדש ישראל והמועדים כלשון התרגום על מועדי הוי' כו'. והנה מתחלה י\"ל ענין השבת שהוא ע\"ש כי בו שבת וינפש<sup data-n=\"2649\">11</sup>, כמשל אדם השובת ונח ממלאכתו<sup data-n=\"2650\">12</sup>, שבתחלה בעת עשיית המלאכה הי' שכלו ומדותיו בבחי' השפלה",[["2639","1","<b>להבין ענין ההפרש בין שבת ליו\"ט</b>: מאמר זה הוא הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה מאמר ד\"ה והי' אמונת עתך במאמרי אדה\"ז נביאים ע' קטו ואילך. יום א' דשבועות תר\"ו — אוה\"ת שבועות ע' פג ואילך (והנחת ר\"ה יודפס בע\"ה בספרו פלח הרמון). ביום השמע\"צ ליל שמח\"ת תרכ\"ד — אוה\"ת פינחס ע' א'קצ ואילך."],["2640","2","<b>השבת דקדושה וקיימא</b>: ביצה יז, א."],["2641","3","<b>ישראל דקדשינהו לזמנים</b>: ברכות מט, א."],["2642","4","<b>ראש ב\"ד שאומר</b>: ר\"ה כד, א במשנה. רמב\"ם הל' קדוש החדש פ\"ב, ה\"ח."],["2643","5","<b>אלה מועדי הוי'. . אותם במועדם</b>: אמור כג, ד [בדילוג]."],["2644","6","<b>אלה הם מועדי</b>: אמור כג, ב."],["2645","7","<b>ומתורגם על מועדי הוי'</b>: ת\"א שם, ב. ד."],["2646","8","<b>מועדי</b>: כנצ\"ל: מועדיא."],["2647","9","<b>בסוף הפסוק</b>: שם, ב."],["2648","10","<b>וכן בכל התורה</b>: ראה באוה\"ת שבריש המאמר."],["2649","11","<b>כי בו שבת וינפש</b>: חיבור שני כתובים, בראשית ב, ג. תשא לא, יז [ראה גם לקמן מאמר ד\"ה את שבתותי תרי\"ב הערה 16]."],["2650","12","<b>אדם השובת ונח ממלאכתו</b>: ראה גם [בנוסף להדרושים שבהערה 1] לקמן מאמר ד\"ה את שבתותי תקצ\"ח על יד הערה 105. תרי\"ב על יד הערה 17 ואילך. מאמרי אדה\"א שמות ח\"ב ע' תרסה ואילך. וש\"נ. במדבר ח\"ג ע' א'רמב. וש\"נ."]]],[4801940175,"וירידה, כי קודם המלאכה הי' בבחי' עצם הנפש, ועתה בעת המלאכה נתפשטו לחוץ מעצמותם, ונתלבשו בדבר נבדל גשמי, שאין ערוך לו לרוחניות הנפש, וזהו בחי' ירידה והשפלה גדולה מאד [וזהו ג\"כ בחי' עמל ויגיעה להתפשט מבחי' עצם ולהתלבש בדבר נבדל שהוא חוץ מעצמו כו'], אך אחרי גמר המלאכה אז חיות נפשו שנתלבש בדבר הנבדל, חוזר למקורו אשר לוקח משם שהוא לבחי' השכל והמדות שבעצמי' נפשו, ובחי' זאת נק' שביתה ומנוחה [כי הוא היפוך העמל כי חזר מבחי' התפשטות לבחי' עצם כו' וד\"ל].\n<b>וכדוגמא</b> זאת יובן למעלה שבחי' השתל' העולמות מבחי' עצמי' המאציל והבורא נק' בשם מלאכה, ואז נעשה בחי' התפשטות דע\"ס עליונות להתלבש בעולמות הנאצלים ונבראים מאין ליש, שזה נק' בחי' ירידה והשפלה לגבי בחי' ע\"ס, לבא מבחי' עצם לבחי' התפשטות להתלבש בדבר נבדל שהוא בחי' עולמות הנ\"ל, בכדי להוותם ולקיימם מאין ליש [והגם שלמעלה בבחי' הע\"ס אינם עצמי' המאציל, ואינו כמו באדם התחתון שהשכל והמדות הם בחי' עצם הנפש כנ\"ל, מ\"מ נק' הע\"ס בשם עצמות ע\"ש התאחדותם בעצמי' המאציל בתכלית כמאמר איהו וחיוהי חד או\"ג חד<sup data-n=\"2651\">13</sup> כו', ולכן התפשטות שלהם בדבר נבדל נק' בחי' ירידה והשפלה לגביהם כו']. וזהו כי ששת ימים<sup data-n=\"2652\">14</sup> עשה הוי' כו', ששת ימים הם המדות עליונים עם המוחין המלובשים בהם, עשה, היינו שבאו בדרך ירידה והשפלה בהתהוות העולמות בבחי' נבדל מאין ליש שנק' מעשה כו' וד\"ל, ולכן אחרי גמר ההשתלשלות שהוא ע\"י עשרה מאמרות שנמשכו בששת ימי בראשית נעשה אח\"כ שביתה ומנוחה במה שחזר ועלה החיות אלקי שנתפשט מע\"ס העליונים למקורם ושרשם שהוא בחי' עצמות העשר ספי' כו', ולכן נק' בשם שבת שהוא ענין השביתה והמנוחה שהוא התכללות התפשטות החיות בבחי' עצמי' העשר ספי' כו', ולכן בשבת זמן עליות העולמות<sup data-n=\"2653\">15</sup> מחמת עליות החיות אלקי למקורו (כי אינו דומה לעליות החיות באדם שאינו פועל כלום במעשה המלאכה מצד שפעולתו הוא מיש ליש ולכן המעשה שעשה נבדל ממנו אבל למעלה התהוות הוא מאין ליש ואין היש נבדל ממנו כלל ולכן עליות חיות האלקי פועל ג\"כ עלי' בבחי' עולם הנפעל ממנו כו' שאין העלי' בחיצוני' החיות רק בפנימי' החיות ולכן גם בעולמות אין העלי' רק בפנימי' העולמות<sup data-n=\"2654\">16</sup> ולכן אין הפרש",[["2651","13","<b>איהו וחיוהי חד או\"ג חד</b>: ת\"ז בהקדמה ג, ב."],["2652","14","<b>כי ששת ימים</b>: תשא לא, יז. ראה זהר ויחי רמז, א. אמור צד, רע\"ב. מאמרי אדה\"א דברים ח\"א ע' רז ואילך. וש\"נ. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 19 ואילך."],["2653","15","<b>בשבת זמן עליות העולמות</b>: ראה ע\"ח שער פנימיות וחיצוניות ש\"מ, דרוש ג. ח. טו. תו\"ח בא ח\"א קכז, א הערה 667. לקמן מאמר ד\"ה את שבתותי תקצ\"ח בתחילתו."],["2654","16","<b>העלי' רק בפנימי' העולמות</b>: ראה סידור שער המילה קמא, ב. מאמרי אדה\"א ויקרא ח\"ב ע' תשסה. וש\"נ. מאמרי אדה\"א קונטרסים ע' תקלז. וש\"נ. תו\"ח ויקהל ח\"ב תלז, א. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 28."]]],[4801940232,"בחיצוני' בין שבת לימות החול ומוריד גשמי' ומגדל צמחי'<sup data-n=\"2655\">17</sup> כמו בחול כמ\"ש במ\"א כו').\n<b>והנה</b> להבין בתוס' ביאור ענין העלי' דשבת יש להקדים ענין מה שבשבת<sup data-n=\"2656\">18</sup> נק' יום השביעי<sup data-n=\"2657\">19</sup> הלא כבר יש אלפים ורבבות ימים מיום בריאת העולם, ובשלמא בחדשים שייך לקרוא חדש הראשון או השביעי מתחילת היקף החמה<sup data-n=\"2658\">20</sup> כאשר באה נקודה שלה שהיתה בגלגלה בעת הבריאה, אבל בענין הימים כל יום הוא היקף שלם וא\"כ כאשר יבואו הימים במספר יש אלפי' ורבבות ימים מיום הבריאה ואין יתכן לקרותו בשם יום השביעי כו'. אך יש להקדים ענין הבריאה שנברא בששת ימים ולמה לא נבראו כולם ברגע אחת וכדוגמת קושי' רז\"ל והלא במאמר אחד יכול להבראות<sup data-n=\"2659\">21</sup>, והתירוץ הוא להפרע כו' וליתן שכר טוב כו', אך תירוצם אינו רק לקושייתם אבל קושי' זאת קשה עדיין שהי' יכול לברוא בעשרה מאמרות ברגע אחת [כי כל יכול לאמר כמה מאמרות כאחד כמארז\"ל אנכי ולא יהי' לך בדבור אחד<sup data-n=\"2660\">22</sup> נאמרו וכן זכור ושמור<sup data-n=\"2661\">23</sup> כו']. והנה ע\"פ פשוט יש לתרץ שבאם הי' נבראו כללות העולמות ברגע אחת לא הי' שייך ענין השבת [וזהו כללות המכוון בהשתלשלות העולמות ענין השבת דייקא, וזהו\"ע למחר לקבל שכרם<sup data-n=\"2662\">24</sup> שעיקר קיבול שכר שהוא תכלית המכוון הוא באלף השביעי יום שכולו שבת<sup data-n=\"2663\">25</sup> כו'. כמבואר בלק\"א בהג\"ה בפל\"ו].\n<b>אך</b> אמיתת הענין יובן בהקדם שרש ענין הזמן שהוא בבחי' המל' מ לך מ‘לך ימלוך<sup data-n=\"2664\">27</sup> כמבואר בלק\"א ח\"ב פ' זיי\"ן<sup data-n=\"2665\">26</sup>, אך מקור הזמן הוא בבחי' המדות<sup data-n=\"2666\">28</sup>, אך למעלה מבחי' המדות גם בחי' מקור הזמן לא יתכן לומר כי שם הוא למעלה אפי' מבחי' מקור הזמן כמשי\"ת, כי הנה ידוע בהפרש שבין שכל ומדות<sup data-n=\"2667\">29</sup> כי גילוי",[["2655","17","<b>ומוריד גשמי' ומגדל צמחי'</b>: ראה ב\"ר פי\"א, ה. תנחומא תשא לג. בהערה שלפנ\"ז. תו\"ח בשלח ח\"א רטו, ד."],["2656","18","<b>שבשבת</b>: אוצ\"ל: ששבת."],["2657","19","<b>שבשבת נק' יום השביעי</b>: ראה גם [בנוסף להדרושים שבהערה 1] לקו\"ת שה\"ש כה, סע\"א. ובהנסמן במ\"מ לשם ובריש המאמר שם. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רצו וע' חצר. ח\"ב ע' תשמח ובהנסמן במ\"מ לשם. תו\"ח בשלח ח\"א ריח, ד. אוה\"ת בשלח ע' תרלט. ואתחנן ע' רט. סה\"מ תרמ\"ג ע' קל בשולי היריעה."],["2658","20","<b>בחדשים. . היקף החמה</b>: ועד\"ז הוא במאמרי אדה\"ז כאן. ובאוה\"ת כאן: החדשים. . לפי הילוך השמש והירח שבמשך י\"ב חדשים סובבת החמה ושפיר שייך לקרוא ניסן חדש הראשון."],["2659","21","<b>והלא במאמר אחד יכול להבראות</b>: אבות רפ\"ה."],["2660","22","<b>אנכי ולא יהי' לך בדבור אחד</b>: יתרו כ, ב. ג. ראה שו\"ע אדה\"ז חאו\"ח סתצ\"ד, ס\"ח. תו\"ח בראשית מה, ד ובהערה 36. מאמרי אדה\"א הנחות תקע\"ז ע' לז."],["2661","23","<b>זכור ושמור</b>: יתרו כ, ח. ואתחנן ה, יב. ר\"ה כז, א. מכילתא יתרו שם. ראה תו\"ח יתרו ח\"ב רסד, א."],["2662","24","<b>למחר לקבל שכרם</b>: ראה ערובין כב, א."],["2663","25","<b>באלף השביעי יום שכולו שבת</b>: ראה גם תו\"ח בשלח ח\"א רכא, ב ובהערה 557."],["2664","27","<b>מלך מלך ימלוך</b>: ראה זהר בראשית לד, א. אוה\"ת סידור ע' פג ואילך."],["2665","26","<b>הזמן. . המל'. . בלק\"א ח\"ב פ' זיי\"ן</b>: ראה גם לעיל ע' רטז ובהערה 175."],["2666","28","<b>מקור הזמן. . המדות</b>: ראה גם (בנוסף על הדרושים שבהערה 1) לעיל ע' רטז ובהערה 177."],["2667","29","<b>בהפרש שבין שכל ומדות</b>: ראה גם לעיל ע' קטז. וש\"נ."]]],[4801940285,"השכל ימצא גם בעצמו גם כשאין זולתו מי להשפיע אליו כמו חכם עמוק שיכול להשכיל השכלות עמוקות בעצמו גם כשאינו רוצה כלל בהשפעה (ואדרבה טבע החכ' להיות בבחי' ביטול במקורה בעומק אחר עומק ולא בבחי' ירידה והשפעה למטה כו') אבל בחי' המדות לא יתכן רק לזולתו כמו כח החסד שענינו הוא להטיב לזולתו או טבע הגבורה למנוע השפע מזולתו כו' ות\"ת לרחם לזולתו וכן כל המדות אינו שייך רק לזולתו הנבדל כו' (אך במ\"א מבואר שמדת המלוכה לא יתכן בלי מציאת זולתו כי אין מלך בלא עם<sup data-n=\"2668\">31</sup> אבל בחי' שאר המדות<sup data-n=\"2669\">30</sup> יתכן גם בלא זולתו<sup data-n=\"2670\">32</sup> היינו שמציאותם יכול להיות גם כשאין מציאת זולת בפועל כמו החסדן בטבע שנקודת רצונו תמיד להשפיע חסד וטוב גם כשאין עדיין מציאות זולתו בפ\"מ להטיב אליו אך מ\"מ הוא בחי' כח ומקור לזולתו הנבדל כו' משא\"כ גילוי המלוכה לא יתכן רק כשיש מציאות זולתו בפועל הנבדל, ונמצא שבחי' המדות הוא כח ומקור לשפע הנמשך לזולתו ובחי' המלוכה הוא בחי' השפע בפ\"מ לזולתו הנבדל כו').\n<b>והנה</b> ע\"ד דוגמא זאת יובן למעלה שגם שנמשך בחי' חו\"ב מבחי' העלם עצמות המאציל שזהו ג\"כ ירידה והשפלה לגבי עצמותו ממש מ\"מ הוא רק בחי' גילוי עצמי' שנגלה לעצמו ואינו בגדר מקור לעולם הנברא מאין ליש ולכן נק' חכים ולא בחכ' ידיעא כו' ולא בבינה ידיעא<sup data-n=\"2671\">33</sup> כי אינו מושג הגילוי עדיין לזולתו הנבדל ממנו כבי' רק הגילוי הוא לעצמו, אבל בחי' המדות שנאצלו מעצמי' המאציל הוא בחי' מקור לעולם הנברא מאין ליש ולכן נאמר כי אמרתי עולם חסד יבנה<sup data-n=\"2672\">34</sup> שבחי' ההתחלה להיות מקור לבנין העולמות הוא מבחי' החסד, וזהו שבחי' ז' מדות נק' בלשון המקובלים בשם ז' ימי הבנין<sup data-n=\"2673\">35</sup> להיותם מקור לבנין העולמות כו' [אך בחי' ז' המדות הם בחי' מקור בלבד לעולמות ולא נתהווה עדיין מציאות העולמות בפ\"מ אבל בחי' מדת המלוכה מהווה<sup data-n=\"2674\">*36</sup>* מציאות העולמות בפ\"מ מאין ליש כו']. ועם זה יובן ענין כי ששת ימים עשה ה', כי ענין היום למעלה אינו כמו יום שלמטה בגשמי' רק הוא בחי' הארה בלבד<sup data-n=\"2675\">36</sup> שהוא מקור לעולם הנברא<sup data-n=\"2676\">37</sup> ביום הראשון הוא בחי' חסד",[["2668","31","<b>אין מלך בלא עם</b>: ראה שער היחוה\"א פ\"ז ובמ\"מ הגהות והע\"ק שם. בחיי וישב לח, ל. הנסמן במאמרי אדה\"ז על פרשיות התורה ח\"ב לע' תרלא."],["2669","30","<b>שמדת המלוכה. . שאר המדות</b>: ראה גם המשך תער\"ב ח\"ג ע' א'שסב ואילך."],["2670","32","<b>המדות יתכן גם בלא זולתו</b>: ראה גם ד\"ה אלה פקודי תש\"ל ס\"ג. וש\"נ [קונט' כ\"ה אדר תנש\"א — סה\"מ מלוקט ה ע' רא]."],["2671","33","<b>חכים. . ולא בבינה ידיעא</b>: ת\"ז בהקדמה יז, ב."],["2672","34","<b>כי אמרתי עולם חסד יבנה</b>: תהלים פט, ג. ראה לעיל ע' קיג. וש\"נ."],["2673","35","<b>ז' ימי הבנין</b>: ראה גם פרדס שער מהות והנהגה ש\"ח, פ\"ב. פ\"ו. שער השערים שי\"ג, פ\"ה. שפע טל שער סוד אבי\"ע ש\"ג, פ\"ב. תניא פ\"ג. לעיל ע' קיג (נו\"א). ולהעיר מלקו\"ש וארא כרך כו ע' 311 הערה 6."],["2674","*36","<b>המדות. . מקור. . המלוכה מהווה</b>: ראה לקמן מאמר ד\"ה וספרתם הה' ובהערה 25. ד\"ה את שבתותי תרי\"ב על יד הערה 24. לעיל ע' רב. ע' עח. תו\"ח בא ח\"א ק, ב ובהערה 162."],["2675","36","<b>בלבד</b>: בהכת\"י באים כאן עוה\"פ התיבות: רק כשהוא בחי' הארה."],["2676","37","<b>הנברא</b>: בהכת\"י באים כאן עוה\"פ התיבות: שהם מקור לעולם הנברא."]]],[4801940335,"לכן נברא ממנו אור<sup data-n=\"2677\">38</sup> ומים שהם בחי' חסד<sup data-n=\"2678\">39</sup> וביום ב' שהוא בחי' גבור נברא ממנו בחי' רקיע שהוא פעולת הגבורה<sup data-n=\"2679\">41</sup> להבדיל בין מים למים, וכן עד\"ז בכל הימים כל יומא בעבידתי' כו'.\n<b>והנה</b> עיקר ההפרש בין חכ' למדות שבחי' חכ' הוא הארה עצמי' כשאינו מקור עדיין להשפעה מיוחדת בפרט משא\"כ בחי' המדות כל מדה הוא מקור להשפעה מיוחדת בפרט דייקא, ולכן ביום א' האיר מבחי' החסד בלבד ולא מבחי' הגבורה לכן נברא ממנו אור ומים וביום ב' האיר מבחי' הגבורה ולא מבחי' החסד לכן נברא ממנו הרקיע, נמצא שבכל פעולה מבחי' הנבראים אינו מאיר בו רק הארה פרטית וזהו\"ע הזמן שהוא התחלקות הנבראים שלכל נברא יש לו זמן מיוחד בפ\"ע וכפי ריבוי הנבראים כ\"ה שכל חיות פרטי הוא בזמן מיוחד בפ\"ע, וכ\"ה עד\"ז בבחי' מקום שהוא בחי' השתלשלות לכל נברא מקום מיוחד בפ\"ע, אך עכ\"ז הוא בבחי' גילוי ההשתלשלות בפ\"מ אך מקור הזמן הוא בחי' ו' ימים שהם ששה הארות כי יום הוא בחי' הארה כמ\"ש ויקרא אלקים לאור יום<sup data-n=\"2680\">42</sup> כו' וכל הארה כשנמשכה בפ\"מ בבי\"ע נעשה מזה אלף שנה בעיניך<sup data-n=\"2681\">43</sup> כיום אתמול כו' שבחי' יום אתמול הוא בחי' היום דאצי' הוא הארה כללי' וכאשר מאיר בבי\"ע נתחלק לאלף שנה בפרט, וכל שנה יש בו ראש השנה שהוא מקור<sup data-n=\"2682\">44</sup> לכל השנה ג\"כ בכלל ונתחלק בפרט לי\"ב חדשי השנה וכל חודש ל' יום, וכ\"ז ההתחלקות בפרט הוא בחי' הזמן בפ\"מ אך למעלה בו' יומין עילאין דאצי' אינו בחי' הזמן בפ\"מ רק מקור הזמן אך גם מקור הזמן הוא בחי' כח להאיר הארה מיוחדת בפרט בכל יום בפ\"ע כמו ביום א' בחי' חסד בלבד כנ\"ל, משא\"כ בחי' חו\"ב הוא למעלה מהזמן שהוא בחי' גילוי פשוט שאינו עדיין בחי' מקור להאיר הארה פרטי' רק כשמאיר נמשך ממנו בחי' גילוי פשוט הכולל כל הארות פרטי', וזהו ג\"כ מה שנאמר במן דבר יום ביומו<sup data-n=\"2683\">45</sup> כי הגם שבחי' מן הוא בחי' הארה מלמעלה מהזמן מ\"מ נמשך בזמן לכן הארה שהאיר ביום זה לא הי' יכול להיות ממנו מזון ביום שאחריו כו'. ובזה יובן ענין המדרש מלמד שהי' סדר זמנים<sup data-n=\"2684\">46</sup> קודם לכן דקאי על בחי' מקור הזמן שנק' סדר זמנים שבא בסדר מיוחד בתחלה האיר בחי' החסד ולא נתגלה עדיין מציאת גבו' ואח\"כ נתגלה מציאת גבורה, וממילא נתעלם גילוי החסד, וכ\"ז הוא בחי' מקור הזמן שהוא<sup data-n=\"2685\">47</sup> קודם לכן פי' קודם לבריאה מאין ליש כי מקור הזמן הוא בבחי' אצי' עדיין כו' כנ\"ל.",[["2677","38","<b>חסד. . אור</b>: ראה גם אוה\"ח לזהר בראשית מו, א. מאמרי אדה\"א דברים ח\"ד ע' א'תמו. וש\"נ. תו\"ח תצוה ח\"ב שיט, א. וש\"נ."],["2678","39","<b>ומים. . חסד</b>: ראה זהר תרומה קסז, א. קעה, ב. שמיני מא, א. מאמרי אדה\"א דברים ח\"ד ע' א'שצב.\n40)גבור: כנצ\"ל: גבורה."],["2679","41","<b>רקיע. . הגבורה</b>: ראה גם המשך מים רבים תרל\"ו פי\"ט ע' כו. סה\"מ תרל\"ח ע' עא."],["2680","42","<b>ויקרא אלקים לאור יום</b>: בראשית א, ה."],["2681","43","<b>אלף שנה בעיניך</b>: ע\"פ תהלים צ, ד. ראה מאמרי אדה\"א דברים ח\"א ע' רז ואילך. ח\"ג ע' תתה ובהנסמן בהנ\"ל."],["2682","44","<b>ראש השנה שהוא מקור</b>: ראה גם מאמרי אדה\"א דברים ח\"א ע' רסח. וש\"נ."],["2683","45","<b>דבר יום ביומו</b>: בשלח טז, ד."],["2684","46","<b>מלמד שהי' סדר זמנים</b>: ראה ב\"ר פ\"ג, ז."],["2685","47","<b>שהוא</b>: אוצ\"ל: שהי'."]]],[4801940382,"ועם כל הנ\"ל יתורץ קושיא למה לא נמשכו כל העשרה מאמרות ברגע אחת, כי אם הי' התהוותם ברגע אחת לא הי' מציאת גילוי הנבראים בפרט כ\"א בפ\"ע וגם לא בבחי' סדר ההשתלשלות כ\"א קודם לחבירו מתחילה לסוף רק הי' מאיר כל הפרטים כאחד וממילא לא הי' מציאת סדר זמן ומקום, ולהיות שפנימי' הכוונה הי' שיהי' בחי' ריבוי והתחלקות דווקא ואח\"כ יתגלה בהם בחי' הביטול לבחי' אחדות הפשוטה לזאת היתה הבריאה בששה ימים דווקא שהוא בחי' סדר זמנים כנ\"ל וד\"ל. ועתה יובן ענין השבת שנק' תמיד בשם יום השביעי, כי הנה מבואר למעלה שיום הוא בחי' אור, והנה ששה ימים הם בחי' ששה הארות בדרך ירידה והשפלה מבחי' העצמי' שהוא מלמעלה להתלבש<sup data-n=\"2686\">48</sup> בזמן שהוא בחי' ריבוי והתחלקות אך אחרי גמר המלאכה שגורם שביתה ועלי' אז ממילא נתגלה בחי' שלמעלה מהזמן שהוא בחי' חכים ולא בחכמה ידיעא כנ\"ל וממילא בטלים ונכללים כל הארות המחולקים שבזמן שזהו\"ע עלי' הזמן בלמעלה מן הזמן ואז מאיר בזמן הגילוי דלמעלה מן הזמן כמו שהוא בעצם ונק' הארה זאת יום השביעי שהוא הארה בדרך עלי', ולזה אין שייך למנותו במספר הימים כי הוא גילוי מיוחד בפ\"ע שאינו בחי' ירידה כלל, וגילוי זה נק' יום השביעי והוא מאיר ממילא מצד השביתה מגמר המלאכה כנ\"ל וד\"ל.\n<b>ועם</b> זה יובן מה שבכל ששת בראשית<sup data-n=\"2687\">49</sup> לא נז' שם הוי' כלל רק ל\"ב ויאמר אלקים<sup data-n=\"2688\">50</sup> שהוא שרש ומקור הזמן שהוא הכח להאיר בריבוי והתחלקות שבא מצד צמצום דשם הוי' אבל בחי' שם הוי' הוא בחי' הגילוי דאחה\"פ הכוללת כל הארות של התחלקות הזמן כאחד וזהו\"ע הוי' הי' הווה ויהי' כאחד<sup data-n=\"2689\">51</sup> והוא למעלה מהזמן לגמרי לכן אינו מאיר בששת ימ\"ב רק ע\"י צמצום והסתר דשם אלקי' משא\"כ כשבא שבת בא מנוחה<sup data-n=\"2690\">52</sup> נתגלה שם הוי' בעולמות שהו\"ע הגילוי דלמעלה מן הזמן שמאיר בזמן בדרך עלי' כנ\"ל, לכן אחרי השבת כתיב ביום עשות הוי' אלקים<sup data-n=\"2691\">53</sup> שנתגלה שם הוי' באלקים כו' וד\"ל. וזהו ג\"כ ענין שילוב הוי' באדני<sup data-n=\"2692\">54</sup>, ששם אדני<sup data-n=\"2693\">55</sup> הוא מקור הזמן כנ\"ל שבחי' זמן הוא במל' מ לך מ‘לך ימלוך שזהו שם אדני אנת אשתמודעא אדון על כולא<sup data-n=\"2694\">56</sup> והוא מסתיר על שם הוי' שזהו\"ע ששה ימי החול, משא\"כ יום השבת הוא",[["2686","48","<b>מלמעלה להתלבש</b>: אוצ\"ל: מלמעלה מהזמן להתלבש."],["2687","49","<b>ששת בראשית</b>: אוצ\"ל: ששת ימי בראשית."],["2688","50","<b>ל\"ב ויאמר אלקים</b>: נמנו בפרטיות בתקז\"ח קיב, ג. ראה מאמרי אדה\"א ויקרא ח\"ב ע' תרכה. וש\"נ. שעה\"י קלב, א ובהערה 3."],["2689","51","<b>הוי' הי' הווה ויהי' כאחד</b>: ראה שער היחוד והאמונה פ\"ז. תו\"ח מקץ ריט, ד הערה 62."],["2690","52","<b>כשבא שבת בא מנוחה</b>: תוד\"ה חצבה סנהדרין לח, א. ראה רש\"י בראשית ב, ב. רש\"י מגילה ט, א ד\"ה ויכל. ב\"ר פ\"י, ט."],["2691","53","<b>ביום עשות הוי' אלקים</b>: בראשית ב, ד. ראה גם באוה\"ת שבהערה 1."],["2692","54","<b>שילוב הוי' באדני</b>: ראה מבו\"ש ש\"ג ח\"ב ספ\"ה. לקו\"ת ש\"ש סה, ד ובהנסמן במ\"מ לשם סד, ב. תו\"ח וארא ח\"א נ, א הערה 32. וראה גם לעיל ע' צה."],["2693","55","<b>במל'. . אדני</b>: ראה זהר ויקרא יא, א. ראה מאמרי אדה\"א בראשית ע' קצז. וש\"נ. תו\"ח נח סד, ג הערה 44."],["2694","56","<b>אנת אשתמודעא אדון על כולא</b>: ת\"ז בהקדמה יז, רע\"ב. ראה תו\"א מג\"א קיז, ג. לקו\"ת אמור לב, ב. שער היחוה\"א רפ\"ז. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 111."]]],[4801940426,"שילוב אדני בהוי'<sup data-n=\"2695\">57</sup> ששם אדני נכלל בבחי' ביטול בשם הוי' ואז מאיר בחי' למעלה מן הזמן בבחי' גילוי, וזהו ענין שבת דקדישא וקיומא<sup data-n=\"2696\">58</sup> היינו שמאיר בחי' קדש העליון שהוא למעל' מן הזמן ממילא ומאיליו מצד השביתה שמגמר המלאכה ואינו תלוי בקדושת ישראל כי אינו תלוי במעשה התחתונים כו' וד\"ל. והנה אנו אומרים ושבת קדשו<sup data-n=\"2697\">59</sup> באה' וברצון הנחילנו כו' שאע\"פ שקדושת שבת אינו תלוי בישראל מ\"מ ניתנה במתנה<sup data-n=\"2698\">60</sup> לישראל דווקא, היינו שבהם דווקא מאיר הארה זאת דבחי' הביטול דזמן בלמעלה מן הזמן (כנ\"ל שהארה זאת הוא רק בפנימי' העולמות וידוע דשרש הנשמות בפנימי' הכלים<sup data-n=\"2699\">61</sup> לכן מאיר בהם דווקא הארה זאת כו').\n<b>והנה</b> ענין הארה זאת בנש\"י מה היא יובן בהקדם ענין שבת עילאה ושבת תתאה<sup data-n=\"2700\">62</sup> ושבת אותיות תשב<sup data-n=\"2701\">63</sup> והו\"ע תשובה עילאה ותשובה תתאה<sup data-n=\"2702\">64</sup> כו', כי ע\"י תשובה שבימות החול שבנש\"י מאיר עי\"ז בהם הארת השבת וכמאמר מי שטרח בערב שבת<sup data-n=\"2703\">65</sup> יאכל בשבת. וביאור ענין התשובה יובן בהקדם ענין תשובה קדמה לעולם<sup data-n=\"2704\">66</sup> האיך שייך ענין תשובה כשאין עולם עדיין. אך הנה ידוע דישראל עלה במח'<sup data-n=\"2705\">67</sup> דשרש נש\"י הוא בלמעלה מן הזמן שהוא בחי' חכים ולא בחכ' ידיעא, וזהו בחי' מזלא שבנשמה כמארז\"ל אע\"ג דאיהי לא חזי מזלייהו חזי<sup data-n=\"2706\">69</sup> והיינו שבחי' עצמי' הנשמה<sup data-n=\"2707\">68</sup> שהוא בחי' כח מה שבנה\"א רואה בתמידות ענין הביטול דזמן כמ\"ש בלמעלה מן הזמן, וע\"ז נאמר נשמה שנתתה בי טהורה היא<sup data-n=\"2708\">70</sup> והיינו שהיא מושללת מחלקי הכלים דנר\"נ שהו\"ע השגה למדות באלקי'<sup data-n=\"2709\">71</sup> אבל בחי' ראי' הוא למעלה מן השגה כי אינו מלובש בכלים ואותיות כלל לכן נקראת בשם טהורה והיינו מצד",[["2695","57","<b>שילוב אדני בהוי'</b>: ראה הערה 54."],["2696","58","<b>וקיומא</b>: כנצ\"ל: וקיימא."],["2697","59","<b>אנו אומרים ושבת קדשו</b>: בקידוש ליל שבת. ראה גם מאמרי אדה\"א שמות ח\"א ע' רכו ואילך."],["2698","60","<b>שבת. . ניתנה במתנה</b>: שבת י, ב."],["2699","61","<b>דשרש הנשמות בפנימי' הכלים</b>: ראה ע\"ח שער העיבורים שכ\"ח, פ\"א. שער פו\"ח ש\"מ, דרוש י. מאמרי אדה\"א ויקרא ח\"א ע' צט. וש\"נ. דברים ח\"ג ע' תשסח. וש\"נ. תו\"ח בשלח ח\"א רמ, ד ואילך."],["2700","62","<b>שבת עילאה ושבת תתאה</b>: זהר בהקדמה ה, ב. ראה גם לקמן מאמר ד\"ה את שבתותי תקצ\"ח בתחילתו. תרי\"ב בתחלתו. שע\"ת יב, ג ובהערה 34."],["2701","63","<b>ושבת אותיות תשב</b>: ראה אגה\"ת ספ\"י. מאמרי אדה\"א דברים ח\"ד ע' א'קפ. וש\"נ. תו\"ח נח נה, ב ובהערה 20. יתרו ח\"ב רסו, ג. סה\"מ תרכ\"ז ע' קכז. תרל\"ו ע' קצז. קצט. לקמן מאמר ד\"ה את שבתותי תקצ\"ח בתחילתו. תרי\"ב בתחלתו. ביאור לד\"ה והתהלכתי תר\"ב על יד הערה 73."],["2702","64","<b>תשובה עילאה ותשובה תתאה</b>: זהר רע\"מ נשא קכג, א."],["2703","65","<b>מי שטרח בערב שבת</b>: ע\"ז ג, א. ראה גם מאמרי אדה\"א דברים ח\"ד ס\"ע א'קפב ואילך. נ\"ך ע' תעא."],["2704","66","<b>תשובה קדמה לעולם</b>: פסחים נד, א. ראה מאמרי אדה\"א דברים ח\"ב ע' תקצז. וש\"נ. הנחות תקע\"ז ע' קלו וע' קע. לעיל ע' רא ובהערה 37."],["2705","67","<b>דישראל עלה במח'</b>: ראה ב\"ר פ\"א, ד. שע\"ת קטו, ב. תו\"ח שמות ח\"א לב, ב ובהערה 248."],["2706","69","<b>אע\"ג דאיהי </b>[כנצ\"ל: דאיהו]<b>. . מזלייהו חזי</b>: מגילה ג, א."],["2707","68","<b>מזלא שבנשמה. . עצמי' הנשמה</b>: ראה גם לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב ובהערה 25."],["2708","70","<b>נשמה שנתתה בי טהורה היא</b>: ברכת אלקי נשמה (ברכות ס, ב)."],["2709","71","<b>למדות באלקי'</b>: כנצ\"ל: ומדות באלקות."]]],[4801940466,"שרשה במח' חשב מ\"ה<sup data-n=\"2710\">72</sup> דחכ' שהוא ג\"כ בחי' חכים ולא בחכ' ידיעא באותיות כו'. אך אתה בראת יצרתה והיינו שנתלבשה בחי' זאת בנר\"נ ומצד זה כח זה הוא בבחי' הסתר והעלם מצד הלבושים דנר\"נ ומצד הסתר דנה\"ט, לכן ניתן בנשמה כח התשובה שהוא בחי' התבוננות באלקות וכמ\"ש בלק\"א פ' כ\"ה (כי מקובלים ראשונים קורין לבינה בשם תשובה<sup data-n=\"2711\">73</sup> והיינו פנימי' בינה שהוא בחי' התבוננות איך דכולא קמי' כלא<sup data-n=\"2712\">74</sup> ממש כו' ולא בחי' התבוננות איך דהוא חייך<sup data-n=\"2713\">75</sup> שזהו חיצוני' בינה שאינו נק' בשם תשובה כו'<sup data-n=\"2714\">76</sup>, והיינו כשמתבונן ענין ביו\"ד נברא עוה\"ב<sup data-n=\"2715\">77</sup> כי הנה יש בחי' עוה\"ב ועוה\"ז היינו בחי' המקום וזמן גשמי' הנגלה לעינינו נק' העוה\"ז אך למעלה בחי' זמן ומקום הוא בבחי' פני ארי' פני שור פני נשר<sup data-n=\"2716\">78</sup> שהו\"ע מעלה ומטה ברוחני' ובחי' זמן ברוחניות ועוד למעלה יותר בו\"ק דאצי' נק' סדר זמנים כנ\"ל, וכ\"ז נברא רק ביו\"ד אחת<sup data-n=\"2717\">79</sup> שהוא ענין הברקה אחת מעצמי' המאציל, והנה ע\"ד ביטול אחת לגבי כח המח' שאינו תופס מקום כלל כן ויותר ע\"כ הוא ביטול היו\"ד לגבי עצמי' המאציל (וכמ\"ש במ\"א בענין כי לא מחשבותי מחשבותיכם<sup data-n=\"2718\">80</sup> שיש הפרש בין מחשבת האדם שנתפס במחשבתו עד שבשעת מעשה אינו יכול להתפס במח' אחרת א\"כ המח' תופסת מקום קצת לגבי כח המח' משא\"כ למעלה אע\"פ שנתפס במחשבה זו שהוא מקור העולמות מ\"מ אינו תפיסא גמורה כי לית מאן דתפיס בי'<sup data-n=\"2719\">81</sup> ולכן יכול להתפס בשעת מעשה במח' אחרת וא\"כ מח' אחת הנ\"ל שהוא בחי' היו\"ד הנ\"ל אינו תופס מקום כלל לגבי עצמי' המאציל כו'), וכשמתבונן בזה נגלה בחי' מזלא בנר\"נ עד שנעשה אצלו בחי' ביטול נכללין<sup data-n=\"2720\">82</sup> בלב שלא לחפוץ בשום דבר גשמי' ורוחני' רק להכלל ולהבטל בעצמי' המאציל וכמ\"ש מי לי בשמים<sup data-n=\"2721\">83</sup> שזהו ג\"ע העליון ועמך לא חפצתי בארץ שזהו געה\"ת רק כלה שארי ולבבי<sup data-n=\"2722\">84</sup> לעצמותו ומהותו ממש, ובחי' זאת נק' תשובה שפועל שהרוח תשוב אל האלקים<sup data-n=\"2723\">85</sup> אשר נתנה והיינו שנכלל במקורו אשר לוקח משם שזהו בחי' שרש הנשמה בבחי' חשב מה דחכ' שהוא ענין כלות הנפש לבחי' חכים ולא בחכ' ידיעא שזהו בחי' אוא\"ס עצמו ששורה בחכ', וזהו\"ע תשובה קדמה לעולם היינו שמגעת לבחי' חכים ולא בחכ' ידיעא אשר הוא",[["2710","72","<b>במח' חשב מ\"ה</b>: זהר בראשית כד, א. ת\"ז תס\"ט קיב, ב."],["2711","73","<b>מקובלים ראשונים קורין לבינה בשם תשובה</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"א. שער עה\"כ שכ\"ג, פכ\"ב מערכת תשובה. לעיל ע' רא ובהערה 35."],["2712","74","<b>דכולא קמי' כלא</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"ז תקס\"ו ע' שמא. מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["2713","75","<b>דהוא חייך</b>: נצבים ל, כ."],["2714","76","<b>כו'</b>: כנצ\"ל: כו')."],["2715","77","<b>ביו\"ד נברא עוה\"ב</b>: ראה מנחות כט, ב."],["2716","78","<b>פני ארי'. . נשר</b>: יחזקאל א, י."],["2717","79","<b>אחת</b>: כנצ\"ל: אות אחת."],["2718","80","<b>כי לא מחשבותי מחשבותיכם</b>: ישעי' נה, ח. ראה גם מאמרי אדה\"א נ\"ך ע' רנ ואילך. תו\"ח ויחי רמה, א ואילך."],["2719","81","<b>לית מאן דתפיס בי'</b>: ראה זהר רע\"מ פינחס רכה, א. הנסמן במאמרי אדה\"א דברים ח\"א ע' קפב. תו\"ח נח סו, ג הערה 30. לעיל ע' רכא."],["2720","82","<b>נכללין</b>: כנצ\"ל: וכליון."],["2721","83","<b>מי לי בשמים</b>: תהלים עג, כה. ראה ספר המצות להצ\"צ קלח, א. סה\"מ תרמ\"ו ע' כ. תרע\"ח ע' תלג (במהדורת תשד\"מ). מאמר ד\"ה ביום עשתי עשר יום י\"א ניסן תש\"ל פ\"ח-ט (קונט' י\"א ניסן תשמ\"ט — סה\"מ מלוקט ג ע' קו-ז). תו\"ח תצוה ח\"ב שנו, ב. וש\"נ. לעיל ע' קיא. מגדל עז ע' קעג."],["2722","84","<b>כלה שארי ולבבי</b>: תהלים עג, כו."],["2723","85","<b>שהרוח תשוב אל האלקים</b>: קהלת יב, ז."]]],[4801940501,"למעלה מהיות מקור עולם כנ\"ל. וזהו ברגע קטן עזבתיך<sup data-n=\"2724\">86</sup> וברחמים גדולים אקבצך, שלכאורה אינו היפך כלל מזה לזה, אך כשמאיר בחי' רחמים גדולים שהוא בחי' הארה בעצמי'<sup data-n=\"2725\">87</sup> אוא\"ס שהוא למעלה מן הזמן אז הוא מבין איך שכל האריכות הגלות אינו תופס מקום כלל רק כרגע קטן כו' וד\"ל.\n<b>והנה</b> זמן גילוי דכח זה דכלות הנפש ע\"י התבוננות הנ\"ל הוא בק\"ש באמרו שמע ישראל, שתי' שמע הוא התבוננות הנ\"ל בביטול מקור ההשתלשלות למהו\"ע ועי\"ז נעשה למסי\"נ באחד<sup data-n=\"2726\">88</sup> שהוא ענין כלה שארי ולבבי, וזהו\"ע הארת השבת שמאיר בכל יום בפרט שישוב למקורו לבחי' למעלה מן הזמן שזהו בחי' תשובה ועי\"ז מאיר בשבת בחי' נשמה יתירה<sup data-n=\"2727\">89</sup> שהוא ענין הביטול דכללות ששה ימים שהוא מקור הזמן בלמעלה מן הזמן ובחי' זאת מאיר בנש\"י בשבת, וע\"ז אנו אומרים ושבת קדשו כו' הנחילנו שניתן במתנה לנש\"י וכמ\"ש קדש ישראל<sup data-n=\"2728\">90</sup> להוי' שבחי' קדש דשבת מאיר בנש\"י להיות שרשם ג\"כ בבחי' קדש כו'. והנה אחרי שמאיר בנש\"י בחי' קדש ע\"י השבת כנ\"ל אז ישראל המה מקדשים את הזמנים ולכן נכתב בפ' מועדות מקודם ענין השבת<sup data-n=\"2729\">91</sup> כי הא בהא תליא, כי הנה ענין המועדים ע\"פ רוב הם ביום חול שהוא מציאת הזמן כנ\"ל, וכשמקדשים אותו ע\"י קידוש החודש שראש ב\"ד אומר מקודש אז ממשיכים בו גילוי קדש העליון שהוא בחי' למעלה מן הזמן רק שהוא בדרך המשכה מלמעלה מן הזמן בזמן ולא כמו בשבת שהוא בחי' העלאה נתעלה<sup data-n=\"2730\">92</sup> הזמן לבחי' למעלה מן הזמן ממש ואז מאיר בו קדש העליון ממש כמ\"ש בעצם משא\"כ בבחי' המשכה אזי מאיר הארה בעלמא מבחי' קדש העליון שהוא למעלה מן הזמן בזמן שהוא בחי' יום חול שמאיר בו (ולכן נק' שבת קדש וי\"ט מקרא קדש<sup data-n=\"2731\">93</sup> ) [ועוד זאת שבבחי' ההעלאה לבחי' קדש העליון נתעלו כללות השית יומין לבחי' קדש מצד ביטול בחי' הזמן שנתבטל ממהותו ונתעלה ונכלל בבחי' קדש העליון משא\"כ כשמאיר בלמעלה מן הזמן בזמן שאז מציאת הזמן לא נתבטל ממהותו רק שמאיר בו קדש העליון מרחוק א\"כ אינו מאיר רק ביום הפרטים<sup data-n=\"2732\">94</sup> שחל בו ולא נתעלה כללות הזמן כו']. ולכן יש גם הפרש בג' המועדים עצמם שבפסח מאיר מדת האה' ושאר המדות לא נשתנו ממהותם כמבואר בפע\"ח שער כ\"ו<sup data-n=\"2733\">95</sup>, כן אפשר שיש",[["2724","86","<b>ברגע קטן עזבתיך</b>: ישעי' נד, ז."],["2725","87","<b>בעצמי'</b>: כנצ\"ל: דעצמי'."],["2726","88","<b>למסי\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."],["2727","89","<b>בשבת בחי' נשמה יתירה</b>: ביצה טז, א. ראה זהר יתרו פח, ב. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 94. ד\"ה אם בחוקותי הא' על יד הערה 117. מאמרי אדה\"א בראשית ע' קה. וש\"נ. תו\"ח ויקהל ח\"ב שצג, ג. וש\"נ. אוה\"ת בהר כרך ד ע' א'קמח. סה\"מ תרכ\"ז ע' קפא."],["2728","90","<b>קדש ישראל</b>: ירמי' ב, ג."],["2729","91","<b>נכתב בפ' מועדות מקודם ענין השבת</b>: אמור כג, ג."],["2730","92","<b>נתעלה</b>: כנצ\"ל: שנתעלה."],["2731","93","<b>שבת קדש וי\"ט מקרא קדש</b>: ראה זהר אמור צד, א. סידור שער המועדים ריז, א. שעה\"י קכח, א ובהערה 12."],["2732","94","<b>הפרטים</b>: כנצ\"ל: הפרטי."],["2733","95","<b>בפע\"ח שער כ\"ו</b>: הוא שער השופר. וכנצ\"ל: שכ\"ד, פ\"ו — הוא שער ר\"ה. שער הכוונות ענין ר\"ה דרוש ה. וראה גם לקו\"ת להאריז\"ל ר\"פ לך."]]],[4801940533,"ענין זה גם בימים שחל בהם שאינו מאיר בחי' קדש רק ביום שחל בו ושאר הימים לא נשתנו<sup data-n=\"2734\">96</sup> ממהותם כלל כו' וד\"ל.\n<b>ולקרב</b> אל השכל ענין גילוי המועדים שמאיר מלמעלה מן הזמן בזמן אעפ\"י שלא נשתנו הזמן ממהותו, יובן מענין מה שהראה הקב\"ה לאדם הראשון<sup data-n=\"2735\">97</sup> דור דור ודורשיו וא\"כ נגלה בו מלמעלה מן הזמן כיון שראה את העתיד להיות אעפ\"י שהי' בזמן, וכן הוא עד<sup data-n=\"2736\">98</sup> נבואת משה שהיתה באצי'<sup data-n=\"2737\">99</sup> א\"כ נגלה בו מלמעלה מן הזמן אעפ\"י שהי' למטה נשמתו מלובש בגופו בזמן כו'. וזהו\"ע האיש מקדש בו ובשלוחו<sup data-n=\"2738\">100</sup>, שמקדש בו הוא ענין השבת שנתעלה הזמן בקדש העליון ממש, וזהו בו ממש, ובשלוחו הוא ענין הימים טובים שמתקדשים ע\"י נש\"י שנק' שלוחו כי שלוחו של אדם כמותו<sup data-n=\"2739\">101</sup> מחמת שמאיר בהם קדש העליון כו' וד\"ל.\n<b>והנה</b> קידוש הזמנים שהוא ענין המשכת קדש העליון דבחי' חכי' ולא בחכ' ידיעא במדות שהוא מלמעלה מן הזמן בזמן צ\"ל מתחלה ענין ההמשכה מחכ' לבינה ואז יוכל להיות ההמשכה מבינה למדות, כידוע ההפרש בין עונג לשמחה<sup data-n=\"2740\">*102</sup>* שעונג הוא בהעלם החכ' שנק' עדן<sup data-n=\"2741\">102</sup> משא\"כ הבינה נק' בחי' שמחה<sup data-n=\"2742\">103</sup> מצד שהעונג הוא בהתגלות במורגש בבחי' בינה (כידוע בענין ועבד הלוי הוא<sup data-n=\"2743\">104</sup> שעיקר התגלות עתיק הוא בבינה<sup data-n=\"2744\">105</sup> כו'), וכאשר נמשך בבחי' בינה במורגש (שזהו בחי' נהר שיוצא מהעלם דעדן<sup data-n=\"2745\">106</sup> כו') אז יכול דווקא להיות התגלות הנ\"ל בבחי' המדות, וזהו אם הבנים שמחה<sup data-n=\"2746\">107</sup> שעיקר השמחה דבנים הוא מצד האם שהוא בחי' בינה<sup data-n=\"2747\">108</sup>, והגם שעיקר שרש המדות הוא בבחי' החכ' כידוע בענין כי מראש צורים אראנו<sup data-n=\"2748\">109</sup> מ\"מ",[["2734","96","<b>נשתנו</b>: כנצ\"ל: נשתנה."],["2735","97","<b>שהראה הקב\"ה לאדם הראשון</b>: ראה סנהדרין לח, ב. ע\"ז ה, א. לקו\"ש תרומה כרך יא ע' 319 ואילך."],["2736","98","<b>עד</b>: אוצ\"ל: ע\"ד."],["2737","99","<b>נבואת משה שהיתה באצי'</b>: ראה תו\"א בא ס, ב. לקו\"ש שמות כרך ו ע' 251 ואילך. וראה גם לקו\"ת נצבים מט, ב. לקמן ביאור למאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 13."],["2738","100","<b>האיש מקדש בו ובשלוחו</b>: קדושין מא, א. ראה גם אוה\"ת פינחס כאן ע' א'קצט."],["2739","101","<b>שלוחו של אדם כמותו</b>: ברכות לד, ב (במשנה). קדושין מא, ב."],["2740","*102","<b>ההפרש בין עונג לשמחה</b>: ראה גם מאמרי אדה\"א במדבר ח\"ג ע' תתקסד וע' תתקסח ואילך. דברים ח\"ג ע' א'קז. שעה\"י קיג, א ובהנסמן במ\"מ לשם."],["2741","102","<b>החכ' שנק' עדן</b>: ראה זהר אד\"ז האזינו רצ, א. יתרו צ, א. לעיל ע' עט ובהערה 62."],["2742","103","<b>הבינה. . שמחה</b>: ראה מאמרי אדה\"א נ\"ך ע' מח. וש\"נ. תו\"ח וארא ח\"א פה, ג. לעיל ע' יט ובהערה 34."],["2743","104","<b>ועבד הלוי הוא</b>: קרח יח, כג."],["2744","105","<b>התגלות עתיק הוא בבינה</b>: מובא בכ\"מ בשם הע\"ח — ראה תו\"ח לך פא, ב ואילך. הנסמן במאמרי אדה\"א הנחות תקע\"ז ע' ד. ביאוה\"ז להצ\"צ אחרי ע' שסד."],["2745","106","<b>נהר שיוצא. . דעדן</b>: בראשית ב, י."],["2746","107","<b>אם הבנים שמחה</b>: תהלים קיג, ט."],["2747","108","<b>אם הבנים. . בינה</b>: ראה זהר ויחי ריט, א. יתרו פד, א. פה, ב. פרדס שעה\"כ שכ\"ג, פ\"א מערכת אם הבנים. לקו\"ת שמ\"ע פח, ד. שעה\"י קי, ב ובהערה 19."],["2748","109","<b>כי מראש צורים אראנו</b>: בלק כג, ט. זהר שם רג, ב. ביאוה\"ז שם קג, א ואילך. מאמרי אדה\"ז תקס\"ח ח\"א ס\"ע רסט ואילך. אוה\"ת בלק ס\"ע תתקד ואילך. ביאוה\"ז להצ\"צ כרך ב ע' תתקצג ואילך. ע' תתרא."]]],[4801940559,"ההתגלות שלהם בלב שנק' לידת המדות להיות<sup data-n=\"2749\">110</sup> כ\"א ע\"י ההשגה דבינה כמו שאנו רואים בחוש שא\"א להיות התפעלות אהוי\"ר בלב כ\"א כאשר בא ענין האלקי לידי השגה במוח בינה דווקא וכמו אב ואם שגם שעיקר הולד הוא מבחי' הטיפה שנמשכה מן האב אבל הציור ברמ\"ח אברי' בגילוי שזהו\"ע העיבור והגילוי שלו להוציאו לאויר העולם הנק' לידה<sup data-n=\"2750\">111</sup>, כ\"ה בענין המשכת קדש העליון שהוא בחי' המשכת העונג במדות א\"א להיות כ\"א כאשר בא מתחילה במורגש שנק' בחי' שמחה שהוא בבחי' בינה.\n<b>וזהו\"ע</b> ב' בחי' שיש בימים טובים הא' במה שנק' מועדי הוי' שהו\"ע יעוד והתחברות דהמשכת החכ' הנק' הוי'<sup data-n=\"2751\">112</sup> בבחי' בינה כו', כי מועדי הוא ענין התחברות כמ\"ש הילכו שנים יחדיו<sup data-n=\"2752\">113</sup> בלתי אם נועדו, וכן ונודעתי לך<sup data-n=\"2753\">114</sup> כו', אך מה שנמשך מבחי' הבינה במדות שהם בבחי' זמן והיינו מקור הזמן כנ\"ל זהו בחי' ב' שעי\"ז נק' בשם זמנים. והנה זה תלוי בקדושת ישראל<sup data-n=\"2754\">115</sup> דקדשינהו לזמנים כו', משא\"כ ההמשכה מחכ' לבינה נעשה ממילא כו', ולכן אל תקראו אותם אתם כתיב<sup data-n=\"2755\">116</sup> שזהו\"ע שישראל מקדשים לזמנים ע\"י<sup data-n=\"2756\">117</sup> מתורגם בזמניהן דווקא משא\"כ מועדי הוי' שהוא ענין ההמשכה מחכ' לבינה שהוא עדיין למעלה מהזמן שהוא במדות כנ\"ל אינו מתורגם רק מועדיא הוי', ולכן גם בתיקון של נוסח התפלה שההודאה על עיקר המכוון דימים טובים שהוא שימשך מלמעלה מן הזמן בזמן דווקא שהוא ענין המדות לכן תקנו לומר והזמנים דווקא ולא המועדים, ובבחי' זאת א' מקדש ישראל כי בחי' זאת תלוי בקדושת ישראל שמקדשים אותם כו' וד\"ל.\n<b>והנה</b> ע\"ד דוגמא דהפרש הנ\"ל שבין שבת ליו\"ט כ\"ה ההפרש בין תורה למצות. כי הנה כתיב ואברהם זקן בא בימים<sup data-n=\"2757\">118</sup> וא' ע\"ז הזוהר באינון יומין עילאין<sup data-n=\"2758\">119</sup> ומאן דגרע יומא חדא גרע לבושא חדא, ולכאורה למה לא יוכל להשלים המצוה שחסר ביום אחד שיעלה<sup data-n=\"2759\">120</sup> ביום שאחריו ב' מצות ולמה תלוי ענין הזה של הבירורים והמשכות שנעשי' ע\"י המצות בזמן דווקא, אך עם הנ\"ל שעיקר ענין המצות הוא ע\"ד ימי<sup data-n=\"2760\">121</sup>ם טובים שהמכוון להמשיך למעלה מהזמן בזמן דווקא ולכן אם חסר יום אחד ולא עשה בו המצות השייך לו אעפ\"י שיעשה ביום שאחריו ב' מצות",[["2749","110","<b>להיות</b>: כנצ\"ל: א\"א להיות."],["2750","111","<b>לידה</b>: כנצ\"ל: לידה הוא ע\"י האם."],["2751","112","<b>החכ' הנק' הוי'</b>: ראה זהר רע\"מ פינחס רנה, רע\"ב. מאמרי אדה\"ז על פרשיות התורה ח\"א ע' קלה."],["2752","113","<b>הילכו שנים יחדיו</b>: עמוס ג, ג."],["2753","114","<b>ונודעתי לך</b>: וכ\"ה באוה\"ת שבועות [שבהערה 1] ע' פד. אבל במהדורת תשנ\"ה תוקן: ונועדתי לך — תרומה כה, כב. ולהעיר מלקו\"ת במדבר א, סע\"ב: ונועדתי ונודעתי הוא ענין אחד אותיות דדין כאותיות דדין ושניהם לשון התקשרות ודביקות."],["2754","115","<b>אל</b>: כנצ\"ל: אשר."],["2755","116","<b>אותם אתם כתיב</b>: ר\"ה כה, א וברש\"י שם."],["2756","117","<b>ע\"י</b>: אוצ\"ל: ע\"כ על כן. או שצ\"ל: במועדם."],["2757","118","<b>ואברהם זקן בא בימים</b>: ח\"ש כד, א."],["2758","119","<b>באינון יומין עילאין</b>: ראה זהר ח\"ש קכט, א. ויחי רכד, א. מאמרי אדה\"א ויקרא ח\"ב ע' תשמט. וש\"נ. תו\"ח בשלח ח\"א קעו, א. וש\"נ."],["2759","120","<b>שיעלה</b>: כנצ\"ל: שיעשה."],["2760","121","<b>ימי</b>: אולי תיבה זו מיותרת. או אולי חסר כאן ההמשך, והכוונה להכתוב [תהלים צ, י] ימי שנותינו בהם שבעים שנה."]]],[4801940577,"מ\"מ אותו היום שעבר חסר מהארת קדש העליון כו'. וזהו\"ע ימי מספר שבעים שנה בכדי להמשיך בכל ז' המדות<sup data-n=\"2761\">122</sup> שכ\"א כלול מי' שהוא מספר שבעים כו'. ולכן כל המצות תלוים בזמן דווקא כמ\"ש לכל זמן ועת לכל חפץ תחת השמים<sup data-n=\"2762\">123</sup>, כי חפץ הוא הגילוי רצון העליון הנמשך ע\"י המצוה הוא תחת השמים שהוא בזמן לכל יש עת לכל חפץ כמו מצות עשיות סוכה ונטילת לולב שצ\"ל בט\"ו לחודש השביעי דווקא, ובזמן אחר לא יפעול כלום וכן הוא עד\"ז בכל המצות כמו אכילת מצה וכיוצא שכולם תלוים בזמן דווקא מצד שזהו\"ע המצות להמשיך מלמעלה מן הזמן בזמן דווקא, משא\"כ בחי' תורה כל העוסק בתורה עולה<sup data-n=\"2763\">124</sup> כאילו הקריב עולה אעפ\"י שאין בהמ\"ק בנוי ואין כהן כי היחוד שנעשה ע\"י התורה שהוא בדיבור הוא בדרך העלאה דזמן בבחי' למעלה מן הזמן ולכן אינו תלוי בזמן, וכ\"ה עד\"ז בכל ההלכות כמו כשעוסק בהלכות לולב<sup data-n=\"2764\">126</sup> הוא פועל פעולתו מתי שלומד הלכה זאת אעפ\"י שהוא לומד אותה שלא בזמנה. ולכן נאמר בתורה<sup data-n=\"2765\">125</sup> מה להלן באימה וביראה<sup data-n=\"2766\">127</sup> כו', והאיך יכול להיות זה הלא אז שמענו מפי הגבו' בקולות וברקי', אך להיות שהגילוי שהי' בשעת מ\"ת הוא ג\"כ בשלימות עכשיו רק שהי' למעלה מן הזמן לכן בעת לימודו שנתעלה בלמעלה מן הזמן לכן תחיל עלי'<sup data-n=\"2767\">128</sup> האימה שבשעת מ\"ת ממש כו' וד\"ל.\n<b>והנה</b> כללי' שני בחי' הנ\"ל דההעלאה והמשכה הו\"ע אברהם ויצחק, כי אברהם הוא בחי' ההמשכה דלמעלה מן הזמן בזמן שלכן נאמר בו בא בימים שהוא הממשיך מלמעלה מן הזמן בשית יומין עילאין ע\"ד הנ\"ל בימים טובים ומעה\"מ<sup data-n=\"2768\">129</sup>, ובחי' יצחק הוא בחי' העלאה דזמן בלמעלה מן הזמן ע\"ד הנ\"ל בתו' ושבת, ולכן לעתיד שיהי' יום שכולו שבת<sup data-n=\"2769\">130</sup> יאמרו ליצחק כי אתה אבינו<sup data-n=\"2770\">131</sup> כו', אך יעקב הוא הכולל ב' בחי' דההעלאה והמשכה וכן התו' אעפ\"י שהוא בחי' העלאה כנ\"ל (כידוע דתורה מפי הגבורה ניתנה<sup data-n=\"2771\">133</sup> וכמ\"ש מימינו אש<sup data-n=\"2772\">134</sup> ), מ\"מ עיקרה הוא בחי' קו האמצעי שכולל שני בחי' דהעלאה והמשכה<sup data-n=\"2773\">132</sup> כו' וד\"ל.",[["2761","122","<b>שבעים שנה. . ז' המדות</b>: ראה גם מאמרי אדה\"א דברים ח\"ב ע' תקנו."],["2762","123","<b>לכל זמן. . השמים</b>: קהלת ג, א."],["2763","124","<b>כל העוסק בתורה עולה</b>: ראה מנחות קי, א. לקו\"ש מסעי כרך יח ע' 413. וש\"נ. ערב פסח כרך לב ע' 37. וש\"נ."],["2764","126","<b>עד\"ז בכל ההלכות. . בהלכות לולב</b>: ראה גם לקו\"ת במדבר יג, א. תו\"ח ויקהל ח\"ב שצג, א. וש\"נ. לעיל ע' רלד ובהערה 37."],["2765","125","<b>בתורה</b>: כנצ\"ל: בתורת."],["2766","127","<b>מה להלן באימה וביראה</b>: ברכות כב, א. ראה גם לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 27. תו\"ח נח מט, סע\"ג ואילך ובהערה 25. יתרו ח\"ב רנג, ד ואילך. שע\"ת מא, א. מאמרי אדה\"א הנחות תקע\"ז ע' קכב."],["2767","128","<b>תחיל עלי'</b>: כנצ\"ל: תחול עליו."],["2768","129","<b>ומעה\"מ</b>: ומעשה המצוות."],["2769","130","<b>יום שכולו שבת</b>: תמיד בסופה."],["2770","131","<b>ליצחק כי אתה אבינו</b>: שבת פט, ב. ישעי' סג, טז."],["2771","133","<b>דתורה מפי הגבורה ניתנה</b>: ראה גם לקוטי ביאורים לשעה\"י קפו, ב ובהערה 11."],["2772","134","<b>מימינו אש</b>: ברכה לג, ב."],["2773","132","<b>התו'. . דהעלאה והמשכה</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'תסז ואילך."]]],[4801940589,"עוד מענין הנ\"ל שמעתי מבנו מהרי\"ל<sup data-n=\"2774\">135</sup> שי' שא' בשמו בענין הכפל דמועדי הוי' ואח\"כ א' אלה הם מועדי, כי יש ב' בחי' במועדים כי המועדים הם חג\"ת<sup data-n=\"2775\">136</sup> ויש בחי' חג\"ת דאצי' נק' מועדי<sup data-n=\"2776\">137</sup> הוי' ויש חג\"ת בכתר ונק' ימי קדם וע\"ז אלה הם מועדי (והוא ע\"ד המצות שיש שרש בחי' מצות הוי'<sup data-n=\"2777\">138</sup> ומצות<sup data-n=\"2778\">139</sup> כו'), וכן בשבת יש ב' בחי' שבת הוא בחכ' למעלה מן הזמן כנ\"ל, ויש שבת שבתון<sup data-n=\"2779\">140</sup> שהוא בכתר הוא למעלה מן המועדי' שבכתר, והנה מבואר למעלה דמועדי'<sup data-n=\"2780\">141</sup> הוא בחי' אברהם וע\"ז אמר ואברהם זקן וא' הרה\"מ נ\"ע<sup data-n=\"2781\">142</sup> שפירושו שיש אברהם הזקן ששרשו בבחי' ע\"י כידוע שהאבות הם חג\"ת<sup data-n=\"2782\">143</sup> דאצי' אבל בעבר הנהר ישבו אבותיכם הוא שרש האבות בכתר<sup data-n=\"2783\">144</sup> ולזה אמר שהאברהם הזקן הוא הממשיך ביומי' דאצי', וזהו בא בימים כו' וד\"ל.\n<b>עוד</b> שמעתי מפי אדמו\"ר שי' שבחי' העלאה דתורה הוא תושבע\"פ שעיקרה בחי' עיון שהוא בחי' העלאה ובחי' דתו' הכולל והעלאה<sup data-n=\"2784\">145</sup> והמשכה הוא בחי' תושב\"כ שעיקרה הוא קריאה באותיו' בקול ודיבור כו' וד\"ל.",[["2774","135","<b>מבנו מהרי\"ל</b>: מו\"ה ר' יהודה ליב. ראה אודותיו ספר השיחות תרפ\"ז ע' 161 ובהערה 15. סה\"מ תרכ\"ז ע' תקי ואילך. המשך וככה תרל\"ז ע' סו (סה\"ש תש\"ד ע' 129). מאמרי אדה\"א הנחות תקע\"ז ע' תמט הערה 13. סה\"ש תורת שלום ע' 79. ע' 81. ע' 237 (אג\"ק כ\"ק אדמו\"ר מהוריי\"ץ ח\"א ע' תפה. ח\"ב ע' שכב). ע' 244. סה\"ש תש\"א ע' 141. יומן תרצ\"ג (נדפס ברשימות חוברת קמ ע' 5. קפז ע' 6). מכתב אדר\"ח אלול תשי\"ג (אג\"ק ח\"ז ס\"ע שנה ואילך). אג\"ק כ\"ק אדמו\"ר מהוריי\"ץ ח\"א ע' שז. סה\"ש תש\"ה ע' 32. סה\"ש תרפ\"ו ע' 100 (תש\"ה ע' 14). לקו\"ד ח\"א ע' 56. סה\"ש תש\"ב ע' 108. תש\"ד ע' 4. אג\"ק כ\"ק אדמו\"ר מהוריי\"ץ ח\"ז ע' נו (היום יום ע' 7)."],["2775","136","<b>המועדים הם חג\"ת</b>: ראה (בנוסף על אוה\"ת שבהערה 1) מאמרי אדה\"א נ\"ך ע' שעה. וש\"נ. תו\"ח בשלח ח\"א רמא סע\"א ואילך. וש\"נ. לעיל ע' רל."],["2776","137","<b>מועדי הוי'. . מועדי</b>: ראה גם אוה\"ת (שבהערה 1) לך כרך ד ס\"ע תרצג ואילך. אמור כרך א ע' שכז. כרך ד ע' א'פא. דברים ע' ב. תצא ע' תתקלג. לעיל ע' רל. ע' רמא ואילך. סה\"מ תרל\"ח ע' שלב."],["2777","138","<b>מצות הוי' ומצות</b>: ראה גם סידור שער הציצית ד, ד. ה, ג. אמ\"ב שם פו, א. אוה\"ת (שבהערה 1) שלח ע' תקפח. תצא כרך ו ע' ב'שסד ואילך. לעיל ע' רלא. ע' רלו. סה\"מ תרל\"ח שם."],["2778","139","<b>ומצות</b>: כנצ\"ל: ומצותי."],["2779","140","<b>שבת שבתון</b>: ויקהל לה, ב."],["2780","141","<b>דמועדי'</b>: כנצ\"ל: דמועדי."],["2781","142","<b>וא' הרה\"מ נ\"ע</b>: באוה\"ת פינחס כאן ע' א'רב: ”ובאור תורה. . פ' חיי שרה ע\"פ ואברהם זקן\" ע\"ש."],["2782","143","<b>האבות הם חג\"ת</b>: ראה מאו\"א מערכת אבות סכ\"ז. תו\"ח וארא ח\"א סא, ד. וש\"נ."],["2783","144","<b>בעבר הנהר. . בכתר</b>: יהושע כד, ב. ראה גם לקמן מאמר ד\"ה והניף הכהן הב' ובהערה 58. ד\"ה אם בחוקותי הג' על יד הערה 121-2."],["2784","145","<b>והעלאה</b>: כנצ\"ל: העלאה."]]],[4801940112,"<b>תורת אדמו\"ר נא' ביום ה' פ' אמור דשנת תקצ\"ח בליבאויץ</b>\n<b>וספרתם</b> לכם<sup data-n=\"2785\">1</sup> ממחרת השבת<sup data-n=\"2786\">2</sup> מיום הביאכם את עומר התנופה שבע שבתות תמימות כו', הנה וספרתם הוא מל' ספיר<sup data-n=\"2787\">3</sup> וקאי על בחי' ע\"ס דאצי' ונק' בשם ספי\"ר<sup data-n=\"2788\">4</sup> מצד שהם דוגמת אבן ספיר וכמאמר כמראה אבן ספיר דמות כסא<sup data-n=\"2789\">5</sup> ועז\"נ וספרתם לכם שתמשיכו בחי' ע\"ס<sup data-n=\"2790\">6</sup> דאצי' לכם בעשר כחות הנפש שלכם עד שכל כח פרטי מכחות הנפש יהי' מרכבה לספי' פרטי' והיינו ע\"י הזדככות הכחות עד שהמה יהי' ג\"כ כדוגמת ספיר, וזהו מה שאו' בספירה<sup data-n=\"2791\">7</sup> ספי' פלוני' כו' [... וזהו מה שאנו אומרים ג\"כ לטהרינו ולקדשינו בקדושתך העליונה<sup data-n=\"2792\">8</sup>, היינו שקדושת הע\"ס שהמה קדושים בקדושת עצמי' המאציל יהי' שורה בנו בכל כחות הנפש כו']<sup data-n=\"2793\">9</sup>.\n<b>ותחילה</b> י\"ל מה שע\"ס נמשלו לספיר כו', כי הנה במאמר אלי' אמר וכמה גופין תקינת לון<sup data-n=\"2794\">10</sup> פי' שכלים דע\"ס הגם שהמה בחי' אלקות ממש להוות מאין ליש כמו חכ' דאצי' הוא אינו מהות חכ' כלל רק כח האלקי להיות מקור להתהוות חכ' להשגה דבי\"ע וכן חסד מקור להתפעלות אה' בבי\"ע ולכן אין ערוך לנברא אפי' היותר עליון כמו נשמת אברהם אוהבי<sup data-n=\"2795\">11</sup> לגבי חסד דאצילות עד שאמר ואנכי עפר ואפר שהוא לגבי מקורו כדוגמת האפר משריפת העצים כו' כמבואר באגה\"ק<sup data-n=\"2796\">12</sup> יעו\"ש אעפ\"כ לגבי עצמי' המאציל המה נק' בשם גופין ממש כדוגמת אברי הגוף שלא יוכל להתקבל בהם עצם חיות הנפש שהוא פשוט בתכלית רק הארה המתחלקת להתמזג בכל אבר בחי' פרטי' כמו המוח אינו מקבל בתוכו רק כח השכל והלב כח המדות אבל חיות עצמי' הנפש הפשוט בתכלית עד שהוא מקור לכל כחות פרטי' אינו בא בבחי' מזיגה באברי הגוף רק בדרך השראה בהעלם כו', כך למעלה בחי' ע\"ס כאו\"א הוא מקור לבחי' פרטי' בלבד כמו חכ' דאצי' הוא מקור להתהוות ממנה רק בחי' חכ' בבי\"ע ולא בחי' חסד כנ\"ל ולכן אין להם ערך לגבי עצמות אוא\"ס הפשוט בתכלית הפשיטות עד שהוא מקור לכל הגילויים דע\"ס לכן<sup data-n=\"2797\">13</sup> כל יכול להאציל עד אין קץ<sup data-n=\"2798\">14</sup>",[["2785","1","<b>וספרתם לכם</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ."],["2786","2","<b>וספרתם לכם ממחרת השבת</b>: אמור כג, טו."],["2787","3","<b>וספרתם הוא מל' ספיר</b>: ראה גם ערכי הכנויים לבעל סדה\"ד מערכת ספיר [ספירה]. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 6. לקו\"ת אמור לה, ב."],["2788","4","<b>ע\"ס דאצי'. . ספי\"ר</b>: ראה פרדס שער מהות והנהגה ש\"ח, פ\"ב. שיעור קומה להנ\"ל ס\"ב בתחלתו."],["2789","5","<b>כמראה אבן ספיר דמות כסא</b>: יחזקאל א, כו."],["2790","6","<b>וספרתם לכם שתמשיכו בחי' ע\"ס</b>: ראה גם הדרושים שבהערה 3."],["2791","7","<b>מה שאו' בספירה</b>: ברבונו של עולם שבסדר ספה\"ע."],["2792","8","<b>לטהרינו ולקדשינו בקדושתך העליונה</b>: בסידור אדה\"ז ולטהרינו [וכ\"ה בהמאמר המצויין בסמוך בין הערות 214-5]. אבל כ\"ה בסידור ר\"ש רשקוב וקול יעקב. ראה גם לקמן מאמר ד\"ה וספרתם הה' על יד הערה 251."],["2793","9","<b>כו']</b>: ראה לקמן ברשימת הכת\"י כאן."],["2794","10","<b>וכמה גופין תקינת לון</b>: ת\"ז בהקדמה יז, א."],["2795","11","<b>אברהם אוהבי</b>: ישעי' מא, ח."],["2796","12","<b>ואנכי עפר ואפר. . באגה\"ק</b>: וירא יח, כז. אגה\"ק סט\"ו."],["2797","13","<b>לכן</b>: ב: וכן."],["2798","14","<b>להאציל עד אין קץ</b>: ראה גם לקמן ע' תמה. וש\"נ."]]],[4801940176,"לכן נק' א\"ס ע\"ש שא\"ס להתפשטותו לכן אין ערך לע\"ס אלו<sup data-n=\"2799\">15</sup> כדוגמת איברי הגוף לגבי עצמות הנפש ויותר מכן לאין קץ כו', ולכן נק' בשם גופין לגבי עצמי' המאציל בלבד אבל מ\"מ אין ערוך ליש הנברא אליהם כי המה בחי' אלקות כנ\"ל.\n<b>אך</b> א\"כ הוה אמינא כמו שהגוף הוא מסתיר על אור וחיות הנפש הפשוט בתכלית עד שאינו מתגלה בו רק בחי' חכ' וחסד כנ\"ל א\"כ גם ע\"ס המה בחי' מסתירים על בחי' עצמי' אוא\"ס הפשוט בתכלית ולז\"א ע\"ס<sup data-n=\"2800\">16</sup> שהמה כדוגמת אבן הספיר שאע\"פ שהוא בחי' דומם נבדל מאור השמש אעפ\"כ הוא מגלה אור השמש כמ\"ש<sup data-n=\"2801\">17</sup> ואינו מסתיר כלל עליו ואדרבה יש בו יתרון בזה שפועל מזיגה באור השמש שיוכל להתקבל במקבל [ובלא\"ה הי' מזיק לעין הרואה כו'], כן למעלה בבחי' ע\"ס נאמר בזוהר איהו וחיוהי וגרמוהי<sup data-n=\"2802\">18</sup> שבחי' עצם אוא\"ס הפשוט הנק' איהו מתייחד בגרמוהי שהוא בחי' הכלים דאצי' עד שהוא מתגלה על ידם כמו כשמתגלה חכ' בבי\"ע בשרפים האומרים קדוש<sup data-n=\"2803\">19</sup> מצד השגתם וכן בנשמות הנה השגתם אינו בחי' יש רק שמשיגים איכות ביטול מציאותם למקורם הראשון שבראשונים שהוא בחי' עצמות אוא\"ס הפשוט בתכלית, רק אדרבה זהו פעולת הכלים דע\"ס דאצי' לעשות מזיגה כבי' בעצמות אוא\"ס הפשוט שיוכל לבוא להיות נמשך בהשגה והתפעלות הנברא, היינו שהנברא ירגיש ביטול מציאותו לגבי א\"ס זהו גילוי אור הא\"ס כו' וד\"ל [אך הכח הזה שיש בכלים הוא גופא כח הא\"ס שכל יכול להגביל א\"ע ולבוא בבחי' גילוי בהגבלה זאת כו' וד\"ל]. ועז\"א וספרתם לכם שיהי' כחות הנפש שבנש\"י שבגופים אפי' מנפשם הטבעי' יהי' בדוגמת ספירות העליונות שיתגלה בהם ועל ידם אוא\"ס הפשוט בתכלית בלי שום הסתר כלל אפי' לאיברי הגוף הגשמי [... וכמאמר בקרבך קדוש<sup data-n=\"2804\">20</sup> כו', וכל קרבי את שם קדשו<sup data-n=\"2805\">21</sup> כו']. אך עדיין אין זה פנימי' הכוונה רק שזיכוך זה הוא הכנה בלבד להתגלות מ\"ת כמשי\"ת וד\"ל.\n<b>והנה</b> להבין ביאור ענין הספי' ואיך שהוא הכנה למ\"ת ילה\"ק ענין קול דודי כו' מדלג על ההרים מקפץ על הגבעות<sup data-n=\"2806\">22</sup>, דילוג הוא ברגל א' שזהו בחי' יצי\"מ בחי' רצוא בלבד וקפיצה בב' רגלים<sup data-n=\"2807\">23</sup> שזהו בחי' השוב דמ\"ת, וכאשר צ\"ל מבחי' הרצוא דיצי\"מ בחי' השוב דמ\"ת א\"א להיות כ\"א ע\"י אמצעות הספירה כמשי\"ת. והנה להבין ענין יצי\"מ, ואיך שבכל יום יש יצי\"מ כמאמר חייב אדם לראות א\"ע<sup data-n=\"2808\">25</sup>",[["2799","15","<b>אלו</b>: שם: אליו."],["2800","16","<b>ע\"ס</b>: שם ניתוסף: בס\"י בספר יצירה פ\"א, מ\"ב ואילך."],["2801","17","<b>כמ\"ש</b>: כמו שהוא."],["2802","18","<b>איהו וחיוהי וגרמוהי</b>: ראה ת\"ז בהקדמה ג, ב."],["2803","19","<b>בשרפים האומרים קדוש</b>: ישעי' ו, ב-ג."],["2804","20","<b>בקרבך קדוש</b>: הושע יא, ט."],["2805","21","<b>וכל קרבי את שם קדשו</b>: תהלים קג, א."],["2806","22","<b>קול דודי. . הגבעות</b>: שה\"ש ב, ח."],["2807","23","<b>דילוג הוא ברגל א'. . וקפיצה בב' רגלים</b>: אהלות פ\"ח, מ\"ה ובפיה\"מ ורע\"ב שם. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רצב. וש\"נ. במדבר ח\"א ע' מו. וש\"נ."],["2808","25","<b>א\"ע</b>: ב ניתוסף: בכ\"י."]]],[4801940233,"כאילו הוא יצא ממצרים<sup data-n=\"2809\">24</sup> כו'. הנה מתחילה י\"ל ענין קליפת מצרים כי הנה פרעה הוא מלך מצרים הוא מקור קליפת מצרים אמר לא ידעתי את הוי'<sup data-n=\"2810\">26</sup> פי' הוי' הוא המהווה<sup data-n=\"2811\">27</sup> כל ההשתלשלות כאחד שע\"ז מורה שם הוי' הי' הוה ויהי' כא'<sup data-n=\"2812\">28</sup> שזהו בחי' ההשתלשלות כמו שהמה בטלים וכלולים במקורם [כמבואר במ\"א בענין כטיפה בים<sup data-n=\"2813\">29</sup> כו'] והעיקר הוא יו\"ד דשם הוי'<sup data-n=\"2814\">30</sup> הכוללם יחד, וכיון שהמה בתכלית הביטול למקורם א\"כ המה אין ואפס ממש עד שאפס בלעדו, ולכן אני הוי' לא שניתי<sup data-n=\"2815\">31</sup> שכמו שקודם שנברה\"ע הי' לבדו ממש כן גם אחרי שנברה\"ע הוא לבדו ממש להיות שאין כל ההשתלשלות תופס מקום כלל בעצמותו ית' ואי לזאת המחדש בטובו שצ\"ל התחדשות בכל עת ורגע לצורך קיום ההשתלשלות כו' ומה שנראה עולם כמנהגו נוהג<sup data-n=\"2816\">32</sup> ע\"פ הטבע זהו מצד שם אלקים המסתיר עד שנראה עולם ומלואו ליש ודבר נפרד כאלו מתנהג בעצמו בטבעו המסודר לו כמו שנברא בשימ\"ב אבל באמת אינו כן רק כל פרט גילוי שפע ואיזה הנהגה פרטי' היא המשכה חדשה ממש ממקור כח הא\"ס המהווה כל ההשתלשלות מאין ליש כו' וד\"ל. וזהו מ\"ש פרעה לא ידעתי את הוי' הגם שכבר ידע שיש בורא המהווה כל ההשתלשלות כי כבר אמר לו יוסף האלקים יענה את שלום פרעה<sup data-n=\"2817\">33</sup> אבל בדמיונו הכוונה<sup data-n=\"2818\">34</sup> הי' שכבר ברא ההשתלשלות בשימ\"ב מאין ליש ועתה עזב ה' את הארץ<sup data-n=\"2819\">35</sup> רק מתנהג כמנהגו ע\"פ הטבע כו'. והיינו מצד ששרשו מבחי' שם אלקים המסתיר לכן לא הי' יכול להשיג אמיתית התהוות הנבראים מצד שם הוי' כנ\"ל אבל באמת אפי' מה שהעולם נראה ליש שזהו מצד אלקים הוא ג\"כ בטל במקורו וכמאמר<sup data-n=\"2820\">36</sup> כולא קמי' כ\"ח<sup data-n=\"2821\">37</sup>, כולא דייקא, והטעם לזה הוא כי באמת הוי' הוא האלקים<sup data-n=\"2822\">38</sup> שבחי' ה\"ג שהוא בחי' הצמצום דשם אלקים<sup data-n=\"2823\">39</sup> נמשכים משם הוי' עצמו כהדין קמצא<sup data-n=\"2824\">40</sup> דלבושי' מיני' ובי', וזהו להודיע לבני האדם גבורותיו<sup data-n=\"2825\">41</sup> וכבוד הדר מלכותו שבחי' המל' הנבנית מהגבורות<sup data-n=\"2826\">42</sup> הוא בחי' גבורותיו שמקורו הוא משם הוי' כו' וד\"ל.",[["2809","24","<b>חייב אדם. . יצא ממצרים</b>: ראה פסחים קטז, ב (במשנה). לעיל ע' נח הערה 257."],["2810","26","<b>לא ידעתי את הוי'</b>: שמות ה, ב. ראה גם לעיל ע' נה."],["2811","27","<b>הוי' הוא המהווה</b>: ראה זהר רע\"מ פינחס רנז, סע\"ב. לקמן מאמר ד\"ה והתהלכתי תרכ\"ב הערה 59."],["2812","28","<b>שם הוי'. . כא'</b>: ראה שער היחוד והאמונה פ\"ז. הנסמן בתו\"ח מקץ ריט, ד הערה 62."],["2813","29","<b>בענין כטיפה בים</b>: ראה גם מאמרי אדה\"ז תקס\"ה ח\"א ע' קסד. סהמ\"צ להצ\"צ ע' צא ואילך. מאמרי אדה\"א נ\"ך ע' שלח ואילך."],["2814","30","<b>והעיקר הוא יו\"ד דשם הוי'</b>: ראה גם אוה\"ת תצוה כרך ח ע' ג'עט. סה\"מ תרל\"ח ע' כו ובהערה 247."],["2815","31","<b>אני הוי' לא שניתי</b>: מלאכי ג, ו."],["2816","32","<b>עולם כמנהגו נוהג</b>: ע\"ז נד, ב."],["2817","33","<b>האלקים יענה את שלום פרעה</b>: מקץ מא, טז."],["2818","34","<b>הכוונה</b>: ב: הכוזב."],["2819","35","<b>עזב ה' את הארץ</b>: יחזקאל ח, יב. ט, ט."],["2820","36","<b>וכמאמר</b>: ב: כי."],["2821","37","<b>כולא קמי' כ\"ח</b>: ראה זהר בהקדמה יא, ב. ראשית חכמה שער היראה פ\"א (ז, רע\"א). מאמרי אדה\"א דברים ח\"ב ע' תרנג."],["2822","38","<b>הוי' הוא האלקים</b>: ואתחנן ד, לה. לט."],["2823","39","<b>ה\"ג שהוא בחי' הצמצום דשם אלקים</b>: ראה לקו\"ת להאריז\"ל פ' נח ז, כ. ע\"ח שער מ\"ן ומ\"ד של\"ט, ד\"א (מ\"ק)."],["2824","40","<b>כהדין קמצא</b>: ראה ב\"ר פכ\"א, ה. מאמרי אדה\"א ויקרא ח\"ב ע' תשכא בהערה. סה\"מ תרכ\"ז ע' שנ ואילך. תרכ\"ט ע' שעג ואילך."],["2825","41","<b>להודיע לבני האדם גבורותיו</b>: תהלים קמה, יב."],["2826","42","<b>המל' הנבנית מהגבורות</b>: ראה ע\"ח שער תיקון הנוקבא של\"ד, פ\"ה. מאמרי אדה\"א דברים ח\"א ע' ריח. וש\"נ. תו\"ח בשלח ח\"א רמד, א. וש\"נ. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 14 ואילך."]]],[4801940286,"<b>והנה</b> זהו ענין יצי\"מ שהוא לצאת מבחי' המיצר הזה המסתיר לאור שם הוי' שהוא בחי' שם אלקים כנ\"ל ולהבין ולהשיג אמיתית מקורו איך שהוא משם הוי' ולזה אינו מסתיר כלל ולכן יראה וישיג איכות ביטול כל ההשתלשלות במקורם עד שבאמת הוא אפס בלעדו כו' וד\"ל. והנה בחי' יצי\"מ ישנו עד רום המעלות כי למטה בחי' יצי\"מ הוא בנשמה האלקית שתוצא מחומר הגוף המסתיר ועי\"ז תופשט מבחי' תאוות הגוף וכל בחי' לגרמי', ולמעלה יותר הוא בחי' יציאת מצרים הוא בעצם הנשמה האלקי' שתתפשט מלבושי הנר\"נ שהוא בחי' השגה והתפעלות אלקות רק ביטול עצמי' למעלה מהשגה, וכן אפי' במקור כל הנשמות כמ\"ש בגעה\"ע שייך ענין יצי\"מ שהוא להפשיט עצמו מבחי' התענוג שנהנין מזיו<sup data-n=\"2827\">43</sup> ולבוא לבחי' לאשתאבא בגופא דמלכא<sup data-n=\"2828\">44</sup>. והנה ע\"ז אמר קול דודי כו' מדלג ברגל א' בלבד והטעם הוא כי ביצי\"מ לא הי' הגילוי הזה רק בשרש הנשמה האלקי' שהוא בחי' אדה\"ע אשר על הכסא [שהוא בחי' ז\"א כמאמר בצאת ישראל שהוא בחי' ז\"א ממצרים<sup data-n=\"2829\">45</sup> כו'] ולכן גם למטה לא הי' הגילוי דאוא\"ס הפשוט [שכולל כל ההשתלשלות בבחי' ביטול כטיפה בים כנ\"ל] רק בנה\"א<sup data-n=\"2830\">46</sup> והנה\"ט נתבטלה ממילא מצד תוקף הארת הנה\"א המאיר ומקיפה עד שלא תוכל לפעול פעולתה כלל [... אבל לא שנתברר עצם נה\"ט וכמבואר במ\"א בענין גפן ממצרים תסיע<sup data-n=\"2831\">47</sup> כו'. ..], וזהו מדלג על ההרים כי באמת הי' הגילוי למעלה מבחי' הרים שהוא בחי' מדות<sup data-n=\"2832\">48</sup> דאצי' שזהו בחי' קול דודי [וע\"ד הקבלה הוא בחי' אוא\"ב<sup data-n=\"2833\">49</sup> חכ\"ע ביטול כל ההשתלשלות במקורם כטיפה בים כו' וד\"ל], אך אעפ\"כ נתלבש הגילוי הזה בבחי' הרים שהוא בחי' המדות דז\"א [שהאבות שנק' הרים<sup data-n=\"2834\">50</sup> המה מרכבה אליהם כו'] ועל ידם נתגלה בנש\"י למטה כו' וזהו על ההרים שיתפרש בו ב' פי' למעלה מבחי' הרים ובתוך בחי' הרים כו' [... שהוא בחי' גילוי מוחין דגדלות דאבא שנמשך בז\"א ובא אח\"כ בגילוי למטה בנש\"י כו', ולכן בלילה הזה כל ישראל בני חורין מצד שרשם בז\"א המתגלה עתה כו' וד\"ל].\n<b>ומעתה</b> י\"ל איך שבכ\"י יש בחי' זאת דיצי\"מ והוא ענין סדר התפלה, דהנה עיקר כללותה<sup data-n=\"2835\">51</sup> הוא בחי' ק\"ש [וכל התפלה הוא ביאור הק\"ש כמ\"ש במא' הקול קול יעקב<sup data-n=\"2836\">52</sup> ]. והנה ק\"ש מתחיל באחד שהוא בחי' למס\"נ באחד<sup data-n=\"2837\">53</sup> שגם נפשו",[["2827","43","<b>שנהנין מזיו</b>: ראה ברכות יז, א."],["2828","44","<b>לאשתאבא בגופא דמלכא</b>: זהר ויחי ריז, ב. ראה הנסמן במאמרי אדה\"א ויקרא ח\"א ע' מה. תו\"ח בראשית מ, ב הערה 25."],["2829","45","<b>בצאת ישראל שהוא בחי' ז\"א ממצרים</b>: תהלים קיד, א. ראה פע\"ח שחה\"מ שכ\"א, פ\"ז."],["2830","46","<b>הגילוי. . בנה\"א</b>: ראה גם תניא פל\"א."],["2831","47","<b>גפן ממצרים תסיע</b>: תהלים פ, ט. ראה גם אוה\"ת (יהל אור) שם ע' רפא. לעיל ע' נח. לקמן מאמר ד\"ה וספרתם הה' על יד הערה 263."],["2832","48","<b>הרים שהוא בחי' מדות</b>: ראה זהר סבא משפטים קט, ב ובמפרשים שם. תו\"ח שמות ח\"א יד, ד הערה 642."],["2833","49","<b>אוא\"ב</b>: אור אבא."],["2834","50","<b>שהאבות שנק' הרים</b>: ראה ר\"ה יא, א. תו\"ח וארא ח\"א עז, ג. וש\"נ."],["2835","51","<b>כללותה</b>: ב: כללות התפילה."],["2836","52","<b>וכל התפלה. . הקול קול יעקב</b>: סידור שער התפלה יט, א."],["2837","53","<b>למס\"נ באחד</b>: ראה זהר רע\"מ משפטים קיט, א. צו לג, א. מאמרי אדה\"א דברים ח\"ב ע' תו. וש\"נ. שמות ח\"א ע' רעח ואילך. הנחות תקע\"ז ע' שא."]]],[4801940336,"האלקי' ימסור להיות מי לי בשמים<sup data-n=\"2838\">54</sup> ועמך לא חפצתי בארץ כלה שארי<sup data-n=\"2839\">55</sup> ולבבי<sup data-n=\"2840\">56</sup> ולכן מסיים בסוף ק\"ש אני הוי' אלקיכם אשר הוצאתי אתכם מאמ\"צ<sup data-n=\"2841\">57</sup>, אך א\"א להגיע לזה כ\"א ע\"י סדר התפלה שמקודם שזהו משארז\"ל תפלות אבות תקנום<sup data-n=\"2842\">58</sup>, פי' כי כללות הפסוד\"ז והברכות יש בהם ג' מיני פסוקים, יש פסוקים המורים על אה' שזהו בחי' אברהם ויש פסוקים המורים על יראה שזהו בחי' יצחק, ויש פסוקי רחמנות שזהו בחי' יעקב, וכמאמר אבינו אב הרחמן רחם עלינו<sup data-n=\"2843\">59</sup> להמשיך גילוי אלקות בנפשותינו וע\"ד<sup data-n=\"2844\">60</sup> כאשר יתגלה כבוד הוי' ואנחנו נראה הריחוק שבנו שאז תהי' הבושה גדולה מאד לכן הבקשה להמשיך עתה בחי' ביטול הנ\"ל לכבוד הוי' בנפשותינו בקירוב ממש בכדי שלא נבוש לעולם ועד, ולכן אח\"כ בא לבחי' מס\"נ באחד כו', וזהו בחי' התפלה שהוא בחי' יצי\"מ שבכ\"י שנעשה ע\"י האבות שנק' הרים וזהו מדלג על ההרים אך גם הק\"ש דמס\"נ באחד הוא בנה\"א בלבד כו' וכנ\"ל בעת יצי\"מ כו' וד\"ל.\n<b>והנה</b> בחי' הרצוא שבנה\"א בלבד שהוא בחי' אדם שם מ\"ה<sup data-n=\"2845\">61</sup> אינו מספיק עדיין לעורר ההתגלות דמ\"ת בבחי' שוב ולכן צריך עדיין לבחי' ספה\"ע שהוא בחי' בירור דבהמה שם ב\"ן<sup data-n=\"2846\">62</sup> כו' והטעם לזה הוא ע\"ד וכפר בעדו ובעד ביתו<sup data-n=\"2847\">63</sup>, שאע\"פ שכפר בעדו ונמצא שאין שום מניעה להיות אוא\"ס שורה בו בגילוי בכה\"ג ובעבודתו מ\"מ כ\"ז שלא כיפר בעד ביתו לא ישרה בעבודתו בחי' הגילוי דיוהכ\"פ שהוא גילוי פנימי' ועצמי' כי קוב\"ה שהוא פנימי' ועצמי' אוא\"ס לא שרי' רק באתר שלים<sup data-n=\"2848\">64</sup> משפיע ומקבל ביחד דייקא, וכמאמר זכר ונקבה בראם כו' ויברך אותם<sup data-n=\"2849\">65</sup> מבחי' ברכה והמשכה דפנימי' ועצמו' אוא\"ס, ולזאת גם שכיפר בעדו צריך ג\"כ לכפר גם בעד ביתו שלא יהי' בהם מונע להשראת הגילוי דאוא\"ס כו', והנה גם במ\"ת שהוא הגילוי מפנימי' ועצמי' אוא\"ס וכמאמר אנכי הוי' אלקיך<sup data-n=\"2850\">66</sup> כו' לזאת צ\"ל ג\"כ הבירור דנה\"ט שהוא בחי' מקבל מבחי' נה\"א ושיתגלה בחי' הכיליון דמי לי בשמים כו' כלה כו' גם ברצון דנה\"ט שיהי' כמו הרצון שבנה\"א למסור נפשו כו' ממש ואזי יתגלה בהם גילוי דאנכי דייקא בשניהם ביחד כמשי\"ת. ולזה צ\"ל ספה\"ע",[["2838","54","<b>מי לי בשמים</b>: תהלים עג, כה."],["2839","55","<b>כלה שארי</b>: תהלים שם, כו."],["2840","56","<b>ולבבי</b>: ב: לו לבדו."],["2841","57","<b>אני הוי'. . מאמ\"צ</b>: שלח טו, מא."],["2842","58","<b>תפלות אבות תקנום</b>: ברכות כו, ב."],["2843","59","<b>אבינו. . רחם עלינו</b>: ברכת ק\"ש (אהבת עולם — בדילוג)."],["2844","60","<b>בנפשותינו וע\"ד</b>: ב: בנפשינו בכדי שלא נבוש לעולם ועד."],["2845","61","<b>אדם שם מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."],["2846","62","<b>דבהמה שם ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["2847","63","<b>וכפר בעדו ובעד ביתו</b>: אחרי טז, יא."],["2848","64","<b>אוא\"ס לא שרי' רק באתר שלים</b>: ראה זהר ויחי רטז, ב. אמור צ, ב. לקו\"ת אמור לח, רע\"א ובהנסמן במ\"מ לשם."],["2849","65","<b>זכר ונקבה בראם כו' ויברך אותם</b>: בראשית ה, ב [בלי תיבת כו']. וראה בראשית א, כז [ושם: ברא אותם]. כח."],["2850","66","<b>אנכי הוי' אלקיך</b>: יתרו כ, ב."]]],[4801940383,"אחר ליל א' דפסח<sup data-n=\"2851\">67</sup> דייקא, וזהו שאין גומרין ההלל בז' ימי הפסח<sup data-n=\"2852\">68</sup> כמו בז' ימי הסוכות והיינו מפני שאע\"פ שהי' הגילוי בליל א' לנה\"א מ\"מ אח\"כ צ\"ל ירידה והתלבשות בנה\"ט בכדי לברר ולכן<sup data-n=\"2853\">69</sup> גם למעלה באדה\"ע דז\"א כו' ואז צריך שיתעלה<sup data-n=\"2854\">70</sup> הגילוי בליל א' בפסח כו' וד\"ל.\n<b>והנה</b> להבין ענין הנפת העומר ביום ט\"ז, ומה שסופרים ליום הנפת העומר ז' שבתות תמימות עד ממחרת השבת יום מ\"ת כו'. הנה מתחלה י\"ל ענין עומר שעורים כי שעורה הוא מאכל בהמה<sup data-n=\"2855\">71</sup> ונק' שעורה שיעור ה\"א<sup data-n=\"2856\">72</sup>. וביאור הדברים הנה ידוע דבחי' בהמה רבה רביעא על אלף טורין<sup data-n=\"2857\">73</sup>, כי הנה ענין רבה בכאן אינו בחי' ריבוי והתחלקות רק העצם הכולל בתוכו בהעלם כל בחי' ריבוי והתחלקות שיבואו ממנו לידי גילוי ופי' רבה בכאן גדולה וכמאמר זעקת סדום ועמורה כי רבה<sup data-n=\"2858\">74</sup> שפי' גדלה. והענין כי ידוע שיש בחי' י\"ב בקר והים<sup data-n=\"2859\">75</sup> כו' שזהו ד' מחנות שכינה<sup data-n=\"2860\">76</sup> פני ארי' להימין ופני שור<sup data-n=\"2861\">77</sup> כו' וחי' בכלל בהמה<sup data-n=\"2862\">78</sup> וכ\"א מד' מחנות כלול מג' לזאת נק' י\"ב בקר כו'. והנה כ\"א מי\"ב בחי' הנ\"ל הוא נק' בשם בהמה רבה להיותו כולל בעצמו ריבוי והתחלקות פרטי' שבאים ממנו לידי גילוי כידוע דמחנה מיכאל קפ\"א<sup data-n=\"2863\">79</sup> אלף כו' וכן למטה ביצי' עד למטה בעשי' גשמי' יש ריבוי והתחלקות מינים ממינים שונים בחיות ובכל מין כמה פרטים לאין שיעור ופני ארי' שבמרכבה הוא מקור הכוללם יחד וכן פני שור מקור כל הבהמות<sup data-n=\"2864\">80</sup> כו', וע\"ד דוגמא זאת יש ג\"כ בנשמות כמו שבט ראובן הוא גילוי בחי' ראי'<sup data-n=\"2865\">81</sup> דחכ' בכלל ובו יש כמה נשמות פרטים שכולם הם בחי' ראי' רק שכ\"א אינו דומה לחבירו וכן שבט יהודה בחי' הודאה<sup data-n=\"2866\">82</sup> בכלל כולל כמה פרטים בתוכו כו' אך יש בחי' בהמה רבה באצילות שהוא",[["2851","67","<b>ספה\"ע אחר ליל א' דפסח</b>: ראה בסמוך בפנים. מאמרי אדה\"א במדבר ח\"ב ע' תקיז."],["2852","68","<b>שאין גומרין ההלל בז' ימי הפסח</b>: ראה שו\"ע אדה\"ז הל' פסח סת\"צ, ס\"ו. סידור אדה\"ז קודם סדר הלל."],["2853","69","<b>ולכן</b>: ב: וכן."],["2854","70","<b>שיתעלה</b>: שם: שיתעלם."],["2855","71","<b>שעורה הוא מאכל בהמה</b>: ראה מל\"א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."],["2856","72","<b>שעורה שיעור ה\"א</b>: זהר בלק קפח, ב. ראה גם לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 38."],["2857","73","<b>בהמה רבה רביעא על אלף טורין</b>: ראה זהר בראשית יח, ב. הנסמן במאמרי אדה\"א ויקרא ח\"א ע' יב."],["2858","74","<b>זעקת סדום ועמורה כי רבה</b>: וירא יח, כ."],["2859","75","<b>י\"ב בקר והים</b>: מל\"א ז, כה. מד. דהי\"ב ד, טו."],["2860","76","<b>ד' מחנות שכינה</b>: זהר במדבר קיח, ב."],["2861","77","<b>פני ארי' להימין ופני שור</b>: יחזקאל א, י."],["2862","78","<b>וחי' בכלל בהמה</b>: ב\"ק יז, ב."],["2863","79","<b>דמחנה מיכאל קפ\"א </b>[ב: ק\"פ]<b> אלף</b>: כנראה הוא ע\"פ מ\"ש בזוהר ח\"ג קנד, א. . וא\"כ צ\"ל כאן: קפ\"ו אלף. . ולא קפיד להעתיק גם מספר המאות שבזוהר שם (סה\"מ ת\"ש ע' 40 בהערה). ולהעיר שכ\"ה גם בכ\"מ ומהם — ראה לקמן מאמר ד\"ה וספרתם הד' על יד הערה 39. ד\"ה והניף הכהן אותם תקפ\"ו על יד הערה 47. ד\"ה בשברי לכם הא' על יד הערה 22. מאמרי אדה\"א ויקרא ח\"א ע' רכד. וש\"נ. הנחות תקע\"ז ע' לד. וש\"נ. תו\"ח שמות ח\"א ל, ב."],["2864","80","<b>בחיות. . ופני ארי'. . פני שור מקור כל הבהמות</b>: ראה גם מאמרי אדה\"א דברים ח\"ד ע' א'רו. וש\"נ."],["2865","81","<b>ראובן. . בחי' ראי'</b>: ראה מאמרי אדה\"א בראשית ע' תצח (ובהנסמן בריש המאמר שם) וע' תקלג."],["2866","82","<b>יהודה בחי' הודאה</b>: ויצא כט, לב. ראה מאמרי אדה\"א שם ע' תצז (ובהנסמן בריש המאמר שם) וע' תקל ואילך."]]],[4801940427,"המל' דאצי' שזהו מקור כללי לכל בחי' י\"ב בקר הנ\"ל [ואפשר גם לנשמות דבי\"ע שנק' זרע בהמה וצ\"ע], ושרש הריבוי וההתחלקות שנמשך מבחי' המל' שהוא כח אלקי פשוט בתכלית הוא ע\"י שבנין המל' הוא מהגבו' שזהו בחי' ה\"ג מנצפ\"ך<sup data-n=\"2867\">83</sup> וה' אותיות דשם אלקים המחלקים השפע כו' וד\"ל. וכמשל אותיות הדיבור המתחלקים מהבל הלב הפשוט ע\"י ה' מוצאות הפה וכן אותיות המח' מתחלקים מכח המחשבה הפשוטה ע\"י ה\"ג [ונק' ה\"ג דאימא פתוחי חותם<sup data-n=\"2868\">84</sup> כו'].\n<b>והנה</b> זהו בחי' ההתהוות מאין ליש שהוא ע\"י ה\"ג משם ב\"ן שנק' בהמה אך בחי' ביטול היש לאין שם כללות<sup data-n=\"2869\">85</sup> הנבראים שבטלים במקורם שם ב\"ן הנ\"ל שזהו בחי' שעורה מאכל בהמה וזהו שיעור ה' בחי' ה\"ג כי הנה ידוע בענין ויוצר משרתים ואשר משרתיו<sup data-n=\"2870\">86</sup> דואשר משרתיו הוא בחי' מלאכים שחיים וקיימים משימ\"ב אך יוצר משרתים המה המתהווים מאין ליש מבחי' הבירורים דרפ\"ח ניצוצי' ונכללים במקורם בפי בהמה עילאה בחי' שם ב\"ן וזהו מצמיח חציר לבהמה<sup data-n=\"2871\">87</sup> כמו למטה בגשמי' צומח חציר בכל יום וכורתים אותם למאכל בהמה כו', אך הבירור והתכללות הוא צ\"ל ג\"כ ע\"י ה\"ג כי צ\"ל תגבורת הגילוי משם ב\"ן לדחות הרע ולהמשיך הטוב אליו, ולכן נק' טרף כמו ארי' טורף בגבורה, אך גם הגילוי הזה אף שבא בתגבורת מ\"מ צ\"ל במדה ושיעור לבל יהי' ביטול מציאותם לגמרי כו' וזהו שעורה שעור ה' כו' וד\"ל. והנה כללות הבירורים שנתבררו ונכללו בשם ב\"ן נק' בחי' עומר שעורים מאכל בהמה אך עומר זה עדיין צריך להניף אותו ע\"י הכהן שהוא דוגמת אדה\"ע ועי\"ז מתברר בירור אחר בירור [שזהו בירור דשם מ\"ה המברר בירור אחר בירור דשם ב\"ן אך ע\"י בירור השני<sup data-n=\"2872\">88</sup> עולה בשרשו בשם ס\"ג<sup data-n=\"2873\">89</sup> דתוהו לפני מלוך מלך<sup data-n=\"2874\">90</sup> כו'] עד שעולה לפני הוי' דתיקון כו' וד\"ל.\n<b>והנה</b> ע\"י הנפת העומר נעשה כללות עלי' הבירורים דשם ב\"ן למעלה לשרשו ולמטה בנש\"י שבגופים נעשה בהם בנפשם הטבעית בכלל ביטול רצון לה' אחד ביטול אמיתי כמו ברצון דנה\"א וכללות ענין זה דתנופת העומר שהוא ביטול<sup data-n=\"2875\">91</sup> הרצון הוא בחי' בירור פנימי והעלאה היינו שנתברר ונתהפך הרצון להיות רצונו רק לה' אחד [שזהו בחי' לב אחד לאביו שבשמים<sup data-n=\"2876\">92</sup> שנתייחדו ב' הלבבות שהוא ב'",[["2867","83","<b>ה\"ג מנצפ\"ך</b>: ראה מאמרי אדה\"א ויקרא ח\"א ע' רלז. וש\"נ."],["2868","84","<b>ה\"ג דאימא פתוחי חותם</b>: תצוה כח, יא. ראה לקמן מאמר ד\"ה בשברי לכם הא' על יד הערה 33. שעה\"י קלז, סע\"א. קלח, א ובהנסמן במ\"מ לשם."],["2869","85","<b>שם כללות</b>: ב: שבכללות."],["2870","86","<b>ויוצר </b>[ב: יוצר]<b> משרתים ואשר משרתיו</b>: ברכת יוצר. ראה איכ\"ר פ\"ג, ח. טאו\"ח סנ\"ט. מאמרי אדה\"א בראשית ע' קכו. וש\"נ. הנחות תקע\"ז ע' לג. וש\"נ. לקמן מאמר ד\"ה אם בחוקותי תר\"י על יד הערה 89."],["2871","87","<b>מצמיח חציר לבהמה</b>: תהלים קד, יד."],["2872","88","<b>דשם מ\"ה המברר. . בירור השני</b>: ראה תו\"א ויחי מז, ד ואילך."],["2873","89","<b>דשם ב\"ן. . בשם ס\"ג</b>: ראה לקו\"ת בחוקותי מז, ג ובהנסמן במ\"מ לשם. מאמרי אדה\"א דברים ח\"ב ע' תקעג. תו\"ח וארא ח\"א ע, ג. וש\"נ."],["2874","90","<b>לפני מלוך מלך</b>: וישלח לו, לא."],["2875","91","<b>רצון לה'. . ביטול</b>: ניתוסף ע\"פ ב."],["2876","92","<b>לב אחד לאביו שבשמים</b>: ברכות נז, א."]]],[4801940467,"חללי הלב משכן והשראת נה\"א ונה\"ט להיות רק לה' אחד כו'], רק אח\"כ צ\"ל נמשך ביטול רצון הזה בפרט בכל המדות וזהו\"ע ספרה\"ע, והנה בענין ספרה\"ע יש ב' בחי' הא' המשכת המקיפים בבחי' המדות, והב' בירור והעלאת פנימי' המדות, וביאור הדברים הנה אנו רואים בעבודה שבלב ב' בחי' הא' היינו כאשר ההתבוננות הוא מבחי' ואתה מחי' את כולם<sup data-n=\"2877\">93</sup> היינו איך שהוא מחי' ומהווה כל העולמות מאין ליש בכל עת ובכל רגע עד שהוא מחי' גם את נפשו בקרבו ומזה יתפעל בלב באה' כמאמר לאה' את ה' כי הוא חייך<sup data-n=\"2878\">94</sup>, והתפעלות זאת יש בה יתרון שמבררת ומהפכת המדות שבלב כו', אבל מ\"מ יש חסרון מצד אחר להיות שההתפעלות בא במורגש לזאת יכול להיות הסתעפות יניקת החיצונים כמו אברהם יצא ממנו ישמעאל<sup data-n=\"2879\">95</sup> כו', וכמו יניקת הצפרניים מן הידים שהוא בחי' מותרות, וכך גם במדות האהבה שמבחי' המורגש של המדה יוכל להיות מותרות יניקה כו' כמו מן ההתפעלות בעבודת ה' יכעס על המנגד כו', והבחי' הב' בעבודת ה' הוא כאשר ההתבוננות הוא מבחי' אוא\"ס איך שהוא מרומם לבדו וכולא קמי' כ\"ח שזהו בחי' עומק ופנימי' בינה, והתבוננות הזאת לא יכילנה כלי הלב רק שנשארה בבחי' מקיף על הלב ויש בה יתרון שאין מזה<sup data-n=\"2880\">96</sup> יניקה לחיצונים כי שרש המקיפים דבינה מסמא עיני החיצונים<sup data-n=\"2881\">97</sup> [וכידוע שזהו בחי' צפור דרור שדרה בבית כבשדה<sup data-n=\"2882\">98</sup> בלי שום פחד וכן וקראתם דרור<sup data-n=\"2883\">99</sup> בחי' בינה עלמא דחירות<sup data-n=\"2884\">100</sup> כו'], אבל יש בזה חסרון מצד זה שאינו נמשך בחי' בירור פנימי' המדות והתהפכותם מחושך לאור ולכן בספרה\"ע פועלים ב' בחי' הא' בחי' המשכת המקיפים מבינה למדות להיות שמירה מיניקת החיצוני' והב' בירור העלאת המדות כו'.\n<b>וזהו</b> משארז\"ל מצוה למימני יומי ומצוה למימני שבוע<sup data-n=\"2885\">101</sup>, כי מנין הימים שאומרים היום יום א' לעומר הוא המשכת המקיפים מבינה למדות ומבחי' מדות לבחי' מל' הנק' עומר<sup data-n=\"2886\">102</sup> שעורים [ונק' בזוהר יומין דדכורא<sup data-n=\"2887\">103</sup> כו'], ואח\"כ כשנגמרו כל פרטי המשכת המקיפים בשבעה בחינותיהם אז נעשה כללות הבירור בהמדה ונתעלה המדה בבחי' העלאה מלמטה למעלה [שזהו ענין עליות יומין דנוקבא ממטה למעלה וכמבואר בזוהר שכאשר נמשכו ז' ימים מסט' דדכורא עולה כנגדה מדה",[["2877","93","<b>ואתה מחי' את כולם</b>: נחמי' ט, ו."],["2878","94","<b>לאה' את ה' כי הוא חייך</b>: נצבים ל, כ [בדילוג]."],["2879","95","<b>אברהם. . יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. וש\"נ. שע\"ת פה, ג ובהערה 14. תו\"ח בא ח\"א קכז, ב."],["2880","96","<b>מזה</b>: ב: בזה שום."],["2881","97","<b>המקיפים. . מסמא עיני החיצונים</b>: ראה ע\"ח שער דרושי אבי\"ע שמ\"ב, פי\"ג. מאמר ד\"ה הוא הי' אומר תרל\"א [קונט' בר מצוה תרנ\"ג ע' לט]."],["2882","98","<b>צפור דרור שדרה בבית כבשדה</b>: ראה זהר תצוה קפג, א. רש\"י משלי כו, ב."],["2883","99","<b>וקראתם דרור</b>: בהר כה, י."],["2884","100","<b>בינה עלמא דחירות</b>: מאו\"א מערכת דרור אות יג."],["2885","101","<b>מצוה למימני יומי ומצוה למימני שבוע</b>: מנחות סו, א."],["2886","102","<b>מל' הנק' עומר</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תרנד. וש\"נ."],["2887","103","<b>יומין דדכורא</b>: ראה זהר רע\"מ אמור צז, ב."]]],[4801940502,"אחת מסט' דנוקבא<sup data-n=\"2888\">104</sup> כו']. והעלאה ובירור זה הוא היפוך המדות ממש וזהו היום שבעה ימים שזהו המשכת המקיפים מבחי' דכורא בינה וז\"א שהם שבוע א' זהו בירור והעלאת מדת החסד דמל' כו', וכן בכל ז' שבועות ולכן נק' ז' שבתות ל' נקבה כו', וזהו ע\"ד דוגמא מששה ימי החול והשבת הבא אחרי' שבחי' ששת ימים המה המשכות מדות<sup data-n=\"2889\">105</sup> עליונות מבחי' מדות דז\"א למטה בבי\"ע לברר בירורים ואח\"כ בחי' שבת הוא הוא בחי' עליות המל' ולכן נק' יום השביעי, ואעפ\"כ השבת גבוה יותר מצד שהוא בחי' עלי' כו' וד\"ל.\n<b>ועתה</b> יובן ג\"כ ענין ממחרת השבת שפי' מחרת יו\"ט<sup data-n=\"2890\">106</sup> אך א\"כ למה קראו בשם מחרת השבת, אך מרמז בזה עוד כוונה אחרת, שכח הספי' לברר ולזכך המדות בא ונמשך ממקום גבוה שהוא ממחרת השבת, כי ידוע שבשבת יש ג' בחי' שבת דמעלי שבתא ושבתא דיומא<sup data-n=\"2891\">107</sup> ובחי' שבת שבתון<sup data-n=\"2892\">108</sup> שזהו בחי' מל' וז\"א ובינה, וכן ענין הספי' נמשך ממחרת השבת שהוא בחי' שבת שבתון שזהו המשכת המקיפים כנ\"ל, ועי\"ז ממילא נעשה גם הבירור בפנימי' כנ\"ל וד\"ל. ונמצא מובן שכללות ענין הספי' הוא בחי' בירור והעלאת נה\"ט דייקא בבחי' רצוא ולמעלה הוא בחי' העלאת שם ב\"ן הנקרא בהמה רבה ובחי' מאכל דעומר שעורים לשרשו כנ\"ל באריכות. וזהו שאו' בספי' מזמור אלקים יחננו ויברכנו<sup data-n=\"2893\">109</sup> אלקים דייקא שהוא בירור דשם ב\"ן<sup data-n=\"2894\">110</sup> עי\"ז נתגלה מקורו שהוא בחי' פנימיותו כמ\"ש בשרשו הנק' אלקים ולכן אומרים ב\"פ יודוך עמים<sup data-n=\"2895\">111</sup> כי עמים הם ז' מדות<sup data-n=\"2896\">112</sup> דנה\"ט שבכאו\"א מישראל שנתבררו ונזדככו עד שנעשו כדוגמת ספירות עליונות ממש והיינו ע\"י המשכת המקיפים ופנימי' כנ\"ל [וכמו למעלה אור המקיף מזכך חצי הכלי מבחוץ<sup data-n=\"2897\">113</sup> ואור הפנימי מזכך חצי הכלי מבפנים כו' וד\"ל].\n<b>והנה</b> כאשר נשלם בחי' הרצוא בנה\"א ונה\"ט וכן למעלה בבחי' מ\"ה דאדם וב\"ן דבהמה אזי ויברך אותם שאז נמשך המשכת גילוי אוא\"ס במ\"ת, וזהו קול דודי מדלג על ההרים הוא ברגל א', כי הנה כללות כל הגילויי' דאוא\"ס הגם",[["2888","104","<b>עליות יומין. . דנוקבא</b>: ראה גם לקו\"ת מסעי פט, סע\"ד."],["2889","105","<b>מדות</b>: ניתוסף ע\"פ ב."],["2890","106","<b>ממחרת השבת שפי' מחרת יו\"ט</b>: תו\"כ אמור כג, טו. מנחות סה, ב."],["2891","107","<b>שבת דמעלי שבתא ושבתא דיומא</b>: זהר בהקדמה ה, ב."],["2892","108","<b>שבת שבתון</b>: ויקהל לה, ב. ראה גם בענין שבת שבתון לקו\"ת נצבים נג, ב. יו\"כ סח, ד. לקמן מאמר ד\"ה את שבתותי תרי\"ב על יד הערה 95. ד\"ה ביאור והתהלכתי תר\"ב על יד הערה 76."],["2893","109","<b>אלקים יחננו ויברכנו </b>[ב: ליתא]: מתהלים סז, ד."],["2894","110","<b>אלקים. . דשם ב\"ן</b>: ראה תו\"ח ויצא קסו, א הערה 19. שמות ח\"א יט, ג הערה 814."],["2895","111","<b>אומרים ב\"פ יודוך עמים</b>: מתהלים שם, ד. ו."],["2896","112","<b>עמים הם ז' מדות</b>: ראה גם מאמרי אדה\"א קונטרסים ע' רמא. וש\"נ. ש\"א סא, ב ובהערה 20. סה\"מ תר\"ל ע' רפח. לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 39."],["2897","113","<b>אור המקיף מזכך חצי הכלי מבחוץ</b>: ראה ע\"ח שער העקודים ש\"ו, פ\"ב. שער השתלשלות הי\"ס ש\"ב ענף ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' תצט. ח\"ב ע' תתקלט. תו\"ח פקודי ח\"ב תמט, ד ואילך."]]],[4801940534,"שהוא בעילוי אחר עילוי מ\"מ המה רק בחי' אחרונה שבעצמי' ונק' בחי' רגל, אך בפסח שאין הגילוי רק למעלה בשרש נה\"א שהוא בחי' אדה\"ע לכן נק' בחי' דילוג ברגל א' אבל בשבועות שהוא בחי' מ\"ת נק' קפיצה בשתי רגלים להיות שהגילוי הוא למעלה ולמטה בהשוואה ונק' כתר א' לשניהם<sup data-n=\"2898\">114</sup>, אך א\"א להיות גילוי זה כ\"א ע\"י הספי' והטעם הוא מחמת שתי סיבות הא' מחמת שהגילוי הוא ממקום נעלה כזה א\"א להיות רק כאשר אתכפי' סט\"א וכידוע שבלתי אפשר הי' להתגלות מ\"ת רק עד שהודה יתרו עתה ידעתי<sup data-n=\"2899\">115</sup> כו', והטעם הוא מצד שרש נה\"ט שהוא לפני מלוך מלך כו' וגם מצד העולמות שכאשר נתברר ונתהפך גם נה\"ט אזי הוא שלימות דגילוי אלקות למטה גם בנה\"ט ולזה שורה ונמשך מבחי' פנימי' ועצמות אוא\"ס שלימותא דכולא<sup data-n=\"2900\">116</sup> וכנ\"ל בענין זו\"נ בראם כו'. אך כ\"ז הוא מצד עצם הגילוי המתגלה ממקום נעלה ביותר שבלתי אפשרי להתגלות כ\"א אחר שלימות הבירור דנה\"ט, והב' הוא טעם הפשוט להיות שתומ\"צ עיקרם באים למטה לברר בחי' עולם שהוא בחי' דצ\"ח דנוגה כמו ע\"י מצות התפילין נתברר הקלף ויוצא מתחת ממשלת נוגה וניכלל בקדושה האלקי' וידוע דעיקר הבירור הוא ע\"י האדם דייקא [שהוא הנה\"א כאשר היא מלובשת בנה\"ט הנק' אדם] וכמאמר אלה המצות אשר יעשה אותם האדם<sup data-n=\"2901\">117</sup> כו' ולזאת צ\"ל שיתברר נה\"ט בתכלית בכדי שיוכל אח\"כ לברר דצ\"ח ע\"י תומ\"צ כי כל מברר לא יוכל לברר<sup data-n=\"2902\">118</sup> זולתו עד שיהי' בעצמו מתוקן ומבורר בתכלית, ולכן צ\"ל ספרה\"ע תחלה וספרתם לכם שהוא בירור וזיכוך דנה\"ט עד שתהי' בבחי' ספיר כנ\"ל ואז תוכל לברר ע\"י תומ\"צ ולכן אחר הספירה הוא מ\"ת כו' וד\"ל.",[["2898","114","<b>כתר א' לשניהם</b>: ראה ע\"ח שער מיעוט הירח של\"ו, פ\"א."],["2899","115","<b>עתה ידעתי</b>: יתרו יח, יא. ראה זהר יתרו סז, ב. סח, א. תו\"ח יתרו ח\"ב רעא, ד ואילך (ובהנסמן בריש המאמר שם). מאמרי אדה\"ז על פרשיות התורה ח\"א ע' ש. ע' שב. ע' שג. ע' שה."],["2900","116","<b>אוא\"ס שלימותא דכולא</b>: ראה עבודת הקודש ח\"א רפ\"ח. דרך אמונה להנ\"ל מהדורת קה\"ת ע' יג ובהנסמן שם. לקו\"ת עקב טז סע\"א. הלשון שלימותא דכולא — ראה ת\"ז בהקדמה (יז, ב)."],["2901","117","<b>אלה המצות אשר יעשה אותם האדם</b>: חיבור שני כתובים בחוקותי כז, לד. אחרי יח, ה. ראה גם הנסמן במאמרי אדה\"א ויקרא ח\"א ע' תא. תו\"ח בשלח ח\"א קעה, ד."],["2902","118","<b>כל מברר לא יוכל לברר</b>: ראה לקו\"ת צו ז, סע\"ד ואילך. בלק סט, א. תו\"ח ויקהל ח\"ב תיז, ד. וש\"נ. לעיל ע' כו. לקמן מאמר ד\"ה והניף הכהן אותם הב' על יד הערה 78."]]],[4801940113,"<b>רישומי דברים מש\"א אדמו\"ר שליט\"א יום א' דחה\"ש לעת ערב ברי\"ת</b>\n<b>וספרתם</b> לכם<sup data-n=\"2903\">1</sup> ממחרת השבת<sup data-n=\"2904\">2</sup> מיום הביאכם את עומר התנופה כו'. הנה בזהר אמרו על פסוק זה וספרתם לכם לכם דייקא<sup data-n=\"2905\">3</sup> כד\"א וספרה לה שבעת ימים<sup data-n=\"2906\">4</sup> לה לעצמה אוף הכא לכם לעצמכם כו'. ולהבין זה מה שהמשיל ענין ספה\"ע ז' שבועות לספירת ז' ימים באשה לטהר עצמה כו'. הנה ידוע דביום חתונתו זה מ\"ת<sup data-n=\"2907\">5</sup> שענין מ\"ת נמשל לענין יחוד חו\"כ שכמו ביחוד חו\"כ הכלה קולטת הטיפה הנמשכת מפנימי' המוחין של החתן המשפיע בה כן במ\"ת הקב\"ה נק' חתן וכנ\"י כלה<sup data-n=\"2908\">6</sup> וענין המשכת השפע הוא הגילוי דאנכי<sup data-n=\"2909\">7</sup> שהוא בחי' פנימי' עצמותו שלמעלה מבחי' הארה הנמשכת להחיות העולמות (... שאותה הארה נק' בחי' אני כו' משא\"כ אנכי הוא בחי' פנימי' המשפיע ומהותו שנמשך ונקלט בנש\"י. ..), וזהו\"ע נתינת התורה לישראל וכמו האשה כאשר נצרכת להתייחד צריכה לנקות א\"ע מדמי' ולספור שבעה נקיים כן הוצרכו נש\"י לספור שבע שבתות בכדי לנקות א\"ע מהפסולת שלהם כי מצרים הוא ערות הארץ<sup data-n=\"2910\">8</sup> שהמשיכה עליהם טומאת נדה וכאשר יצאו ממצרים וניקו א\"ע מהפסולת (... כדוגמת הפסק טהרה באשה. ..) אז הוצרכו לספור שבע שבתות כי באשה שהיא פרטי' מספיק ז' ימים משא\"כ בכללות נש\"י הספירה הוא ז' שבועות תמימות דווקא, וזהו כד\"א וספרה לה לעצמה היינו להנאתה בכדי שתוכל לקבל אח\"כ שפע הטיפה כן בכללות נש\"י וספרתם לכם לעצמכם ולהנאתכם בכדי שתוכלו לקלוט בתוככם השפע דאנכי כנ\"ל וכמשי\"ת וד\"ל.\n<b>והנה</b> להבין מתחלה מה שנמשל שפע התורה לקליטת הטיפה כו' ילה\"ק ענין כאיל תערוג על אפיקי מים<sup data-n=\"2911\">9</sup> ופרש\"י שענין תערוג הוא בלה\"ק מורה על צעקת האיל כמו שמורה נוהם על צעקת הארי וגועה על צעקת השור ושוקק על צעקת הדוב כו' וכאשר נשכיל בעומק יותר יש לחבר ל' תערוג עם ערוגת הבושם<sup data-n=\"2912\">10</sup> כו', ויתפרש תערוג צעקה על העדר העונג כי יש ב' מיני צעקה הא' צעקה מן הכאב",[["2903","1","<b>וספרתם לכם</b>: הנחת ר\"ה מדרוש כ\"ק אדמו\"ר הצ\"צ.\nמאמר הצ\"צ נדפס בביאוה\"ז ח\"א ע' שמב [ושם הפתיחה: פתח ר\"ש ואמר כאיל תערוג]. והוא דרוש כ\"ק אדמו\"ר הזקן (עם הוספות וכו') שנדפס במאמרי אדה\"ז תקס\"ז בשני נוסחאות ע' קכג (הנחת כ\"ק אדה\"א) וע' קכה (הנחת הר\"מ בן אדה\"ז).\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["2904","2","<b>וספרתם לכם ממחרת השבת</b>: אמור כג, טו."],["2905","3","<b>בזהר. . וספרתם לכם לכם דייקא</b>: זהר אמור צז, ב."],["2906","4","<b>וספרה לה שבעת ימים</b>: מצורע טו, כח. ראה גם כתובות עב, א ובתוס' שם."],["2907","5","<b>דביום חתונתו זה מ\"ת</b>: שה\"ש ג, יא. תענית כו, ב [במשנה]."],["2908","6","<b>הקב\"ה נק' חתן וכנ\"י כלה</b>: וכל שה\"ש מיוסד ע\"ז כידוע במדרשי רז\"ל. ראה גם מאמרי אדה\"א נ\"ך ע' רלא. וש\"נ. תו\"ח וארא ח\"א עה, ג ובהערה 7."],["2909","7","<b>דאנכי</b>: יתרו כ, ב."],["2910","8","<b>מצרים הוא ערות הארץ</b>: מקץ מב, ט. יב. קה\"ר פ\"א, ד (בסופה). ע\"ח שער ציור עולמות שמ\"ג, פ\"א."],["2911","9","<b>כאיל תערוג על אפיקי מים</b>: תהלים מב, ב. ראה רש\"י שם."],["2912","10","<b>ל' תערוג עם ערוגת הבושם</b>: שה\"ש ה, יג. פי' מנחם ברש\"י תהלים שם."]]],[4801940177,"ויסורין רח\"ל כו' והב' צעקה על העדר התענוג בלבד והיינו כאשר הי' מורגל באיזה עונג ועכשיו ניטל ממנו אז הוא צועק על העדרו וצעקה זאת נק' בשם תערוג כו', וגם כאן צעקת האיל הוא על אפיקי מים שהוא מקור מוצא מים והמים הוא מקור העונג (... כידוע דמים מצמיחים כל מיני תענוג<sup data-n=\"2913\">11</sup> כו'. ..) והצעקה הוא על הסתלקות מקור התענוגים כו'.\n<b>וביאור</b> הענין יובן בהקדם המאמר דקוב\"ה אתא לאשתעשע בגנתא דעדן עם צדיקיי'<sup data-n=\"2914\">12</sup> והשעשוע הוא בלימוד התורה שלומדים אחר חצות והלימוד שלהם הוא מה שלמדו בעוה\"ז דווקא כמאמר אשרי מי שבא לכאן<sup data-n=\"2915\">13</sup> ותלמודו בידו שהוא תלמודו שלמד בעוה\"ז דווקא כו', ולכאורה איך שייך שהקב\"ה יקבל עונג מבחי' לימוד התורה שבעוה\"ז דווקא, הנה אנו רואים למטה באדם כאשר ישכיל שכל חדש תתמלא נפשו בתענוג מחמת ההשכלה שהשכיל כו' (... והכוונה שאין תענוג זה שמתענג מהשכלת שכל דומה לתענוג שמתענג מדברים אחרים כמו מעשיית החסד וטוב או כאשר מתענג ממון וכבוד שאינו רק התעוררות גילוי עונג מצומצם בנפש ונק' עונג מורכב כו' משא\"כ מהשכלת שכל חדש יתעורר בנפש מקור העונג לבוא לידי גילוי בבחי' עונג פשוט עד שכללות הנפש מתמלא במילוי אורה ושמחה כו', והיינו להיות כי מקור העונג ומקור השכל הכל אחד<sup data-n=\"2916\">14</sup> הוא כמשי\"ת. ..), היינו מחמת שמקור השכל הוא בלחלוחית הרוחני' שבמוח ושם הוא מקור העונג ג\"כ לכן ע\"י השכלת שכל חדש יתגלה מקור העונג בנפש. אך א\"כ למה אנו רואים חילוקים שונים בדיעות בנ\"א בענין התענוג שמצד החכ' יש שמתענג משכל זה ולא יתענג משכל אחר ובחבירו יכול להיות להיפוך כמו עד\"מ החכם אומן כל העונג שלו הוא כאשר מוציא שכל חדש במלאכת העשי' ולא יתענג מחכמת המדות, ויש שיתענג מחכמת המדות ולא יתענג מחכ' שבעשי', ויש שמתענג מבחי' השכלות עמוקות שאינם שייכים לא לבחי' המדות ולא לבחי' העשי' כמו חכמות התכונה וחכ' דקדוק הלשון כו' וגם בזה יש חילוקים שונים יש שמתענג מחכ' זאת ולא מחכ' אחרת ויש להיפוך וכמו עבנ\"י<sup data-n=\"2917\">15</sup> שכל עיקר העונג שלהם הוא בחכ' האלקי' דווקא שהוא חכ' התורה ולא מחכ' אחרת זולתה ולפי טעם הנ\"ל הי' צריך שכל האנשים יתענגו מכל חכ' שיהי' כו'. אך הענין הוא שגילוי אור התענוג מוכרח להיות בבחי' איזה כלי כו' והכלי לגילוי העונג הוא היוקר וחשיבות דווקא (... כמו גם בגשמי' הממון אנו רואים שיש בנ\"א שאינם מקבלים תענוג ממנו רק שמחזירים אחריו בכדי למלאות הצטרכותם ההכרחיות נמצא שאין עצם הממון יקר וחשוב בעיניהם רק התועלת הנמשך ממנו, ויש בנ\"א שעצם הממון יקר וחשוב בעיניהם לכן מקבלים עונג ממנו בעצמו בלי שום תועלת נמשך ממנו כ\"ה בענין החכ' יש מי שאין",[["2913","11","<b>דמים מצמיחים כל מיני תענוג</b>: תניא פ\"א."],["2914","12","<b>דקוב\"ה אתא לאשתעשע. . עם צדיקיי'</b>: ראה זהר אחרי (כאן) סז, ב. לך עז, א."],["2915","13","<b>אשרי מי שבא לכאן</b>: פסחים נ, א."],["2916","14","<b>מקור העונג ומקור השכל הכל אחד</b>: ראה גם לקמן מאמר ד\"ה אם בחוקותי הא' על יד הערה 95. ד\"ה והתהלכתי תרט\"ו על יד הערה 248. תו\"ח יתרו ח\"ב רסז, ג. וש\"נ."],["2917","15","<b>עבנ\"י</b>: א: עמינו ב\"י."]]],[4801940234,"החכ' יקרה בעיניו רק מצד התועלת הנמשך ממנה ואין זה יוקר אמיתי ויש שעצם ענין החכ' יקר וחשוב בעיניו בלתי שום תועלת נמשך ממנה כו' (... כמאמר מילתא אלבישייהו יקירא<sup data-n=\"2918\">17</sup> כו'<sup data-n=\"2919\">16</sup>. ..) והמופת לזה הוא כאשר שוה אצלו בענין חכ' כאשר המציא אותה מעצמה או כאשר לימד אותה מזולתו, וזהו\"ע מאמרם ז\"ל איזהו חכם הלומד מכל אדם<sup data-n=\"2920\">18</sup> כו' ועד\"ז יש ג\"כ חילוקי מדריגות בפרט בענין החכ' גופא יש שחכ' זאת יקרה בעיניו ויש שחכ' אחרת יקרה בעיניו כמשי\"ת. ..) ולכן גם התענוג שבחכ' תלוי בחשיבות ויוקר החכ' כו' ויוקר וחשיבות של החכ' תלוי בשרש נשמתו אם הוא מעשי' אז החכ' שבעשי' הוא אצלו בבחי' יוקר וחשיבות ואם שרש נשמתו הוא מעולם היצירה אז היוקר שלו הוא בחכ' המדות כו' ועד\"ז יש כמה חילוקי מדריגות בדיעות בנ\"א בענין היוקר וחשיבות של החכ' לפ\"ע שרש נשמתו כו', ובזה תלוי ג\"כ בחי' התענוג שבחכ' שלו כמשנ\"ת.\n<b>ועד\"ז</b> יובן למעלה בענין התענוג שהקב\"ה מקבל מחכמת התורה כו' כי הנה אנו רואים ריבוי חילוקי מדריגות בענין החכ' כו' כי הנה למטה בעשי' גשמי' יש בחי' חכ' שהוא חכ' ושכל אנושי והנה חכ' זאת מוכרח להיות מקור השופע אותה כמו ע\"ד שארז\"ל אין לך עשב<sup data-n=\"2921\">19</sup> מלמטה שאין לו מזל מלמעלה המכה אותו<sup data-n=\"2922\">20</sup> ואומר לו גדל, שכל טעמי הפירות יש להם שרש ומקור רוחני במזלות הרוחני', כן עד\"ז יש מקור לחכ' האנושי' במזלות הרוחני' (... כמארז\"ל מזל מחכים<sup data-n=\"2923\">21</sup> כו'. ..), והנה כמו שאין ערך למתיקות הגשמי לגבי מתיקות הרוחני שבמזל הרוחני הגם שנמשכת ממנה הוא ע\"י ריבוי השתלשלות וצמצומי' רבים כו', כן אין ערך מחכ' האנושי' לחכ' הרוחני שבמזל הרוחני רק שנמשכת ממנה ע\"י השתל' רבות, וכעד\"ז גבוה מעל גבוה שומר<sup data-n=\"2924\">22</sup> כי המזלות מקבלים מבחי' האופנים<sup data-n=\"2925\">23</sup> והאופנים מקבלים מבחי' י\"ס דעשי'<sup data-n=\"2926\">24</sup>, נמצא שיש שרש לחכ' האנושית בבחי' ספי' החכ' שבעולם העשי' הרוחני' והיא מקבלת ממנה אך אעפ\"כ אין ערוך מחכ' האנושית לחכ' האלקי' שבעולם העשי' אעפ\"י שמקבלת ממנה כנ\"ל, וכן עד\"ז אין ערך מחכ' דעשי' לבחי' החכ' דיצירה ומחכ' דיצירה לגבי חכ' דבריאה וכן מחכ' דבריאה לחכ' דאצילות הריחוק הוא יותר לאין ערוך מהריחוק שמחכ' האנושי' לגבי חכ' דבריאה כו', אך גם החכ' דאצי' הוא מקור לבחי' חכ' שבכל העולמות דבי\"ע והוא רק הארה בעלמא מעצמות חכמתו אבל חכמת התורה הוא חכמתו העצמי' ממש והיא נבדלת במעלה מכל בחי' חכ' שבעולמות דאבי\"ע, והנה חכמתו העצמי' שהוא בחי' תורה שלמעלה ירדה למטה",[["2918","17","<b>מילתא אלבישייהו יקירא</b>: שבת י, ב."],["2919","16","<b>(כמאמר. . כו'. ..)</b>: תוקן ע\"פ אז. ולכאורה הסגול'ס מיותרים כיון שזה מובא בתוך הגהתו. אבל ז כנראה העתיק מגוכ\"י של ר\"ה."],["2920","18","<b>איזהו חכם הלומד מכל אדם</b>: אבות רפ\"ד."],["2921","19","<b>אין לך עשב</b>: ראה ב\"ר פ\"י, ו. מאמרי אדה\"א דברים ח\"ג ע' תתמח. וש\"נ. שם ע' תתעו ואילך. שער האמונה ע' נג. אוה\"ת וארא כרך ח ע' ב'תתפג."],["2922","20","<b>אותו</b>: ניתוסף ע\"פ ה."],["2923","21","<b>מזל מחכים</b>: שבת קנו, א."],["2924","22","<b>גבוה מעל גבוה שומר</b>: קהלת ה, ז."],["2925","23","<b>המזלות מקבלים מבחי' האופנים</b>: ראה פרדס שער אבי\"ע שט\"ז, פ\"ח. תו\"ח וארא ח\"א ס, ג. וש\"נ."],["2926","24","<b>והאופנים מקבלים מבחי' י\"ס דעשי'</b>: ראה גם שעה\"י קמה, סע\"ב ואילך."]]],[4801940287,"ממדריגה למדריגה עד שנתלבשה בהלכות הגשמי' ולכן נמשלה התורה למים כמבואר בלק\"א<sup data-n=\"2927\">25</sup> כו', ונמצא שהחכ' שבהלכות הגשמי' הם בבחי' עילוי יותר מכל מדריגות שבעולמות אפי' מבחי' חכ' שבאצילות כו' (... וזהו היוקר וחשיבות שבחכ' התורה וכמאמר יקרה היא מפנינים<sup data-n=\"2928\">26</sup> כו'. ..).\n<b>והנה</b> עם כל הנ\"ל יובן ענין שהקב\"ה משתעשע עם חכמת התורה שבעוה\"ז דווקא להיות שתורה זאת יקרה היא בעיניו מחמת שהיא בבחי' עילוי והפלאה למעלה מכל בחי' חכ' שבעולמות דאבי\"ע וידוע שהנהגת העולמות מוכרח להיות ע\"י המדות דחו\"ג כי ההשפעה מוכרח להיות ע\"י החסד אך אם הי' השפע נמשכת בלי צמצום לא היו המקבלים יכולים לקבל ונמצא שאין זה חסד כלל לזאת מוכרח להתגלות מדת הגבו' לצמצם השפע בכדי שיתקבל במקבל שזהו תכלית החסד כו', וכן לפעמים יומשך בחי' מדת הגבורה למנוע השפע משאינו ראוי לכך ועד\"ז יהי' לפעמים ההנהגה ע\"י מדה\"ר היינו אע\"פ שאינו ראוי מצד מדת הדין מ\"מ יומשך בו השפע מצד הרחמנות כו', ונמצא שהנהגת העולמות שבמדת המלוכה היא מקבלת מלמעלה היינו מבחי' המדות דז\"א כו', והמדות מתנהגים ע\"פ המוחין דחו\"ב חכ' הוא מקור לקו הימין דחסד ובינה הוא מקור לקו השמאל<sup data-n=\"2929\">27</sup> דגבורה כו', וזהו מלך במשפט יעמיד ארץ<sup data-n=\"2930\">28</sup> כו', ונמצא שבחי' קוב\"ה הוא בחי' המדות דאצי' עם המוחין השייכים למדות המתלבשים במדת המלוכה כו', אך בחי' חכ' התורה היא למעלה מבחי' החכ' השייך למדות כו' (... רק בבחי' או\"א עילאין<sup data-n=\"2931\">29</sup> שלמעלה מבחי' המוחין דז\"א כו'. ..) לכן ע\"י לימוד הלכות דעוה\"ז ששרשם בחכ\"ע ממש שהוא חכמתו העצמי' ממשיכים מוחין יותר עליונים בבחי' המדות הנק' בשם קוב\"ה כנ\"ל למעלה דמקור החכ' ומקור התענוג אחד ולכן ממילא מתגלה בו גם העונג העליון הנק' שעשועי המלך בעצמותו<sup data-n=\"2932\">30</sup> כו' ומטעם הנ\"ל שיוקר החכ' ממשיך תענוג וזהו\"ע הנ\"ל דקוב\"ה אתא לאשתעשע כו' עם צדיקיי' כו' מלימוד הלכות שלמדו בעוה\"ז דווקא כו' וד\"ל.\n<b>וזהו</b> ענין אז תתענג על הוי'<sup data-n=\"2933\">31</sup> שהו\"ע העונג שבעצמות השעשועי' שהוא למעלה משם הוי' והכוונה הוא על קיבול שכר הצדיקים שהם מתענגים בעונג שלמעלה משם הוי' ששם הוי' עצמו מקבל תענוג משם וזהו ענין השעשועים",[["2927","25","<b>נמשלה התורה למים כמבואר בלק\"א</b>: פ\"ד. וראה במ\"מ הגהות והע\"ק לשם."],["2928","26","<b>יקרה היא מפנינים</b>: משלי ג, טו."],["2929","27","<b>חכ'. . לקו הימין. . ובינה. . השמאל</b>: ראה זהר רע\"מ בהעלותך קנג, ב. פרדס שער סדר עמידתן ש\"ו, פ\"א. מאמרי אדה\"א בראשית ע' ריז. וש\"נ."],["2930","28","<b>מלך במשפט יעמיד ארץ</b>: משלי כט, ד."],["2931","29","<b>או\"א עילאין</b>: ראה ע\"ח שער הזווגים שט\"ו, פ\"א (מ\"ב). פ\"ד. לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 21."],["2932","30","<b>שעשועי המלך בעצמותו</b>: ראה עמה\"מ שער זה. מאמרי אדה\"א שמות ח\"ב ע' תנג. קונטרסים ע' שמה ובהנסמן בהנ\"ל. וראה גם לקמן מאמר ד\"ה את שבתותי תרי\"ב ובהערה 130."],["2933","31","<b>אז תתענג על הוי'</b>: ישעי' נח,יד. ראה גם לעיל ע' מא. לקמן מאמר ד\"ה והתהלכתי תרט\"ו על יד הערה 244. מאמרי אדה\"א דברים ח\"ג ע' א'קי. וש\"נ. תו\"ח וארא ח\"א נ, ב. וש\"נ."]]],[4801940337,"שהקב\"ה משתעשע עם הצדיקים שמקבלים עצמו' השעשועים כנ\"ל וד\"ל. וזהו ג\"כ ענין והשביע בצחצחות נפשך<sup data-n=\"2934\">32</sup> שהו\"ע השעשועים שבתורה וידוע שבתורה יש מ\"ט פנים טמא ומ\"ט פנים טהור<sup data-n=\"2935\">33</sup> בגי' צ\"ח והו\"ע דודי צח ואדום<sup data-n=\"2936\">34</sup> ולכן השעשועים דתורה נק' צחצחות כו', וזהו ג\"כ ענין לכו ונלכה באור הוי'<sup data-n=\"2937\">35</sup> היינו באור המאיר לשם הוי' עצמו כו', וזהו\"ע ונהר יוצא מעדן<sup data-n=\"2938\">36</sup> להשקות את הגן כי עדן הוא מקור השעשועים הנק' שעשועי המלך בעצמותו ונהר הוא המשכת השעשועים הנ\"ל שנמשך למטה להשקות את הגן שהוא מה שמאיר בגעה\"ע בלימוד הלכות שלומדים בג\"ע והו\"ע קוב\"ה אתא לאשתעשע כנ\"ל. והנה בחי' זאת נק' ערוגת הבושם עד\"מ הגן שיש בו הרבה ערוגות שבכל ערוגה נזרע מין פרטי כן העונג ושעשועי' הנ\"ל מתחלק בגעה\"ע לכל צדיק כפי מדריגתו בכמה חילוקי מדריגות פרטי' ולכן נק' בשם ערוגת הבושם כו' וד\"ל.\n<b>ובכל</b> הנ\"ל יובן מה שיש בכח מעשה המצות הגשמי' לעורר אורות למעלה ולהמשיכם למטה כמו כן כללות הקרבנות שלוקחין בהמה גשמי' ועושין בה ד' עבודות שחיטה וקבלה והולכה וזריקת הדם ואח\"כ הקטרת האימורין ועי\"ז גורמין למעלה ריח ניחוח להוי' ואח\"כ נמשך שפע למטה בכל העולמות מרכ\"ד עד סוכ\"ד וכן בענין המבואר בפ' זאת<sup data-n=\"2939\">37</sup> שע\"י הזאת הדם בהיכל ק\"ק מעוררים אורות עליונים למעלה לכפר על הקדש מטומאות בנ\"י כו', ואיך יכול להיות ע\"י מעשה גשמי' התעוררות אורות עליונים שאין ערוך ממעשה הגשמי' אליהם. אך עם כל הנ\"ל יובן ענין זה והיינו בהקדם הידוע שבחי' התענוג הוא מקור השמחה<sup data-n=\"2940\">38</sup> ובחי' השמחה הוא מקור השפלות<sup data-n=\"2941\">39</sup> כמו המלך שאע\"פ שהוא תמיד מרומם ומובדל מעמו ומתנשא עליהם מ\"מ בעת שמחתו מתגלה לכל וישפיל א\"ע לדבר עם כולם ולקרב אותם כו', ומעתה יובן ענין הנ\"ל להיות שמעשה המצות נעשים ע\"פ חכמת התורה ובחכמת התורה מלובש עצמות השעשועי' כנ\"ל, ולכן ע\"י מעשה הגשמי' הנעשה ע\"פ משפט התורה מעוררים עונג ושעשועים למעלה ומבחי' שעשועי' נמשך בחי' שמחה ושמחה זאת גורם השפלת אורות עליונים מבחי' סוכ\"ע להתלבש במעשה הגשמי' כנ\"ל וד\"ל. אך מי יכול לעורר ע\"י מעשה המצות שעשועי' העליונים הם נש\"י דווקא והטעם להיות שהם בחי' בנים כמאמר בנים אתם להוי' אלקיכם<sup data-n=\"2942\">40</sup> ומוח הבן נמשך ממוח האב<sup data-n=\"2943\">41</sup> והיינו מבחי' מקור העונג המלובש בלחלוחית הרוחני' שבמוח וכן שרש נש\"י נמשך מבחי' פנימי' התענוג העליון הנק' שעשועי המלך בעצמותו, ולכן כאשר הם עושים המצוה ע\"פ חכ' התורה מעוררים עונג ושעשועי' הנ\"ל ולא אחר זולתם",[["2934","32","<b>והשביע בצחצחות נפשך</b>: ישעי' נח, יא."],["2935","33","<b>מ\"ט פנים טמא ומ\"ט פנים טהור</b>: ראה ירושלמי סנהדרין פ\"ד, ה\"ב. שע\"ת עח, א הערה 2."],["2936","34","<b>דודי צח ואדום</b>: שה\"ש ה, י. ראה מג\"ע אופן רמה. רמו."],["2937","35","<b>לכו ונלכה באור הוי'</b>: ישעי' ב, ה."],["2938","36","<b>ונהר יוצא מעדן</b>: בראשית ב, י."],["2939","37","<b>המבואר בפ' זאת</b>: כ\"ה בהכ\"י. ראה אחרי טז, יד ואילך."],["2940","38","<b>התענוג הוא מקור השמחה</b>: ראה לקו\"ת נצבים מז, ד."],["2941","39","<b>השמחה הוא מקור השפלות</b>: ראה גם לקו\"ת שם."],["2942","40","<b>בנים אתם להוי' אלקיכם</b>: פ' ראה יד, א."],["2943","41","<b>ומוח הבן נמשך ממוח האב</b>: ראה תניא פ\"ב."]]],[4801940384,"כו', וזהו בכלל ענין מ\"ת והוא מה שנקלט פנימי' התענוג העליון הנק' אנכי כו' במקור נש\"י ועי\"ז יוכלו לעורר אח\"כ בתמידות עונג העליון ע\"י מעהמ\"צ שעושים כו' וד\"ל. ולכן נק' מ\"ת ביום חתונתו שהקב\"ה הוא בחי' החתן להשפיע בחי' התורה שהוא בחי' פנימי' עונג העליון בנש\"י הנק' כלה ע\"ש שמקבלים עונג הנ\"ל כו' וד\"ל.\n<b>והנה</b> בזמן הבית הי' בחי' יחוד פב\"פ בתמידות כמו בשעת מ\"ת (... כמבואר במאמר הכרובים בתורה אור בפ' תרומה<sup data-n=\"2944\">42</sup> כו'. ..), והיינו שהי' מאיר פנים שלמעלה שהוא פנימי' עונג העליון במקור נש\"י וכן נש\"י הי' כל פנימי' העונג שלהם רק להתענג על הוי' וזהו פנים בפנים<sup data-n=\"2945\">43</sup>, אך בזה\"ג נאמר קוב\"ה אסתלק לעילא לעילא<sup data-n=\"2946\">44</sup> שהוא בחי' פנימי' העונג שנסתלק ואינו מאיר בכנס\"י ולכן אינו מאיר בחי' שמחה במעהמ\"צ רק שנעשי' בחיצוני' מאד וזהו\"ע כאיל תערוג שבחי' כנס\"י הנק' בחי' איל<sup data-n=\"2947\">45</sup> צועקת על העדר העונג שנסתלק ממנה וזהו על אפיקי מים כי מים מצמיחי' כל מיני עונג והיינו מחמת שמלובש בהם מקור כל התענוגים כו', ולכן נק' מקור כל התענוגים בשם אפיקי מים מקור מוצא המים כו' וד\"ל.\n<b>ועתה</b> יובן מה שכנס\"י בזה\"ג נמשל לאשה נדה<sup data-n=\"2948\">46</sup> וכן הי' בגלות מצרים<sup data-n=\"2949\">47</sup> כו' כי נדה היא נ\"ד ה'<sup data-n=\"2950\">48</sup> והיינו שבחי' ה' שהוא כנס\"י נתרחקה ונדה מן המשפיע והיינו שאינו מאיר בה מפנימי' התורה הנק' שעשועי' ולכן נד\"ה ר\"ת נאלמתי דומי' החשיתי<sup data-n=\"2951\">49</sup> והיינו שהקול נסתלק מן הדיבור וממילא גם הדיבור נתעלם עד שאינו יכול לדבר, וביאור ענין הקול היינו קול תורה שנק' קול יעקב מלא בוי\"ו<sup data-n=\"2952\">50</sup> כי ידוע שהתורה ניתנה בה' קולות<sup data-n=\"2953\">51</sup> והיינו שצ\"ל ה' בחי' ירידות והמשכות מהעלם אל הגילוי עד שתתלבש התורה במדת המלוכה הנק' דיבור להיות שהתורה הוא בחי' שעשועי' העצמי' וראשית הירידה וההתלבשות הוא בבחי' הרצון ומהרצון אל החכ' ומחכ' לבינה ומבינה למדות דחג\"ת ומחג\"ת לנה\"י ואח\"כ נמשך בבחי' הדיבור וזהו אז ראה ויספרה<sup data-n=\"2954\">52</sup> הכינה וגם חקרה כו', אז הוא מקדמת דנא<sup data-n=\"2955\">53</sup> הוא הרצון הנק' קדם,",[["2944","42","<b>במאמר הכרובים בתורה אור בפ' תרומה</b>: ראה שם פ, א."],["2945","43","<b>פנים בפנים</b>: ואתחנן ה, ד."],["2946","44","<b>קוב\"ה אסתלק לעילא לעילא</b>: ראה זהר ויגש רי, א. ויקרא כ, ב. מאמרי אדה\"א הנחות תקע\"ז ע' ג. וש\"נ. תו\"ח שמות ח\"א לט, סע\"א ואילך ובהערה 72."],["2947","45","<b>כנס\"י הנק' בחי' איל</b>: זהר אחרי (כאן) סח, רע\"א."],["2948","46","<b>שכנס\"י בזה\"ג נמשל לאשה נדה</b>: ראה ערכי הכנויים לבעל סה\"ד מערכת נדה — ישראל."],["2949","47","<b>וכן הי' בגלות מצרים</b>: ראה זהר שנסמן בריש המאמר."],["2950","48","<b>נדה היא נ\"ד ה'</b>: ראה זהר רע\"מ פינחס רכו, א. וראה גם מאמרי אדה\"א דרושי חתונה ח\"א ע' קיז."],["2951","49","<b>נד\"ה ר\"ת נאלמתי דומי' החשיתי</b>: תהלים לט, ג. באוה\"ת (יהל אור) תהלים עה\"פ מציין לר\"ח שער הקדושה פי\"ז בד\"ה גם צריך ליזהר. וראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקנה. וש\"נ. ח\"ד ע' א'תקי. דרושי חתונה ח\"א ע' נב וע' קיז."],["2952","50","<b>תורה שנק' קול יעקב מלא בוי\"ו</b>: תולדות כז, כב. ראה סידור שער התפלה יט, סע\"א ואילך. תו\"ח בא ח\"א קח, ג. וש\"נ."],["2953","51","<b>שהתורה ניתנה בה' קולות</b>: ברכות ו, ב. ראה גם מאמרי אדה\"ז תקס\"ה ח\"ב ע' תרלה. מאמרי אדה\"א במדבר ח\"ב ע' תרפה. וש\"נ."],["2954","52","<b>אז ראה ויספרה</b>: איוב כח, כז."],["2955","53","<b>אז הוא מקדמת דנא</b>: ראה גם שה\"א נ, א ובהערה 3."]]],[4801940428,"ראה הוא בחי' חכ', ויספרה הוא בחי' בינה הנק' ספר, הכינה בחג\"ת, וגם חקרה בנה\"י, ואח\"כ ויאמר לאדם<sup data-n=\"2956\">54</sup> שהוא התלבשות במל' דאצי' הנק' דבר הוי' כו' וד\"ל. ולכן כאשר נסתלק אור התורה הנק' שעשועי' מכנס\"י הוא הסתלקות הקול וממילא נתעלם הדיבור ונק' נד\"ה כנ\"ל, וממילא נמשך תוס' יניקה לחיצוני' וכמאמר כרחל לפני גוזזי' נאלמה<sup data-n=\"2957\">55</sup>, ותוס' יניקה זאת הוא שפע ה' דמים טמאים<sup data-n=\"2958\">56</sup> שיוצאים ממנה ולכן נד\"ה בגי' זוהמא<sup data-n=\"2959\">57</sup>, שזהו נמשך מזוהמת הנחש<sup data-n=\"2960\">58</sup> שהטיל זוהמא בחוה<sup data-n=\"2961\">59</sup> כו' וד\"ל.\n<b>(אך</b><sup data-n=\"2962\">60</sup> י\"ל למה הסתלקות העונג מכנס\"י גורם יציאות הפסולת להיות מקור יניקת החיצוני' שזהו\"ע נד\"ה בגי' זוהמא כנ\"ל, יובן ע\"פ המבואר במ\"א ששרש יניקת החיצוני' הוא משני בחי'<sup data-n=\"2963\">61</sup> הא' מבחי' אור הפנימי שנק' ממכ\"ע ומבחי' זאת לא תוכל לקבל כ\"א בסוף מדריגות הפנימי' שהם בחי' צמצומים היותר אחרונים (שהם מ\"ח צירופי' האחרונים דשם אלקים<sup data-n=\"2964\">62</sup> כמבואר במ\"א) שמוסתר האור לגמרי ואז יוכלו להיות<sup data-n=\"2965\">63</sup> בבחי' נפרד משא\"כ כאשר מאיר האור בגילוי קצת אינו שורה רק בסט' דקדושה כי אוא\"ס אינו שורה רק במי שבטל אליו<sup data-n=\"2966\">64</sup> כו' ועז\"נ הן גוים כמר מדלי<sup data-n=\"2967\">65</sup> שהם מקבלים התמצית ושמרים של השפע המאיר דרך מ\"ח צירופים האחרונים כנ\"ל, אך בחי' הב' שרש יניקתם הוא מבחי' המקיף הנק' סוכ\"ע כי אור המקיף הוא שוה ומשוה כו' וקמי' כחשיכה כאורה ואינו תופס מקום הביטול דחכ' לפניו לכן גם החיצונים מקבלים יניקה אעפ\"י שאין בהם בחי' הביטול כו', ומצד זה יוכלו למשול על ישראל וזהו אם תגביה כנשר<sup data-n=\"2968\">66</sup> והיינו שמגביהים א\"ע לקבל מבחי' המקיפים כנשר כי דרך הנשר בשמים<sup data-n=\"2969\">67</sup> בבחי' מקיפים עליונים כו' אך משם אורידך<sup data-n=\"2970\">68</sup> כו' כי הנה פנימי' העונג הנק' שעשועי' עצמי' כנ\"ל הוא למעלה מבחי' סובב וממלא כי סובב וממלא שניהם הם בחי' המשכת השפע בעולמות אך בחי' שעשועי' העצמי' הוא בחי' גילוי אור עצמותו שלמעלה מבחי' סובב וממלא, ושם אין מקום רק לתורה",[["2956","54","<b>ויאמר לאדם</b>: איוב שם, כח."],["2957","55","<b>כרחל לפני גוזזי' נאלמה</b>: ראה ישעי' נג, ז. תו\"ח ויצא קסו, ג הערה 53."],["2958","56","<b>ה' דמים טמאים</b>: נדה יט א (במשנה) ראה גם מאמרי אדה\"א דברים ח\"ג ע' תתקנה. וש\"נ."],["2959","57","<b>נד\"ה בגי' זוהמא</b>: מאו\"א מערכת זוהמא אות ט."],["2960","58","<b>שזהו נמשך מזוהמת הנחש</b>: ראה ת\"ז ת\"מ פ, א. תס\"ט קיח, סע\"ב."],["2961","59","<b>הנחש שהטיל זוהמא בחוה</b>: שבת קמו, רע\"א."],["2962","60","<b>(אך. . וד\"ל. ..)</b>: הגהה זו של ר\"ה חסירה בכמה כת\"י. ראה גם הנרשם לקמן ברשימת הכת\"י."],["2963","61","<b>יניקת החיצוני' הוא משני בחי'</b>: ראה פלח הרמון שמות ע' יז וע' תכב. תו\"א וישלח כו, ב. תו\"ח שמות ח\"א כג, ד ואילך. כה, ב. לא, ב ואילך. סה\"מ תרכ\"ז ס\"ע תצג ואילך. וש\"נ."],["2964","62","<b>מ\"ח צירופי' האחרונים דשם אלקים</b>: ראה פע\"ח שחה\"מ שכ\"א, פ\"ה. הנסמן במאמרי אדה\"א דברים ח\"ג ע' א'סא. פלח הרמון שמות ס\"ע שנג ואילך."],["2965","63","<b>להיות</b>: ה: לקבל. ז: כבפנים."],["2966","64","<b>אוא\"ס אינו שורה רק במי שבטל אליו</b>: ראה תניא פ\"ו."],["2967","65","<b>הן גוים כמר מדלי</b>: ישעי' מ. טו."],["2968","66","<b>אם תגביה כנשר</b>: עובדי' א, ד. ראה תו\"א וישלח כו, ב. מאמרי אדה\"ז תקס\"ו ע' פד."],["2969","67","<b>דרך הנשר בשמים</b>: משלי ל, יט. ראה גם לעיל ריש ע' רט."],["2970","68","<b>משם אורידך</b>: עובדי' שם."]]],[4801940468,"ולישראל לבדם כנ\"ל שהתורה משבחת ואהי' שעשועים יום יום<sup data-n=\"2971\">69</sup> וכן נש\"י נק' בנים<sup data-n=\"2972\">70</sup> כו', וכח המוליד נמשך מפנימי' העונג כנ\"ל ולכן כאשר נמשך ע\"י התורה השפע מפנימי' העונג הנ\"ל הוא גורם שגם אור המקיף הנק' סוכ\"ע יתלבש בבחי' קו המדה דחכ' ואזי נמשך פנימי' השפע לישראל ונכרת שרש יניקתם מבחי' המקיף ואינם מקבלים רק התמצית ושמרים כנ\"ל, ולכן לא יוכלו למשול על ישראל. אך בזה\"ג שנסתלקו פנימי' העונג הנק' שעשועי' מבחי' כנס\"י כנ\"ל אז הוא גורם שנעשה תוס' יניקה לחיצונים והתוס' הוא מבחי' אור המקיף כנ\"ל דקמי' כחשיכה כאורה וזהו\"ע טומאת נד\"ה שהיא המשכת פסולת הדמים להיות מהם יניקה ח\"ו לחיצוני' כנ\"ל וד\"ל. ..).\n<b>אך</b> ענין היציאה מן הגלות הו\"ע כאיל תערוג הנ\"ל שהו\"ע הצעקה על מניעות העונג ובזה מעורר עונג העליון להתגלות ולהיות נקלט בכנס\"י כו', והנה כ\"ה ענין תנופת העומר שהוא בחי' ביטול רצון ועקירת כל הרצונות להיות רק רצון אחד לה' לבדו שבזה יוצא מן הגלות, והוא כמשל אשה הפוסקת בטהרה. אך אח\"כ צ\"ל ספי' ז' שבועות שזהו\"ע שבע שבתות תמימות היינו שצריך להפוך כל ז' המדות שיהי' רק לה' לבדו ואינו מספיק היפוך המדות בד\"כ כי כל מדה כלולה מז' כמו החסד כלול מכל הז' וכן מדת הגבו' לכן צריך להפוך כל המדות בפרט ואז נק' בשם תמימות שלא נשאר שום אחיזה לרע בז' המדות משא\"כ בהיפוך המדות בד\"כ יש עדיין שמץ אחיזה לרע. והנה אחר הבירור של המדות בשלימות זפ\"ז נמשך בחי' מ\"ט שע\"ב ואח\"כ מתגלה שער החמשים ביום החמשים והו\"ע התגלות בחי' שעשועי' העצמי' שהו\"ע התורה בשער הנו\"ן דבינה ומשם נמשך במל' מקור נש\"י שזהו ענין קליטת הטיפה בכנס\"י, וזהו וספרתם לכם לעצמכם ולהנאתכם ע\"ד וספרה לה לעצמה כו' וד\"ל.\n<b>(והנה</b><sup data-n=\"2973\">71</sup> המתבאר מכל הנ\"ל בדרך קצרה שענין מ\"ת הוא קליטת פנימי' העונג הנק' שעשועים בכנס\"י הנק' כלה ודבר זה לא יוכל להיות כ\"א כאשר יוצא מן הגלות שהו\"ע היציאה מן ההיפוך שזהו\"ע יצי\"מ בכלל ואח\"כ ענין ספרה\"ע שהו\"ע בירור ז' המדות בפרט ואז הוא יוצא לגמרי מן ההיפוך (שזהו כמשל ספי' ז' נקיי' באשה כנ\"ל), ואז אח\"כ כנס\"י ראוי' ליחוד היינו לקבל בתוכה אור ושפע שעשועי' העליונים העצמי' שזהו\"ע מ\"ת כו'. וביאור טעם הדברים למה לא יוכל להאיר אור השעשועי' בגלות, הנה מבואר שעיקר משכן והשראת התענוג העצמי הוא בלחלוחית הרוחני'<sup data-n=\"2974\">72</sup> שבמוח אשר שם הוא ג\"כ מקור השכל ולכן גם התגלות התענוג העצמי הוא ג\"כ בבחי' חו\"ב והיינו כאשר נתגלית החכ' ממקורה מבחי' האין דחכ' כח המשכיל ונמשכה בהתגלות בבחי' בינה אז מתגלה בהם בחי' תענוג הפשוט העצמי הנ\"ל וזהו שעשועי' יום יום כי יום יום הוא בחי' חו\"ב<sup data-n=\"2975\">73</sup> ובהם משכן והתגלות",[["2971","69","<b>ואהי' שעשועים יום יום</b>: משלי ח, ל."],["2972","70","<b>נש\"י נק' בנים</b>: פ' ראה יד, א."],["2973","71","<b>(והנה</b>: מכאן ואילך נמצא רק בחלק מהכת\"י (ראה גם הנרשם לקמן ברשימת הכת\"י). ז אחרי תיבת ”וד\"ל\" כתב: מוגה ובשורה שלאח\"ז כתב: סליק, ובשורה שלאח\"ז מתחיל (... והנה."],["2974","72","<b>העצמי. . הרוחני'</b>: ה: ליתא. . ליתא."],["2975","73","<b>יום יום. . חו\"ב</b>: ראה גם לעיל ע' עו. וש\"נ."]]],[4801940503,"התענוג העצמי, והנה בחי' חו\"ב הוא בחי' שרש אותיות י\"ה<sup data-n=\"2976\">74</sup> כידוע והנה ידוע דעליות המל' הנק' כנס\"י<sup data-n=\"2977\">75</sup> לקבל מבחי' י\"ה שהוא בחי' חו\"ב עילאין הוא ע\"י רחימו ודחילו עילאין שהוא בחי' אהבה בתענוגים שעי\"ז עולה המל' לבחי' בינה עילאה וע\"י יראה עילאה עולה לבחי' חכ\"ע וזהו מש\"א בזוהר דהנסתרות להוי' אלקינו הוא בחי' דו\"ר דבמוחא ולבא<sup data-n=\"2978\">76</sup> וידוע דנסתרות נק' או\"א עילאין ע\"ש שהם מכוסים תחת הדיקנא<sup data-n=\"2979\">77</sup> כמבואר בכהאריז\"ל, והתגלותם בבחי' המל' הנק' כנס\"י הוא ע\"י דו\"ר דמוחא ולבא הנ\"ל כו', ואז כאשר המל' עולה לבחי' חו\"ב אז מקבלת וקולטת בתוכה בחי' פנימי' העונג הנק' שעשועי' כו', ואז נק' המל' בשם אלקים כו' משא\"כ כשאינו מאיר בה בחי' אהוי\"ר עילאין הנ\"ל, אז מסתלקין ממנה בחי' שרש<sup data-n=\"2980\">78</sup> אותיות דו\"ה<sup data-n=\"2981\">79</sup> הנ\"ל ונקראת בחי' אלם בלבד וממילא לא תוכל לקלוט אור השעשועי' הנ\"ל כי בחי' שעשועי' הנ\"ל אינו מאיר כ\"א ע\"י שתי אותיות די\"ה הנ\"ל כנ\"ל, ולכן בגלות שאינו מאיר בכנס\"י בחי' אהוי\"ר לכן אינו מאיר גם אור השעשועים בכנס\"י. והנה ידוע דבעת יצי\"מ היתה האה' בגלות ולכן לא האיר בהם בחי' שעשועים הנ\"ל אך כאשר יצאה בחי' האה' מן הגלות וההיפוך והיינו ע\"י יצי\"מ וספה\"ע אז ממילא נתגלה אור התורה הנק' שעשועים בשער החמשים דבינה ואז נתגלה אור השעשועי' ממילא בבחי' המל' הנק' כנס\"י וזהו שניתנה התורה ביום החמשים<sup data-n=\"2982\">80</sup> אחר יציאתם ממצרים כנ\"ל.\n<b>והנה</b> עכשיו בגלות האחרון בחי' היראה היא בגלות כפי ששמעתי מאדמו\"ר שליט\"א במאמר אני ישנה הנא' שנת תר\"א<sup data-n=\"2983\">81</sup> וכ\"ה בהערה לתו\"ח<sup data-n=\"2984\">82</sup>, והיינו שנמשכה בחי' יראה חיצוני' שהוא ירא שלא יגע לבחי' היש שלו כמו פן יחסר לחמו<sup data-n=\"2985\">83</sup> וכה\"ג שארי יראות חיצוניות ובהם מלובשת היראה פנימי' רק שהיא בגלות בלבוש שק דיראה חיצוני' הנ\"ל, ולכן נשמת משיח שיוציאנו מן הגלות הזה האחרון בבי\"א<sup data-n=\"2986\">84</sup> נאמר עליו והריחו ביראת ה'<sup data-n=\"2987\">85</sup> כו' ולכן עכשיו בזה\"ג אין אור השעשועי' מאיר מצד חסרון היראה (הגם שאה' אינה עכשיו בגלות כמבו' בהערה לת\"ח הנ\"ל) אך לימות המשיח כאשר תוצא היראה מן הגלות אז יאיר אור השעשועי' בכנס\"י באופן הגבוה מאד נעלה יותר מבשעת מ\"ת כידוע וד\"ל. והנה ידוע בענין מציץ מן",[["2976","74","<b>חו\"ב. . י\"ה</b>: ראה זהר אד\"ז האזינו רצ, ב. אגה\"ת פ\"ד. מאמרי אדה\"א דברים ח\"ב ע' שסו וע' תרנו."],["2977","75","<b>המל' הנק' כנס\"י</b>: ראה זהר בלק קצז, א."],["2978","76","<b>דהנסתרות להוי' אלקינו. . דו\"ר דבמוחא ולבא</b>: ראה זהר רע\"מ נשא קכג, ב."],["2979","77","<b>דנסתרות נק' או\"א. . הדיקנא</b>: ראה גם ע\"ח שער הולדת או\"א שט\"ז, פ\"ו. לקו\"ב לשעה\"י קנח, ג ובהערה 5."],["2980","78","<b>שרש</b>: ה: שתי."],["2981","79","<b>דו\"ה</b>: ה: י\"ה."],["2982","80","<b>שניתנה התורה ביום החמשים</b>: ראה שו\"ע אדה\"ז סדר תפלת חגה\"ש סתצ\"ד, ס\"א."],["2983","81","<b>אני ישינה הנא' שנת תר\"א</b>: אולי הכוונה למאמר ד\"ה זה שנדפס בפלח הרמון שה\"ש ע' עג. אמנם ברשימת הרח\"א ביחובסקי מדרושי ר\"ה בראש בוך 1228 ע' פה נרשם המאמר ומציין: ”ליל ר\"ה תר\"ב\". וראה גם בפלה\"ר שם מב, ב."],["2984","82","<b>בהערה לתו\"ח</b>: ה: לת\"ח לתיקון חצות — נדפס בסידור קנב, סע\"א."],["2985","83","<b>פן יחסר לחמו</b>: ע\"פ ישעי' נא, יד."],["2986","84","<b>בבי\"א</b>: במהרה בימינו אמן."],["2987","85","<b>והריחו ביראת ה'</b>: ישעי' יא, ג."]]],[4801940535,"החרכים<sup data-n=\"2988\">86</sup> שגם עכשיו בזה\"ג יש פרקים ועתים ידועים שנעשה בחי' יחוד דעצמות אוא\"ס בנש\"י שהו\"ע גילוי השעשועים הנ\"ל בכנס\"י והיינו בכל חצות לילה דקוב\"ה אתא לאשתעשע כו' מצד הצעקה דאיל הקודמת לזה כנ\"ל כו', לכן בעת זמן ק\"ש ותפלה בכל יום וכן בשבתות ויו\"ט שכל זמנים הנ\"ל הם זמן היחוד דקוב\"ה בכנס\"י (רק שיש חילוקי מדריגות באופני היחוד כידוע דיש יחוד יעקב ורחל או יעקב ולאה או ישראל ורחל<sup data-n=\"2989\">87</sup> כו' כידוע כ\"ז בכהאריז\"ל) ועכ\"ל שבעיתים הנ\"ל יוצאת כנס\"י מן הגלות ומאיר בה אהוי\"ר הפנימי' שהם שתי אותיות י\"ה הנ\"ל ולכן מתגלה אור השעשועי' ג\"כ ונקלט בכנס\"י.\n<b>והנה</b> עם כל הנ\"ל יבוארו הפסוקים דועתה ישראל מה הוי' כו' שואל כו' כ\"א ליראה כו', ואח\"כ מונה דברים רבים שהם ללכת בכל דרכיו כו' עד לשמור את מצות הוי'<sup data-n=\"2990\">88</sup> ואת חקותיו כו', כי הנה מבואר במדרש על מאמר אחת שאלתי כו' והקושי' דמתחלה א' אחת כו' ואח\"כ מבקש דברים רבים לחזות בנועם ה' כו' עד בצור ירוממני<sup data-n=\"2991\">89</sup> כו', ומבואר שם התירוץ דדוד א' ממך למדתי כו', והקושיא מפורסמת<sup data-n=\"2992\">90</sup> דאיך מתרץ קושיא אחת בחברתה דגם בתו' יקשה איך א' כ\"א ליראה כו' כיון שהוא שואל אח\"כ דברים רבים כו'. אך מבואר התירוץ בשם הרה\"מ ז\"ל<sup data-n=\"2993\">91</sup> דכוונת התירוץ הוא כך ממך למדתי כו' כמו שאתה בקשת מכנס\"י שאלה אחת שהיא בחי' היראה רק שמזה יבוא ממילא שאלות הרבה שהוא ללכת בכל דרכיו כו' כן אנכי שואל מעמך שאלה אחת שהו\"ע שבתי בבית ה' וממילא יבוא אח\"כ כל השאלות הפרטיו' כמו לחזות בנועם ה' עד בצור ירוממני כנ\"ל. והנה שאלת הקב\"ה הוא המשכת התעוררות מלמעלה ליתן כח ועוז בכנס\"י שתוכל לבוא מתחלה ליראה ואח\"כ ממילא תעלה בעילוי אחר עילוי להגיע למדריגות הפרטי' שמונה אח\"כ ללכת בכל דרכיו כו' ושאלת דוד שהוא בחי' כנס\"י הוא אתעדל\"ת העולה בעצמות אא\"ס ואתעדל\"ת זאת גורמת המשכה כללי' מתחלה בד\"כ שהוא שבתי בבית ה' שהוא בחי' אותיות התורה וממילא יומשכו כל הפרטי המשכות אחר האותיות כו' ופרטי הגילויי' הוא לחזות בנועם ה' עד בצור ירוממני כנ\"ל וד\"ל.",[["2988","86","<b>מציץ מן החרכים</b>: שה\"ש ב, ט. ראה גם מאמרי אדה\"א נ\"ך ע' תח ואילך."],["2989","87","<b>יחוד יעקב ורחל. . ולאה או ישראל ורחל</b>: ראה גם ש\"א ו, ב ובהנסמן במ\"מ לשם."],["2990","88","<b>דועתה ישראל מה הוי'. . לשמור את מצות הוי'</b>: עקב י, יב. יג."],["2991","89","<b>במדרש. . אחת שאלתי. . בצור ירוממני</b>: תהלים כז, ד. ה. ראה מדרש תהלים ויל\"ש שם. ראה גם מאמר ד\"ה זה וביאוריו בסה\"מ תקס\"ג ח\"ב ע' תשד ואילך. מאמרי אדה\"א שמות ח\"ב ע' תיא. וש\"נ. תו\"ח שמות ח\"א מח, ד ובהערה 221."],["2992","90","<b>והקושיא מפורסמת</b>: ראה גם מאמר ד\"ה ועתה ישראל תשל\"ז ס\"ב (קונט' כ\"ף מנ\"א תשמ\"ח — סה\"מ מלוקט ח\"ב ע' שכו)."],["2993","91","<b>התירוץ בשם הרה\"מ ז\"ל </b>[ה: נ\"ע]: ראה סה\"מ מלוקט שם שמציין ללקו\"ת מסעי צו, סע\"ב ואילך. אוה\"ת עקב ע' תקעח. המשך תער\"ב ח\"ב ס\"ע א'קיד. ועוד. וראה גם אוה\"ת ואתחנן ע' תיח. האזינו ע' א'תרעח [ושם: הה\"ג המגיד נ\"ע]. סה\"מ תרכ\"ט ע' שכה."]]],[4801940114,"<b>יום א' דחה\"ש תרי\"ט</b>\n<b>וספרתם</b> לכם<sup data-n=\"2994\">1</sup> כו' מיום הביאכם את עומר התנופה<sup data-n=\"2995\">2</sup> כו' תספרו חמישים יום<sup data-n=\"2996\">3</sup> כו'. להבין ענין הבאת העומר, י\"ל ענין הספי' מ\"ט ימים להבאת העומר למה צריך לזה כו', גם להבין מש\"א תספרו חמישים יום הלא אין סופרים רק מ\"ט יום כו', הנה מתחילה י\"ל ענין העומר שנק' מנחה<sup data-n=\"2997\">4</sup>, וידוע דכל המנחות הם מחטים<sup data-n=\"2998\">5</sup> זולת מנחת העומר ומנחת קנאות דסוטה שדומים הם בזה ששניהם באים מן השעורים, הגם שיש הפרש ביניהם<sup data-n=\"2999\">6</sup> שבמנחת סוטה אינו נותן שמן ולבונה<sup data-n=\"3000\">7</sup> מטעם המבואר בדרז\"ל, כי שמן מקור האור, וסוטה כל מעשיה במחשך כו', ולבונה היא כנגד האמהות כמ\"ש גבעת הלבונה<sup data-n=\"3001\">8</sup> ומעשה סוטה היא היפך מעשה אמהות, אבל מנחת שעורים דעומר נעשית בשמן ולבונה. ועוד יש הפרש ביניהם שמנחת העומר היא גרש ומנחת סוטה היא קמח<sup data-n=\"3002\">9</sup>, אך בזה הם דומים ששניהם באים משעורים, וע\"כ לומר שמנחת העומר הוא מעין מנחת סוטה כמשי\"ת.\n<b>הענין</b> הוא מבואר ברע\"מ פ' אמור שבחי' מנחת העומר הוא בדיקו דאשת חיל<sup data-n=\"3003\">10</sup> והיא סמא דמותא לאשת זנונים כו', ופי' הדברים כמו שמנחת סוטה באה לבדוק האשה ואם טהורה היא ונקתה ונזרעה זרע<sup data-n=\"3004\">11</sup> ואם טמאה היא וצבתה בטנה<sup data-n=\"3005\">12</sup> כו' רח\"ל כך ע\"י מנחת העומר ונקתה כנס\"י מדמים הטמאים כו' והיינו שמבדלת ממנה כל מיני רע כו' (... ואח\"כ ספה\"ע הוא ספירת הנקיים כו' ונזרעה זרע בשעת מ\"ת כו' וד\"ל. ..) וממילא נתברר הטוב מאשת זנונים ומתבטלת לגמרי ממציאותה. וזהו סמא דמותא לאשת זנונים כו'. ויובן הענין ע\"פ המבואר בדרז\"ל על הפסוק ה' מסיני בא וזרח משעיר כו' הופיע מהר פארן כו' שהקב\"ה החזיר את התורה<sup data-n=\"3006\">13</sup> על כל אומה ולשון ולא רצו לקבלה כו' וזהו וזרח משעיר כו' מקום דירת עשו כו' הופיע",[["2994","1","<b>וספרתם לכם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nהמאמר מיוסד על דרוש כ\"ק אדה\"ז שנאמר בש\"ק פ' אמור והמשכו ביום ב' פ' בהר שנת תקס\"ה. הנחת כ\"ק אדמו\"ר האמצעי נדפסה בביאוה\"ז אמור קמ, ג. והנחת הר\"מ בן כ\"ק אדה\"ז נדפסה בסה\"מ תקס\"ה ח\"א ע' תעד. ראה ביאוה\"ז לכ\"ק אדמו\"ר הצ\"צ ח\"ב ע' תתקכז. ע' תתקמז.\nדרוש בהתחלה זו נאמר ע\"י כ\"ק אדמו\"ר הצ\"צ שני פעמים בשנת תרי\"ט. פעם ראשון בשבת פ' בהר ופעם שני' ביום א' דחה\"ש. הדרוש דש\"פ בהר נדפס בסה\"מ תרכ\"ו ע' פז (והוא הנחת כ\"ק אדמו\"ר מהר\"ש כנרשם בפרטיות בהמפתח ע' לסה\"מ הנ\"ל). והנחה מהדרוש מיום א' דחה\"ש נרשמה ע\"י ר' הלל."],["2995","2","<b>וספרתם. . עומר התנופה</b>: אמור כג, טו."],["2996","3","<b>תספרו חמישים יום</b>: אמור שם, טז."],["2997","4","<b>העומר שנק' מנחה</b>: סוטה יד, א (במשנה)."],["2998","5","<b>דכל המנחות הם מחטים</b>: סוטה שם."],["2999","6","<b>שיש הפרש ביניהם</b>: סוטה שם."],["3000","7","<b>שבמנחת סוטה אינו נותן שמן ולבונה</b>: נשא ה, טו. ראה רש\"י שם. במדב\"ר פ\"ט, יג. תנחומא נשא ג."],["3001","8","<b>גבעת הלבונה</b>: שה\"ש ד, ו."],["3002","9","<b>שמנחת העומר היא גרש ומנחת סוטה היא קמח</b>: ראה סוטה שם."],["3003","10","<b>ברע\"מ פ' אמור. . בדיקו דאשת חיל</b>: ראה שם צז, א."],["3004","11","<b>ונקתה ונזרעה זרע</b>: נשא ה, כח."],["3005","12","<b>וצבתה בטנה</b>: נשא שם, כז."],["3006","13","<b>ה' מסיני בא. . החזיר את התורה</b>: ברכה לג, ב. ע\"ז ב, ב."]]],[4801940178,"מהר פארן מקום דירת ישמעאל<sup data-n=\"3007\">14</sup> כו' (... והגם שבפסוק אינו מבואר רק עשו וישמעאל הנה הם מקורי האומות<sup data-n=\"3008\">15</sup> כי<sup data-n=\"3009\">16</sup> ע' אומות ל\"ה מימין יונקים מקליפת ישמעאל כי הוא יונק מקו הימין כי אברהם יצא ממנו ישמעאל<sup data-n=\"3010\">17</sup> כו' ול\"ה משמאל יונקים מקליפת עשו כי הוא יונק מקו השמאל, כי יצחק יצא ממנו עשו, ובפסוק אינו מבואר רק המקורים של הע' אומות, אבל באמת החזיר על כל אומה ולשון בפרט<sup data-n=\"3011\">18</sup> (... ובזוהר פ' בלק דקצ\"ג ע\"א רומז<sup data-n=\"3012\">19</sup> בתיבת ואתא מרבבות קודש דקאי על כל הע' שרים<sup data-n=\"3013\">20</sup> כו'. ..) כי כולם צריכים לזה כמשי\"ת. ..), והנה מבואר<sup data-n=\"3014\">21</sup> בדרז\"ל אשר עשו לא רצה לקבל מחמת שכתוב בה לא תרצח<sup data-n=\"3015\">22</sup> כו' וברכתו היא על חרבך תחי'<sup data-n=\"3016\">23</sup> כי מזה כל מקור חיותו כו', וישמעאל לא רצה לקבל מצד שכתוב בה לא תנאף<sup data-n=\"3017\">24</sup> כו' וברכתו היא והפריתי אותו (בראשית י\"ז<sup data-n=\"3018\">25</sup> ) ומזה כל מקור חיותו כו' (... כנ\"ל שיונק מקו הימין מהפסולת הנבדל למטה ע\"י ריבוי השתלשלו' וזהו מקור תאוות הניאוף, ועשו יונק מקו השמאל שנסתעף ממנו פסולת למטה, וזהו מקור תאוות הרציחה כו'. ..).\n<b>והנה</b> לכאורה אינו מובן האיך רצה ליתן להם התו' הלא עיקר כל התומ\"צ היא באה לברר בירורים בבחי' עולם ובבחי' נפש כו' וידוע שאוה\"ע א\"א להם להתברר מצד עצמם כ\"א ע\"י ישראל<sup data-n=\"3019\">26</sup> כו' וכמבואר בדרז\"ל ע\"פ רבות עשית<sup data-n=\"3020\">27</sup> כו' שכהו עיני יצחק בכדי שיעקב יקבל הברכות כי כוונות יצחק הי' שעשו יתברר ע\"י הברכות שימשיך בו אורות עליונים (... כמארז\"ל מטל השמים זה מקרא<sup data-n=\"3021\">28</sup> ומשמני הארץ זה משנה כו'. ..), ועי\"ז יתעלה לשרשו (... כי זאת ידע שמצ\"ע כמו\"ש למטה הוא רשע כמבואר בדברי רש\"י ז\"ל<sup data-n=\"3022\">29</sup> שידע שאין ש\"ש<sup data-n=\"3023\">30</sup> שגור בפיו כו'), אך באמת אינו",[["3007","14","<b>משעיר. . עשו. . ישמעאל</b>: ראה מכילתא יתרו כ, ב. ספרי ברכה לג, ב הובא ברש\"י שם. זהר בלק קצב, ב."],["3008","15","<b>עשו וישמעאל. . מקורי האומות</b>: ראה אוה\"ח וניצוצי אורות לזהר רע\"מ פינחס רכז, ב. מאמרי אדה\"א שמות ח\"א ע' קעג. וש\"נ. שע\"ת צא, א ובהערה 6."],["3009","16","<b>כי</b>: תוקן ע\"פ ב."],["3010","17","<b>אברהם יצא ממנו ישמעאל</b>: ראה פסחים נו, א. מאמרי אדה\"א דברים ח\"ג ע' א'קטו ואילך. שע\"ת פה, ג ובהנסמן במ\"מ לשם."],["3011","18","<b>החזיר על כל אומה ולשון בפרט</b>: ראה ספר הערכים חב\"ד ח\"ב מערכת אומות העולם ע' תרנד הערה 658."],["3012","19","<b>דקצ\"ג ע\"א רומז</b>: ניתוסף ע\"פ ד."],["3013","20","<b>הע' שרים</b>: ראה זהר בראשית מו, סע\"ב. שע\"ת עד, א הערה 2."],["3014","21","<b>לזה כמשי\"ת) והנה מבואר</b>: ניתוסף ע\"פ ח. ובכת\"י זה הניח מקום פנוי. ומבואר."],["3015","22","<b>עשו. . לא תרצח</b>: יתרו כ, ג. בסה\"מ תרכ\"ו כאן ע' פח מציין לילקוט [עה\"פ ברכה לג, ב] וזהר [הנ\"ל קצב, ב]."],["3016","23","<b>על חרבך תחי'</b>: תולדות כז, מ [ושם: ועל — ראה תו\"ח בא ח\"א קיז, ג. וש\"נ]."],["3017","24","<b>וישמעאל. . לא תנאף</b>: יתרו כ, יג. ראה זהר שם."],["3018","25","<b>בראשית י\"ז</b>: פסוק כ."],["3019","26","<b>שאוה\"ע. . להתברר. . כ\"א ע\"י ישראל</b>: ראה תו\"א תולדות כ, ג. מאמרי אדה\"ז תקס\"ה ח\"א ע' כב (נוסחא שני') ואילך. ע' כג (נוסח א) ואילך. אוה\"ת תולדות קנד, ב ואילך. קנו, א-ב."],["3020","27","<b>רבות עשית</b>: תהלים מ, ו. תנחומא תולדות ח."],["3021","28","<b>מטל השמים זה מקרא</b>: תולדות כז, כח. ראה ב\"ר פס\"ו, ג."],["3022","29","<b>בדברי רש\"י ז\"ל</b>: ראה רש\"י תולדות כז, כא. ראה גם תו\"א שם כ, ב. מאמרי אדה\"ז תקס\"ה שם ע' יז."],["3023","30","<b>ש\"ש</b>: תוקן ע\"פ ב."]]],[4801940235,"יכול להתברר ע\"י יצחק (... וא\"כ אם הי' יצחק ממשיך בו תוס' אורות ע\"י הברכות הי' נפרד יותר<sup data-n=\"3024\">31</sup> כו'. ..) אך מוכרח להתברר ע\"י יעקב דוקא (... כי יעקב שרשו בת\"ת<sup data-n=\"3025\">32</sup> שהוא בקו האמצעי<sup data-n=\"3026\">33</sup> שבו מאיר מבחי' פנימי' חכ\"ע כמ\"ש נאדר בקודש<sup data-n=\"3027\">34</sup> כו' ובחכ' אתברירו<sup data-n=\"3028\">35</sup> כו'. ..) כאשר יקבל התורה אז יברר גם את הע' שרים ע\"י תומ\"צ, וא\"כ איך רצה הקב\"ה ליתן להם בעצמם התורה כו'. אך זה אפשר לתרץ כי דוקא ע\"י יצחק לא יוכלו להתברר אבל הקב\"ה בעצמו כאשר הי' נותן להם התורה היו יכולים להתברר<sup data-n=\"3029\">36</sup> כי כל יכול הוא (... ומטעם הנ\"ל כי ע\"י קו האמצעי שבו מאיר מפנימי' חכ\"ע והקב\"ה הוא בחי' עתיקא מקור פנימי' החכ\"ע ומקור קו האמצעי וק\"ו הוא שיוכלו להתברר ע\"י כו' וד\"ל. ..), וראי' ממ\"ש לע\"ל אז אהפוך אל עמים<sup data-n=\"3030\">37</sup> שפה ברורה כו' לעבדו שכם אחד וכמ\"ש והי' ה' למלך<sup data-n=\"3031\">38</sup> על כל הארץ אז יהי' ה' אחד ושמו אחד כו', אך הם לא רצו ליכלל בקדושה מצד שהוא היפוך החיות שלהם כנ\"ל, אך אעפ\"כ אינו מובן כי כל יכול ויכול לבררם שלא ברצונם כו', ועוד כי הוא יודע העתידות ויודע שלא ירצו לקבל, וא\"כ למה רצה ליתן להם התורה כו', אך באמת במה שרצה ליתן להם התורה המשיך בהם אור וחיות (... בבחי' מקיף כי הרצון הוא בחי' כתר<sup data-n=\"3032\">39</sup> מלשון כותרת ומקיף כו'. ..) ובזה נתן להם כח ועוז שיוכלו להתברר ע\"י ישראל כו' (... ואפ\"ל ע\"ד המבואר במ\"א בענין ברכה שלפני אכילה<sup data-n=\"3033\">40</sup> שעי\"ז נמשך בחי' מקיף על הניצוץ אלקי שבמאכל שיוכל להתברר ע\"י האכילה כו' וד\"ל. ..).\n<b>ובזה</b> יתורץ הכל כי מתחלה בעת שרצה ליתן להם ידע שלא יקבלו אותה רק פעל בהם כח ועוז שיוכלו להתברר ע\"י ישראל כו' (... והענין הוא כי אע\"פ שהי' יכול לבררם בע\"כ כו' הנה ידוע שפנימי' הרצון ועונג הנעלם הי' שיהי' הבירור לאהפכא חשיכא לנהורא<sup data-n=\"3034\">41</sup> ע\"י מעשה התחתונים דוקא, וא\"כ אם היו מתבררים ע\"י הקב\"ה בעצמו שלא ברצונם לא הי' נשלם פנימי' הרצון ועונג הנעלם כו', ולכן מוכרחים להתברר ע\"י ישראל דוקא שהם בבחי' הביטול דחכ\"ע<sup data-n=\"3035\">42</sup> כח מ\"ה<sup data-n=\"3036\">43</sup> ולכן הם מבררים ומהפכים חושך דעולם ונפש ע\"י כח הביטול שבהם ע\"י<sup data-n=\"3037\">44</sup> עצמם ואפי'",[["3024","31","<b>אם הי' יצחק. . נפרד יותר</b>: ראה תו\"א שם כ, ג. מאמרי אדה\"ז שם ע' כד (נוסחא שני')."],["3025","32","<b>יעקב שרשו בת\"ת</b>: ראה זהר ס\"ת ויצא קנז, ב. ח\"ג (תוספות) שב, א."],["3026","33","<b>בת\"ת שהוא בקו האמצעי</b>: ראה השמטות לזח\"א רנז, א."],["3027","34","<b>נאדר בקודש</b>: בשלח טו, יא. ראה גם לעיל ע' קכג."],["3028","35","<b>ובחכ' אתברירו</b>: ראה זהר היכלות פקודי רנד, סע\"ב. הנסמן במאמרי אדה\"א דברים ח\"א ע' רצה. שמות ח\"ב ע' שכא. תו\"ח תשא ח\"ב שפד, ד ואילך."],["3029","36","<b>אבל הקב\"ה. . יכולים להתברר</b>: ראה גם ביאוה\"ז להצ\"צ ח\"ב ע' תתקנ."],["3030","37","<b>אז אהפוך אל עמים</b>: צפני' ג, ט."],["3031","38","<b>והי' ה' למלך</b>: זכרי' יד, ט."],["3032","39","<b>הרצון. . כתר</b>: ראה פרדס שער עצמות וכלים ש\"ד, פ\"ח. שער הצחצחות שי\"א, פ\"ה. פ\"ו. אגה\"ק סכ\"ט. מאמרי אדה\"א הנחות תקע\"ז ע' עב. וש\"נ."],["3033","40","<b>ברכה שלפני אכילה</b>: ראה גם ביאוה\"ז עקב קכ, ד."],["3034","41","<b>לאהפכא חשיכא לנהורא</b>: ראה זהר בהקדמה ד, א. סה\"מ תרכ\"ט ע' פח ואילך. וש\"נ. מאמר ד\"ה זאת חוקת התורה ש\"פ פרה תשכ\"ו."],["3035","42","<b>דחכ\"ע</b>: בד: דחכ'."],["3036","43","<b>דחכ' כח מ\"ה</b>: זהר (רע\"מ) צו כח, א. לד, א."],["3037","44","<b>ע\"י</b>: בד: ליתא."]]],[4801940288,"החושך דאוה\"ע המה מבררים ע\"י שנתפזרו בהם בגלות וכמארז\"ל צדקה עשה הקב\"ה שפיזרם<sup data-n=\"3038\">45</sup> כו' ובזה נשלם פנימי' הרצון ועונג הנעלם שיהי' הבירור ע\"י מעשה התחתונים דוקא רק אעפ\"כ החזיר עליהם את התורה כדי להמשיך בהם כח ועוז שיוכלו להתברר ע\"י ישראל, וממילא יהי' בנקל יותר לישראל לבררם ולהפכם מחושך לאור כו' וד\"ל. ובזה יובן עומק כוונות הזוהר (שם קצ\"ב ב') שאמר שם<sup data-n=\"3039\">46</sup> שכוונת הקב\"ה במה שהחזיר עליהם התורה הוא לנקיא דמא בישא מדרועא שמאלא וימינא, ואח\"כ אמר שפעל הקב\"ה אצלם שהפרישו נהירו דחפיא עליהון ונתנו אותם לישראל כו'. וביאור הענין לפ\"ד בד\"א כי יש בבחי' הרע ב' בחי', הא' הטוב דנוגה הגנוז בי' דחפי' עליהן בבחי' מקיף והו\"ע הלבונה<sup data-n=\"3040\">47</sup> שבסממני הקטורת כו' והב' עצם הרע שלא יוכל להתברר רק נדחה למטה בנוק' דתה\"ר<sup data-n=\"3041\">48</sup> עד עת קץ שיבוער רוח הטומאה לגמרי כו' ואיבודם יהי' תיקונם כו', ובזה מובן כוונת הזוהר הנ\"ל שכשרצה הקב\"ה ליתן תורה לישראל שהם בבחי' קו האמצעי בכדי שיבררו גם שני הקוין כל הפסולת המסתעף משני הקוין שהוא קליפת עשו וישמעאל, וזה צ\"ל ע\"י שמתחלה ימשיכו בהם אור ואח\"כ מתבררים ונכללים בקדושה וראה דמא בישא בקו השמאל שהוא עצם הרע שלא יוכל להתברר ואם הי' נמשך עליו האור הי' מתחזק להתקיים בקיום נצחי (כענין פן ישלח ידו<sup data-n=\"3042\">49</sup> כו' ואכל וחי לעולם), לזאת ע\"י שהחזיר עליהם את התורה ולא רצו לקבל בזה נדחו למטה וממילא לא יאיר עליהם האור כלל רק הנהירו דחפי' עליהון שהו\"ע הניצוץ דנוגה זאת ניתן לישראל להתברר על ידם, וכאשר ימשיכו האור ע\"י תומ\"צ על הניצוץ הנ\"ל יתברר ויוכלל בקדושה כו' וד\"ל. ..).\n<b>והנה</b> להבין איכות ענין הבירור שמתבררים ע\"י ישראל, הנה שעיר הוא אדום<sup data-n=\"3043\">50</sup> תכלית האדמימות שהוא תוקף הגבורות<sup data-n=\"3044\">51</sup> קשות שנמשך בדרך נפילה מעולם התוהו שהוא בחי' גבורות דקדושה, וענין השפעה בדרך נפילה היינו כאשר השפע למטה היא בבחי' היפוך משרשו כמו מלך הראשון דתוהו שנק' בלע<sup data-n=\"3045\">52</sup> ע\"ש שהוא בחי' תוקף הביטול למקורו, ולכן נק' בשם בלע שהוא טרוד לבלוע<sup data-n=\"3046\">53</sup> כו' (... והוא בחי' הדעת דתוהו<sup data-n=\"3047\">54</sup> ויש מפרשים שהוא בחי' החסד דתוהו<sup data-n=\"3048\">55</sup> עיין",[["3038","45","<b>צדקה עשה הקב\"ה שפיזרם</b>: ראה פסחים פז, ב. ראה גם תו\"ח שמות ח\"א מ, ג ואילך ובהנסמן שם."],["3039","46","<b>שם</b>: ניתוסף ע\"פ בד."],["3040","47","<b>מקיף. . הלבונה</b>: ראה גם מאמרי אדה\"א שמות ח\"א ע' כה ואילך. וש\"נ. ש\"א ז, ב ובהערה 33."],["3041","48","<b>בנוק' דתה\"ר</b>: ראה זהר בהקדמה ה, א. יד, ב. בראשית מח, א. ועוד."],["3042","49","<b>פן ישלח ידו</b>: בראשית ג, כב."],["3043","50","<b>שעיר הוא אדום</b>: בסה\"מ תרכ\"ו כאן ע' פח: הוא שעיר אבי אדום — וראה וישלח לו, ח. ט. לב, ד."],["3044","51","<b>האדמימות. . הגבורות</b>: ראה פרדס שער הגוונים ש\"י, פ\"א. תו\"ח תרומה ח\"ב שו, סע\"ד. וש\"נ."],["3045","52","<b>מלך הראשון. . בלע</b>: וישלח לו, לב."],["3046","53","<b>בלע. . טרוד לבלוע</b>: ראה ביאוה\"ז להצ\"צ כאן ח\"ב ע' תתקנ. ע' תתקנב."],["3047","54","<b>בלע. . הדעת דתוהו</b>: ראה ע\"ח שער דרושי הנקודות ש\"ח, פ\"ד. תו\"ח שמות ח\"א מב, ב. וש\"נ."],["3048","55","<b>בלע. . החסד דתוהו</b>: עמק המלך שער עולם התהו ש\"ו, רפנ\"א. יל\"ר וישלח קרוב לסופו קמג, ב ד\"ה בסטרא דקדושה."]]],[4801940338,"בכהאריז\"ל. ..) ולמטה נעשה ממנו דבר המסתיר לגמרי כמו ותבלען<sup data-n=\"3049\">56</sup> כו' (... שז' פרות הרעות<sup data-n=\"3050\">57</sup> הם ז' מדות דקליפה ומקורם הוא הדעת דקליפה שנמשך בדרך נפילה מדעת בעולם התוהו ונעשה בחי' נפרד ולכן הם בולעים את הז' מדות דקדושה ומסתירים עליהם עד שאין ניכרים כלל<sup data-n=\"3051\">58</sup> כמו המתפעל בתפילה באה' אלקי' ואחר התפילה נופל בבחי' יש באהבת עצמו עד שאינו ניכר שהתפלל מעולם וזהו ולא נודע כי באו אל קרבנה<sup data-n=\"3052\">59</sup> כו'. ..), וכמו ע\"ד דוגמא פני ארי' אל הימין<sup data-n=\"3053\">60</sup> שהוא למעלה תכלית הקדושה ראשון שבמרכבה ולמטה נמשך ממנו חי' טמאה<sup data-n=\"3054\">61</sup> כו', או ע\"ד דוגמא כאשר שותה יין בישוב הדעת אז משמח היין אותו ויצא סוד הנעלם לידי גילוי ויכול להתגלות בו שרש נשמתו<sup data-n=\"3055\">62</sup> כמו שהיא ויכול לגלות רזין דאורייתא כענין אגברו חמרא אדרדקי<sup data-n=\"3056\">63</sup> כו' אך כששותים ריבוי יין שלא ע\"פ ישוב הדעת אז נעשה ממנו יין המשכר ריבוי פסולת להסתיר לגמרי על האור האלקי<sup data-n=\"3057\">64</sup>, וכן ע\"ד דוגמא מזיעתן של חיות הקודש שנמשך מאה' האלקי' שלהם כאשר היא ברשפי אש בתגבורת (מצד הגבורות הנכללים בחסדים) ואח\"כ נעשה<sup data-n=\"3058\">66</sup> מזה נהר דינור<sup data-n=\"3059\">65</sup> שהוא תוקף גבורות קשות שעל ראש רשעים יחול<sup data-n=\"3060\">67</sup> כו', והנה שפע זאת הנמשך בדרך נפילה מז\"מ דעולם התוהו כאשר מתבררים ועולים לשרשם אז ממשיכים אורות דתוהו (... כי האורות עלו לשרשם רק ניצוצות נפלו, ולכן כאשר מתברר הניצוץ אז עולה לשרשו ומעורר את האור שיומשך למטה כו'. ..), ומתלבשים בכלים דתיקון כו' (... כי נעשה ונמשך ריבוי האורות בריבוי הכלים התכללות תוהו ותיקון עגולים ויושר<sup data-n=\"3061\">68</sup>, וזהו יהללו שמו במחול<sup data-n=\"3062\">69</sup> וממילא נשלם הכוונה להיות לו דירה בתחתונים כו' וד\"ל. ..). וממילא מצד תוס' אורות שנמשכים למעלה בעולם האצילו' שהוא עולם התיקון נמשך ג\"כ למטה תוס' קדושה על נפש האדם (... ולכן אומרים אשר קדשנו במצותיו<sup data-n=\"3063\">70</sup> כי כל זה נעשה ע\"י התומ\"צ כמשי\"ת. ..), (כמו מרציחה נעשה מוהל וטבח",[["3049","56","<b>ותבלען</b>: לשון הפסוק מקץ מא, כד. ראה גם תו\"א תצוה קי, ד. תו\"ח שמות שם הערה 247."],["3050","57","<b>שז' פרות הרעות</b>: ראה מאמרי אדה\"א דברים ח\"ד ע' א'ריג. וש\"נ. תו\"ח מקץ רטו, ג ובהערה 33. ש\"א ד, א."],["3051","58","<b>כלל</b>: בכת\"י זה ניתוסף למעלה מן השורה בכת\"י אחר: וזה נבלע ישראל בגוים [הושע ח, ח — בדילוג] נבלעים ברע. וראה הנרשם אודות הוספות אלו ברשימת הכת\"י כאן."],["3052","59","<b>ולא נודע. . אל קרבנה</b>: מקץ מא, כא."],["3053","60","<b>פני ארי' אל הימין</b>: ראה יחזקאל א, י."],["3054","61","<b>ארי'. . הקדושה. . חי' טמאה</b>: ראה אוה\"ח אחרי יז, ד ד\"ה ונראה. ראה גם תו\"ח וארא ח\"א נו, ב. וש\"נ. סה\"מ תרכ\"ז ע' נ. וש\"נ."],["3055","62","<b>נשמתו</b>: בכת\"י זה ניתוסף עה\"ג בכת\"י אחר: כמ\"ש [ס' שופטים ט, יג] החדלתי את תירושי המשמח אלקים ואנשים ונקרא יין המשמח ויין בגימטריא סוד משנכנס יין יצא סוד [ערובין סה, סע\"א. ראה גם תו\"ח ויחי רלו. ב]. וראה הנרשם אודות הוספות אלו ברשימת הכת\"י כאן."],["3056","63","<b>אגברו חמרא אדרדקי</b>: סנהדרין לח, א."],["3057","64","<b>אלקי</b>: בכת\"י זה ניתוסף בין השיטין בכת\"י אחר: ולכן נאמר ביין [ראה נח ט, כא] וישת וישכר ויתגל. . לשון. . . וראה הנרשם אודות הוספות אלו ברשימת הכת\"י כאן."],["3058","66","<b>נעשה</b>: ניתוסף ע\"פ בד."],["3059","65","<b>מזיעתן של חיות. . נהר דינור</b>: ראה חגיגה יג, סע\"ב."],["3060","67","<b>שעל ראש רשעים יחול</b>: ירמי' כג, יט. ל, כג."],["3061","68","<b>תוהו ותיקון עגולים ויושר</b>: ראה גם לקמן מאמר ד\"ה והניף הכהן תקפ\"ו ובהערה 52."],["3062","69","<b>יהללו שמו במחול</b>: תהלים קמט, יג. ראה גם סידור שחרית סח, ד."],["3063","70","<b>אשר קדשנו במצותיו</b>: נוסח ברכת המצות."]]],[4801940385,"ומקיים מצות מילה ומצות שחיטה שממשיך בו קדושה כמארז\"ל האי דבמאדים כו'<sup data-n=\"3064\">71</sup> וכן מקליפת פארן שהוא תאוות הניאוף כנ\"ל נמשך פרי' ורבי' שמקדש אותו בתכלית כי נעשה דוגמת שם הוי' כי אב ואם הוא בחי' י\"ה ובן ובת הוא בחי' ו\"ה<sup data-n=\"3065\">72</sup> וכן עונג שבת אפי' שאוכל לתאבון<sup data-n=\"3066\">73</sup> כאשר כוונתו לענג בזה את השבת ממשיך בזה תוס' קדושה על נפש האדם<sup data-n=\"3067\">74</sup> ).\n<b>והנה</b> הבירור והעלי' לשרשו הוא ע\"י התורה דוקא והטעם לזה כי הנה כל ההשתל' הוא ע\"י שם אלקים כו' כמ\"ש בראשית ברא אלקים<sup data-n=\"3068\">75</sup> ואפי' עולמות היותר עליוני' שהם ג' מיני אדם<sup data-n=\"3069\">76</sup> א\"ק אדם דבריאה כו' הוא ג\"כ נמשך ע\"י צמצום ומקו\"פ, שהוא בחי' אלקים כו', אך ע\"י התורה ממשיך בחי' הוי' באלקים שהו\"ע גילוי אור עצמותו כמו\"ש ממשיך אותו למטה (... ושם אלקים אינו מסתיר כלל אדרבה מצמצמו ומגבילו שיתקבל כמו שהוא במקבל כמו ע\"ד צמצם שכינתו בין שני בדי ארון<sup data-n=\"3070\">77</sup> שאינו צמצום המסתיר רק מגביל כל העצמות להיות נמצא שם כו' וד\"ל. וזהו ענין המשכת הוי' בבחי' אלקי' ונק' יחוד הוי' ואלקים משא\"כ כאשר מסתיר לאור הוי' שזהו\"ע ההשתל' נק' המשכה משם אלקים בלבד, שהגם שהשפע נמשך משם הוי' מ\"מ כיון שנמשך רק הארה בעלמא ממנו לכן שם אלקים מסתיר אותו ואינו נגלה רק שם אלקים בלבד כו'. ..), וזהו ביום עשות ה' אלקים<sup data-n=\"3071\">78</sup> כו' (... כי בתחלת הבריאה נברא העולם בתכלית השלימות ע\"ד שיהי' לע\"ל והי' שם הוי' בבחי' גילוי בשם אלקים בלי הסתר כלל כנ\"ל רק שנתקלקל ע\"י חטא עה\"ד וניתקן ע\"י מ\"ת<sup data-n=\"3072\">79</sup> כמשי\"ת. ..)<sup data-n=\"3073\">80</sup>. וזה הי' ג\"כ בשעת מ\"ת שנמשך שם הוי' בשם אלקים בבחי' גילוי כמו שהוא כמארז\"ל ביטל את הגזירה<sup data-n=\"3074\">81</sup> שמתחלה גזר שלא ילכו מרומי לסוריא, רומי היינו השמים שמים לה' שעולה בעילוי אחר עילוי וממילא נעשה צמצום והסתר עד שנעשה והארץ נתן לבני אדם<sup data-n=\"3075\">82</sup> ירידה אחר ירידה להוות בבחי' נפרד שזהו סוריא כו', וזהו ענין ההשתל' שנמשך ע\"י שם אלקים כו' אך אח\"כ",[["3064","71","<b>האי דבמאדים כו'</b>: שבת קנו, א. בכת\"י זה ניתוסף בין השיטין בכת\"י אחר: יהי גבר אשיד דמא טבחא או מוהילא. והוא המשך הגמרא שם. וראה הנרשם אודות הוספות אלו ברשימת הכת\"י כאן."],["3065","72","<b>אב ואם. . י\"ה ובן ובת. . ו\"ה</b>: ראה זהר ויקרא יא, ב. רע\"מ צו לד, א. ת\"ז תנ\"ה פח, א. תנ\"ו פט, ב."],["3066","73","<b>עונג שבת. . לתאבון</b>: ראה מאמרי אדה\"א דברים ח\"ב ע' תקעו. וש\"נ. קונטרסים ע' רמב. וש\"נ. תו\"ח בשלח ח\"א רי, ד. וש\"נ."],["3067","74","<b>על נפש האדם</b>: ניתוסף ע\"פ בד."],["3068","75","<b>בראשית ברא אלקים</b>: בראשית א, א."],["3069","76","<b>ג' מיני אדם</b>: ראה מאמרי אדה\"ז על ענינים בתחילתו ובהנסמן במ\"מ לשם. אוה\"ת על ענינים ע' עז. סה\"מ תש\"ח ע' 113 בהערה. הנסמן בסה\"מ תרל\"ב ח\"א ע' ד."],["3070","77","<b>צמצם שכינתו. . ארון</b>: ראה ב\"ר פ\"ד, ד. מאמרי אדה\"ז תקס\"ג ח\"א ס\"ע שמו ואילך (נו\"א). לקו\"ת אמור לד, ב. הנסמן במאמרי אדה\"א בראשית ע' קכט. שה\"א ז, א ובהערה 12. לקמן מאמר ד\"ה והתהלכתי בתוככם תר\"ב על יד הערה 18."],["3071","78","<b>ביום עשות ה' אלקים</b>: בראשית ב, ד."],["3072","79","<b>כנ\"ל. . מ\"ת כמשי\"ת. ..)</b>: ב: כנ\"ל)."],["3073","80","<b>כמשי\"ת. ..)</b>: ניתוסף ע\"פ דח."],["3074","81","<b>ביטל את הגזירה</b>: ראה תנחומא וארא טו. שמו\"ר פי\"ב, ג. בילקוט המכירי תהלים קטו, כא מביא את זה מסנהדרין פרק חלק (קג, ב). וכנראה שזהו טעות המעתיק שם שערבב שני מאמרים."],["3075","82","<b>השמים שמים. . לבני אדם</b>: תהלים קטו, טז."]]],[4801940429,"בשעת מ\"ת ביטל את הגזירה ונעשה יחוד הוי' ואלקי' בשני אופנים, א' בדרך המשכה מלמעלמ\"ט שעצם המשפיע נגלה במקבל והיחוד נעשה במקום המקבל ע\"ד וירד ה' על הר סיני<sup data-n=\"3076\">83</sup> כו' והב' בדרך העלאה ממטה למעלה שהמקבל עולה למקום המשפיע וע\"ד משה עלה למרום<sup data-n=\"3077\">84</sup> שהיחוד נעשה במקום המשפיע כו' וד\"ל.\n<b>והנה</b> המשכה זאת ויחוד זה שנעשה ע\"י התורה נעשה ע\"י הבירור שמתחלה שהוא היפוך החשך לאור ומיש לאין שהוא ג\"כ ע\"י התורה כי היש נמשך מבחי' הגבורות דשם אלקים כנ\"ל, והתורה נק' תורת חסד<sup data-n=\"3078\">85</sup> להיותה ממשיך חסדים לזאת נמתקים הגבורות וניכללים בחסדים הנמשכים ע\"י תומ\"צ, וזהו לא לתוהו בראה<sup data-n=\"3079\">86</sup> כבן עזאי תוקף הרצוא<sup data-n=\"3080\">87</sup> בעילוי אחר עילוי (... וא\"כ אין גילוי למטה. ..) רק לשבת יצרה בחי' שוב דוקא (... שהוא ההתגלות למטה ע\"י יחוד הוי' ואלקים כנ\"ל. ..), שזהו ע\"י תומ\"צ כנ\"ל וד\"ל. וזהו ה' מסיני בא ליתן התורה לישראל (... ומחמת שישראל קיבלו בחשק ורצון גמור את התורה והקדימו נעשה לנשמע<sup data-n=\"3081\">88</sup> והם לא קיבלו ממילא ירדה שנאה לאוה\"ע<sup data-n=\"3082\">89</sup> ונדחה הרע שבהם למטה וממילא יוכל הניצוץ אלקי המקיף עליהם שהוא נהירו דחפיא הנז' בזוהר כנ\"ל להתברר ולעלות לשרשו ע\"י עסק התומ\"צ דישראל כו' וד\"ל. ..) ואז אח\"כ וזרח משעיר כו' הופיע מהר פארן שמתבררי' ע\"י ישראל כו'.\n<b>ובכל</b> הנ\"ל יובן ענין הבאת עומר שעורים<sup data-n=\"3083\">90</sup> וספיה\"ע שנעשה מקודם למ\"ת כו' כי הנה העומר נק' עומר התנופה<sup data-n=\"3084\">91</sup> שצריך להניף אותו כמ\"ש והניף את העומר<sup data-n=\"3085\">92</sup> כו'. והוא ע\"ד הזהב המתנדב למשכן שנק' זהב התנופה<sup data-n=\"3086\">93</sup> כי זהב הוא בחי' גבורה<sup data-n=\"3087\">94</sup> כמ\"ש מצפון זהב יאתה<sup data-n=\"3088\">95</sup> וכאשר הגבורות נופלים למטה נמשך מהם בחי' רע כמ\"ש מצפון תפתח הרעה<sup data-n=\"3089\">96</sup> כו'<sup data-n=\"3090\">97</sup>, ולכן ע\"י הזהב המתנדב לנדבת המשכן נתרוממו הגבורות לשרשן ונמתקו שם כו' ולכן נק' זהב התנופה כו'. וכן הוא עד\"ז הו\"ע עומר שעורים הוא מאכל בהמה<sup data-n=\"3091\">98</sup> בירור נה\"ט ביטול רצון הנעשה ע\"י תנופת",[["3076","83","<b>וירד ה' על הר סיני</b>: יתרו יט, כ."],["3077","84","<b>משה עלה למרום</b>: ב\"מ פו, ב. שבת פח, ב."],["3078","85","<b>תורת חסד</b>: ראה משלי לא, כו. מאמרי אדה\"א דברים ח\"ד ע' א'תטו. וש\"נ. תו\"ח בשלח ח\"א רמד, ג. וש\"נ."],["3079","86","<b>לא לתוהו בראה</b>: ישעי' מה, יח [ושם: תהו — ראה מאמרי אדה\"א ויקרא ח\"א ע' שעו. דברים ח\"ד ע' א'רט. קונטרסים ע' רנה ובהנסמן בהנ\"ל]. ראה גם מאמרי אדה\"א שמות ח\"א ע' קלה. וש\"נ."],["3080","87","<b>כבן עזאי תוקף הרצוא</b>: ראה גם מאמרי אדה\"א קונטרסים שם ובהנסמן שם."],["3081","88","<b>והקדימו נעשה לנשמע</b>: משפטים כד, ז."],["3082","89","<b>ירדה שנאה לאוה\"ע</b>: שבת פט, א."],["3083","90","<b>עומר שעורים</b>: מנחות מח, ב. תו\"כ ויקרא ב, יד."],["3084","91","<b>עומר התנופה</b>: אמור כג, טו."],["3085","92","<b>והניף את העומר</b>: אמור שם, יא."],["3086","93","<b>זהב התנופה</b>: פקודי לח, כד."],["3087","94","<b>זהב הוא בחי' גבורה</b>: ת\"ז תכ\"ד סט, ב. ראה ש\"א מה, ב הערה 25."],["3088","95","<b>מצפון זהב יאתה</b>: איוב לז, כב."],["3089","96","<b>מצפון תפתח הרעה</b>: ירמי' א, יד."],["3090","97","<b>כו'</b>: בכת\"י זה ניתוסף עה\"ג בכת\"י אחר: ולכן יש עושר שמור לרעתו [קהלת ה, יב] וכמארז\"ל הני עתירי דבבל מערב רב קאתי ר\"ל שיש בהם רע מצד הגבורות (שנפלו בדרך נפילה. וראה הנרשם אודות הוספות אלו ברשימת הכת\"י כאן."],["3091","98","<b>שעורים הוא מאכל בהמה</b>: ראה מל\"א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."]]],[4801940469,"העומר וממילא נמתקים הגבורות בשרשם כי שעורה הוא בשי\"ן שמאלית שהוא בחי' גבורות<sup data-n=\"3092\">99</sup> כו' וע\"י התנופה של העומר שעורים מתעלים הגבורות להמתיק בשרשם כו', ולכן נק' עומר התנופה כו', ואח\"כ נעשה מיתוק שני שהוא מה שנמתקים בחסדים וזהו ע\"י ספיה\"ע שהם מ\"ד יום שמז' ש\"פ עד מ\"ת שהוא בחי' דם נעכר ונעשה חלב<sup data-n=\"3093\">101</sup> שמתהפכים הגבורות לחסדים (... וה' ימים<sup data-n=\"3094\">100</sup> שמתחלה עד ז' ש\"פ היינו המשכת החסדים עצמם שהם בחי' ה' חסדים בכדי להמתיק הגבו' כו' וד\"ל. ..), ונמצא שע\"י תנופת העומר שהוא פועל בחי' ביטול רצון בכלל בבחי' נה\"ט נעשה מיתוק הגבורות בשרשן וע\"י ספיה\"ע שהוא בירור המדות דנה\"ט בפרט כו' (... ובפרטי פרטיות כי כל מדה כלולה מכל ז' המדות ולכן מצוה למימני יומי ומצוה למימני שבועי<sup data-n=\"3095\">102</sup> כו'. ..) נעשה מיתוק שני שהוא המתקת הגבו' בחסדים כי כאשר פועל בנפשו בכל לבבך<sup data-n=\"3096\">103</sup> בשני יצרך<sup data-n=\"3097\">104</sup> שגם היצה\"ר מדות דנה\"ט נכללים ביצ\"ט מדות דנה\"א ומתהפכי' גם המה לאהבת ה' כמו הנה\"א אז נפעל למעלה המתקת הגבו' בחסדים כי למעלה אינו רע רק בחי' גבורות כי אין רע יורד<sup data-n=\"3098\">105</sup> כו' רק ע\"י ריבוי השתל' נסתעף בחי' רע מקו השמאל (ולכן אופן א' בארץ תרגומו מלרע<sup data-n=\"3099\">106</sup> כו') לכן כאשר מתהפך הרע לטוב למטה נעשה למעלה התכללות הגבורות בחסדים (... ושני ההמתקות צריכים להיות כי ע\"י המתקת הגבורות בשרשם נבדלו הגבורות הקשות שלא יוכלו להתמתק כמשי\"ת ואז אח\"כ יוכלו הגבורות להתמתק בחסדים כו'. ..).\n<b>וזהו</b> ההפרש בין שעורה בשין שמאלי שהוא בחי' גבורות שיכולים להיות נמתקים בחסדים (... כי השי\"ן יש בו ג' קוין (וקו<sup data-n=\"3100\">107</sup> הימין הוא בחי' החסדים וקו השמאל הוא בחי' גבורות הנכללים בחסדים ע\"י קו האמצעי וד\"ל. ..) ובין סער בסמ\"ך שהוא בחי' גבורות קשות<sup data-n=\"3101\">108</sup> שאינם יכולים להתמתק בחסדים והו\"ע והלך בסערות תימן<sup data-n=\"3102\">109</sup> וכן ענין רוח סערה<sup data-n=\"3103\">110</sup> כו', וזהו הנה סערת ה'<sup data-n=\"3104\">111</sup> חמה יצא וסער מתחולל על ראש רשעים כו' רח\"ל, וההפרש בין גבורות קשות ובין גבורות הנמתקים כו' כי גבורות קשות הוא ע\"ד שלוחי הדין שכוונתם לפעול רע בלבד כו'",[["3092","99","<b>שעורה הוא בשי\"ן שמאלית. . גבורות</b>: ראה לקו\"ת במדבר י, ב. סידור שער חה\"ש שז, א. אוה\"ת אמור ע' קנט וע' קסד. ביאוה\"ז להצ\"צ ח\"ב כאן ע' תתקלא. ע' תתקמה. ע' תתקמז. סה\"מ תרכ\"ו כאן ע' צ ואילך."],["3093","101","<b>דם נעכר ונעשה חלב</b>: נדה ט, א."],["3094","100","<b>מ\"ד יום. . וה' ימים</b>: ראה גם מאמרי אדה\"א במדבר ח\"ב ע' תפג ואילך."],["3095","102","<b>מצוה למימני יומי ומצוה למימני שבועי</b>: מנחות סו, א. ראה גם פלח הרמון יתרו ע' רמה."],["3096","103","<b>בכל לבבך</b>: תוקן ע\"פ ד. ובכת\"י זה בכל מאדך."],["3097","104","<b>בכל לבבך בשני יצרך</b>: ואתחנן ו, ה ובספרי שם. ברכות נד, א במשנה. ראה מאמרי אדה\"א בראשית ע' שסג ואילך. שערי אורה ו, א הערה 9."],["3098","105","<b>אין רע יורד</b>: ראה ב\"ר פנ\"א, ג. ספר ארבע מאות שקל כסף בסופו (רפב, א). תו\"ח וארא ח\"א נח, ד הערה 29."],["3099","106","<b>אופן א' בארץ תרגומו מלרע</b>: יחזקאל א, טו [ושם: כמלרע — ראה בחיי בראשית א, כא בסופו. לקו\"ת האזינו עז, א]."],["3100","107","<b>(וקו</b>: ב: וקו."],["3101","108","<b>סער בסמ\"ך. . גבורות קשות</b>: ירמי' ל, כג. ראה גם ביאוה\"ז וסה\"מ שבהערה 99."],["3102","109","<b>והלך בסערות תימן</b>: זכרי' ט, יד."],["3103","110","<b>רוח סערה</b>: יחזקאל א, ד. תהלים קז, כה. קמח, ח."],["3104","111","<b>הנה סערת ה'</b>: ירמי' כג, יט."]]],[4801940504,"משא\"כ הדן דין אמת הוא ג\"כ בחי' גבורות רק כוונתו בשביל התיקון כמ\"ש ונקלה אחיך לעיניך<sup data-n=\"3105\">112</sup> כיון שנקלה אחיך הוא כי נתקן ע\"י הדין שדנו אותו וכן יראת חטא היראה הוא מן החטא עצמו כי הוא מפריד מבחי' החיות אלקי, משא\"כ מן העונש של החטא אין שייך יראה כי הוא באמת תיקון הנפש כו'.\n<b>והנה</b> בכל הנ\"ל יובן מש\"א ברע\"מ דתנופת העומר הוא בדיקו דאשת חיל היינו שעי\"ז נבדל מכנ\"י שנק' אשת חיל דקות הרע, כי ע\"י ביטול רצון דנה\"ט לה' (שזהו\"ע תנופת העומר כנ\"ל) נעשים קלות דומות עליו כחמורות כמו הכועס כאילו עובד ע\"ז<sup data-n=\"3106\">113</sup> כו' והמלבין פני חבירו ברבים כאילו שופך דמים<sup data-n=\"3107\">114</sup>, וכן משארז\"ל נואף אשה חסר לב<sup data-n=\"3108\">115</sup> זה הלומד תורה לפרקים כו', וע\"פ פשוט כי התורה צ\"ל כמו אשתו שדר עמה בקביעות, משא\"כ הנואף שאינו דר בקביעות, לכן כאשר לומד התורה לפרקים נק' נואף אשה כו' (... כי עצם הנשמה משפיע לתורה והתורה היא בחי' מקבל מעצם הנשמה, ולכן נק' אשה כמ\"ש מורשה א\"ת מורשה אלא מאורסה<sup data-n=\"3109\">116</sup> כו'. ..), אך באמת הכוונה בתיבת לפרקים היינו כמ\"ש ולא יזח החושן כו' ותרגומו ולא יתפרק<sup data-n=\"3110\">117</sup> כו' וכ\"ה כאן שכאשר מפרק ומפריד התורה מן הקב\"ה מצד שלומד שלא לשמה נק' נואף אשה ואז הוא חסר לב שחסר לב<sup data-n=\"3111\">118</sup> ל\"ב נתיבות דחכמה<sup data-n=\"3112\">119</sup> עילאה שממשיכים בחי' ביטול, משא\"כ כאשר לומד לשמה לקשר נפשו בה' ע\"י התורה ועי\"ז נעשה תלת קשרין<sup data-n=\"3113\">120</sup> (... כי מתחלה נעשה בחי' מקבל מן התורה כי הוא מקשר נפשו לה' ע\"י התורה כו' אך אח\"כ מתעלה להיות בבחי' משפיע לתורה כו' ואז התורה נק' אשה שדר עמה בקביעות כו' וד\"ל. ..), והנה כ\"ז הוא בדיקו דא\"ח שכאשר מפריד ממנה דקות הרע אז ממילא גסות הרע אין לו יניקה מקדושה וממילא מתבטל לגמרי וזהו סמא דמותא לאשת זנונים כו' וד\"ל)<sup data-n=\"3114\">121</sup>. והנה אחר שנעשה שלימות הבירור בכל ז' המדות בפרט אחר ביטול הרצון בכלל שהוא תנופת העומר וספיה\"ע אז נמשך הגילוי דמ\"ת שהוא ע\"י שער הנו\"ן הממשיך בחי' אמיתת העצמות למטה [... כי כאשר נכללי' הגבורות בחסדים ע\"י ספה\"ע ממילא נעשה תגבורת החסדים לגלות אמיתת העצמות<sup data-n=\"3115\">122</sup> כמ\"ש למטה דוקא כו'. ..) וזהו כי גבר עלינו חסדו<sup data-n=\"3116\">123</sup> ע\"י ספה\"ע אז ואמת ה' לעולם שזהו\"ע התורה שנק' אמת<sup data-n=\"3117\">124</sup> שמתגלה",[["3105","112","<b>ונקלה אחיך לעיניך</b>: תצא כה, ג. ראה מגילה ז, ב. מאמרי אדה\"א קונטרסים ע' רטו. וש\"נ. הנחות תקע\"ז ע' שצג. וש\"נ."],["3106","113","<b>הכועס כאילו עובד ע\"ז</b>: ראה שו\"ע אדה\"ז חאו\"ח סקנ\"ו, ס\"ג. מאמרי אדה\"א דברים ח\"ב ע' שצג. וש\"נ."],["3107","114","<b>והמלבין. . כאילו שופך דמים</b>: ב\"מ נח, ב."],["3108","115","<b>נואף אשה חסר לב</b>: משלי ו, לב. סנהדרין צט, ב."],["3109","116","<b>מורשה א\"ת מורשה אלא מאורסה</b>: ברכה לג, ד. ברכות נז, א."],["3110","117","<b>ולא יזח החושן. . ולא יתפרק</b>: תצוה כח, כח ובת\"א שם."],["3111","118","<b>לב</b>: ב: ליתא."],["3112","119","<b>לב. . ל\"ב נתיבות דחכמה</b>: ראה גם מאמרי אדה\"א שמות ח\"ב ע' תמב ואילך. וש\"נ."],["3113","120","<b>תלת קשרין</b>: ראה זהר אחרי עג, א. הנסמן במאמרי אדה\"א קונטרסים ע' שלט."],["3114","121","<b>וד\"ל)</b>: ד: וד\"ל."],["3115","122","<b>למטה [... כי. . אמיתת העצמות</b>: ניתוסף ע\"פ ד."],["3116","123","<b>כי גבר עלינו חסדו</b>: תהלים קיז. ב."],["3117","124","<b>התורה שנק' אמת</b>: מלאכי ב, ו."]]],[4801940536,"למטה בבחי' עולם כו' וד\"ל, וזהו תספרו חמישים יום כי יום החמישים הוא<sup data-n=\"3118\">125</sup> הממשיך התגלות אמיתת העצמות ממילא נמשך ע\"י המ\"ט ימים ומים<sup data-n=\"3119\">126</sup> הממתיקים את הגבורות בחסדים כנ\"ל, וזהו ולאן אתה הולך<sup data-n=\"3120\">127</sup> שירידת הנשמה בגוף הוא בשביל קיום התורה שנק' ן, התגלות הא' דאנכי שהוא בחי' אמיתת העצמות הנק' אנכי כו' בבחי' הן' פשוטה שהוא יום החמישים כו' וד\"ל.",[["3118","125","<b>הוא</b>: ניתוסף ע\"פ ב."],["3119","126","<b>ומים</b>: ב: ליתא."],["3120","127","<b>ולאן אתה הולך</b>: אבות פ\"ג, מ\"א."]]],[4801940115,"<b>וספרתם</b> לכם<sup data-n=\"3121\">1</sup> ממחרת השבת<sup data-n=\"3122\">2</sup> מיום הביאכם את עומר התנופה שבע שבתות תמימות תהיין עד ממחרת השבת השביעית תספרו חמשים יום. להבין מש\"א תספרו חמשים יום והלא אינם סופרים אלא מ\"ט יום וכמ\"ש שבעה שבועות תספר לך כו' ואח\"כ ועשית חג שבועות<sup data-n=\"3123\">3</sup> כו' שמחוייבים לעשות אותו לקדש אותו באיסור עשיית מלאכה ולהקריב בו קרבנות אבל א\"צ לסופרו כו'. גם להבין מש\"א היום יום אחד<sup data-n=\"3124\">4</sup> היום שני ימים והל\"ל יום ראשון<sup data-n=\"3125\">5</sup> יום שני כו', וכן במנין השבועות א' שהם שבוע אחד כו' שהם שני שבועות והל\"ל שהם שבוע ראשון שהם שבוע שני כו'. גם צ\"ל למה נק' החג הזה בשם חג שבועות בפ' ראה וגם בפ' פנחס א' בשבועותיכם<sup data-n=\"3126\">6</sup>, הרי הוא אחר השבעה שבועות כמ\"ש ממחרת השבת השביעית ולמה יקרא ע\"ש הימים שלפניו שכבר חלפו ועברו כו'. גם להבין תיבת לכם שלכאורה היא מיותרת כו'. הנה יש להקדים בתחילה בכלל ענין הספירה שצריכה להיות דייקא מראשית קציר שעורים שהוא זמן הבאת מנחת העומר שהיא בט\"ז בניסן עד זמן ראשית קציר חטים שהוא הבאת שתי הלחם בחג השבועות כו', וצריך לספור מ\"ט יום. והענין הוא כי הלחם הוא המחי' ובשרשו ברוחני' הוא בחי' האותיות שהם ג\"כ הממשיכים החיות מהעלם אל הגילוי ויש ב' מיני אותיות בד\"כ הא' בחי' האותיות שהמה מקור החיות דהשתלשלות והוא האותיות דבהבראם בה' בראם<sup data-n=\"3127\">7</sup> כי מקור כל האותיות דהשתלשלות היא אות ה' אתא קלילא<sup data-n=\"3128\">8</sup> דלית בה מששא ונק' אותיות אלו",[["3121","1","<b>וספרתם לכם</b>: הנחת ר' הלל מדרוש כ\"ק אדמו\"ר הצ\"צ.\nלמאמר זה ראה לקו\"ת במדבר י, א. יא, ב. סידור שער חה\"ש שז, ג. שט, א. מאמרי אדה\"א במדבר ח\"ב ע' שצו ואילך. וש\"נ. ע' תתלד ואילך.\nראה עוד ע\"ד המאמר לקמן ברשימת הכת\"י."],["3122","2","<b>וספרתם לכם ממחרת השבת</b>: אמור כג, טו."],["3123","3","<b>שבעה שבועות. . ועשית חג שבועות</b>: פ' ראה טז, ט. י."],["3124","4","<b>מש\"א היום יום אחד</b>: בסדר ספירת העומר."],["3125","5","<b>יום ראשון</b>: תיבת ראשון ניתוספה עה\"ג. ואולי לפני זה כתוב יום."],["3126","6","<b>בפ' פנחס א' בשבועותיכם</b>: שם כח, כו."],["3127","7","<b>דבהבראם בה' בראם</b>: ראה מנחות כט, ב. ב\"ר פי\"ב, ב."],["3128","8","<b>ה' אתא קלילא</b>: ראה לקו\"ת האזינו עד, ד: והה' הוא אות קלילא דלית בי' מששא כמבואר באקדמות. תו\"ח ח\"ש קכא, ג ובהערה 48."]]],[4801940179,"שעורה שעור ה'<sup data-n=\"3129\">9</sup> להיותם באים במדה ושיעור מבחי' ה' כו' כמשי\"ת, וזהו בחי' מאכל בהמה<sup data-n=\"3130\">10</sup> [... כי בהמה הוא בחי' שם ב\"ן<sup data-n=\"3131\">11</sup> דמל' המסתתר בעולם הבריאה שהוא בגדר בחי' חי לגבי עולם האצי' שנק' מדבר<sup data-n=\"3132\">12</sup> כו'] וצי\"א<sup data-n=\"3133\">13</sup> אלו שנמשכים מבחי' ה' עילאה שהוא בחי' המל' דאצי' שנק' ה' עילאה לגבי המל' המלובש בבי\"ע הם בחי' מוחין וחיות לבחי' המל' המוסתר בבי\"ע להיותם ממשיכים אורות האצי' מהעלמם<sup data-n=\"3134\">14</sup> לבוא בבחי' גילוי אור במל' שמוסתרת בבי\"ע ולכן נק' בשם מאכל כמשל המזון שהוא מחי' כו', אך כ\"ז הוא בחי' האותיות דהשתלשלות אבל בחי' הב' באותיות נק' בשם חטה בגי' כ\"ב<sup data-n=\"3135\">15</sup> שהוא בחי' כ\"ב אתוון דאורייתא<sup data-n=\"3136\">16</sup> שלמעלה מהשתלשלות והוא בחי' מאכל<sup data-n=\"3137\">17</sup> אדם להיותו מזון וחיות לנשמות ששרשם בבחי' אדם העליון דאצי' עצמו שנק' בשם מדבר כו', ולכן נאמר על הנשמות דייקא אדם אתם<sup data-n=\"3138\">18</sup>, ובחי' אותיות התורה המה ממשיכים תוס' אורות ומוחין מעצמי' המאציל שהוא בבחי' כי לא אדם<sup data-n=\"3139\">19</sup> לבחי' אדה\"ע דאצי' ולכן נק' בשם מאכל אדם כו', אך כדי לבוא מבחי' מאכל אדם לבחי' מאכל בהמה צ\"ל ממוצע בזה שהוא ענין ספה\"ע, נמצא יש ג' בחי' מנחת<sup data-n=\"3140\">20</sup> ומנחת חטים והממוצע ביניהם שהוא ענין ספירת העומר וכל ג' בחי' אלו הם אחר יצי\"מ כו' וד\"ל.\n<b>וביאור</b> הענין יש להבין מתחילה ענין שעורה שיעור ה', כי הנה במלאכים נאמר ופניהם וכנפיהם פרודות<sup data-n=\"3141\">21</sup> ואין הכוונה לומר שגם פניהם פרודות, כי הלא תיבת פניהם מופסק בזקף גדול, להורות שפניהם אינם פרודות רק כנפיהם פרודות. ותחילה יש להבין מהו בחי' כנפיהם, כי הנה כתיב אחרי ה' ילכו כארי' ישאג<sup data-n=\"3142\">22</sup>, כארי' שבמרכבה<sup data-n=\"3143\">23</sup> שישאג כו', כי הנה כללות המרכבה הוא בחי' בהמה בחי' יש כמאמר שנים עשר בקר<sup data-n=\"3144\">24</sup> והים עומד עליהם מלמעלה<sup data-n=\"3145\">25</sup>, אבל באצי' הוא בחי' אדם שם מ\"ה<sup data-n=\"3146\">26</sup> בחי' ביטול בתכלית. כי הנה ההפרש בין ע\"ס דאצי' לע\"ס דבי\"ע",[["3129","9","<b>שעורה שעור ה'</b>: זהר בלק קפח, ב. ראה גם (בנוסף להערה 1) לקמן מאמר ד\"ה בסוכות תשבו תרכ\"ב הערה 38."],["3130","10","<b>שעורה. . מאכל בהמה</b>: ראה מל\"א ה, ח. פסחים ג, סע\"ב. סוטה יד, א (במשנה)."],["3131","11","<b>בהמה. . שם ב\"ן</b>: ראה תניא ספמ\"ו. מאמרי אדה\"א ויקרא ח\"א ע' ד. וש\"נ."],["3132","12","<b>הבריאה. . חי. . האצי' שנק' מדבר</b>: ראה סה\"ש תשנ\"ב ע' 139 הערה 54. תו\"ח משפטים ח\"ב רצט, א. וש\"נ."],["3133","13","<b>וצי\"א</b>: וצירופי אותיות."],["3134","14","<b>מהעלמם</b>: אולי כ\"ה בגוכת\"י."],["3135","15","<b>חטה בגי' כ\"ב</b>: ראה ת\"ז שבהערה הבאה. פע\"ח שער חג השבועות שכ\"ג, פ\"א. טעמי המצות להאריז\"ל ר\"פ אמור. לקו\"ת שה\"ש כז, ג. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקפא."],["3136","16","<b>חטה. . כ\"ב אתוון דאורייתא</b>: ראה זהר בלק קפח, ב. ת\"ז תס\"ט (קיד, א. ב)."],["3137","17","<b>מאכל</b>: אולי כ\"ה בגוכת\"י."],["3138","18","<b>אדם אתם</b>: יחזקאל לד, לא."],["3139","19","<b>כי לא אדם</b>: שמו\"א טו, כט."],["3140","20","<b>מנחת</b>: אוצ\"ל: מנחת שעורים."],["3141","21","<b>ופניהם וכנפיהם פרודות</b>: יחזקאל א, יא. ראה רש\"י ורד\"ק שם. ראה גם מאמרי אדה\"א במדבר ח\"ב ע' ת ואילך."],["3142","22","<b>אחרי ה' ילכו כארי' ישאג</b>: הושע יא, י."],["3143","23","<b>כארי' שבמרכבה</b>: ראה מאמרי אדה\"א דברים ח\"א ס\"ע שא. וש\"נ."],["3144","24","<b>שנים עשר בקר</b>: ראה מל\"א ז, כב. מד. דהי\"ב ד, טו."],["3145","25","<b>מלמעלה</b>: צויין סי' לעיין עה\"ג, אבל עה\"ג מטושטש וקרוע."],["3146","26","<b>אדם שם מ\"ה</b>: ראה ע\"ח שער התיקון ש\"י, פ\"ג. לקו\"ת ושער הפסוקים להאריז\"ל בראשית ג, כ. מאמרי אדה\"ז על פרשיות התורה ח\"ב ע' תקסז ובהנסמן במ\"מ לשם. תו\"ח בראשית ט, א הערה 14."]]],[4801940236,"יובן ע\"ד דוגמא מחיות הנפש המתלבש באברי הגוף שאע\"פ שהאברים המה גשמיים ואין להם ערך לחיות הנפש הרוחני אעפ\"כ מתייחד בהם חיות הנפש הרוחני בתכלית עד שא\"א לו לפשוט א\"ע מהם, ועוד זאת שאע\"פ שחיות הנפש הרוחני הוא רחוק מגדר גילוי בתכלית מ\"מ ע\"י האברים מתקרב לבחי' הגילוי עד שמתגלה על ידם בגילוי גמור, כמו<sup data-n=\"3147\">27</sup> כח הראי' הרוחני הוא מתייחד בעין הגשמי עד שא\"א לו לפשוט א\"ע ממנו ולא ברצון הנפש תליא מילתא כי אפי' אם ירצה שלא לראות כ\"ז שהעין פתוחה הוא רואה ממילא וכן שמיעה באוזן כו', ואפי' בבחי' תנועה ביד והילוך ברגל אע\"פ שגילויים מהעלמם תלוי ברצון הנפש אך כח התנועה שמתחבר בגשם היד עד שמחמת זה יש בכחו להניע וכן מה שבכח הרגל להלוך מזה אין ביכולת הנפש להסתלק כמאמר בע\"כ אתה חי<sup data-n=\"3148\">28</sup>, והטעם לזה להיות שיש רצון עליון למעלה מרצון הנפש המפליא לעשות ומקשר גשמי ברוחני, כן רצון זה הוא הפועל קירוב הרוחני לגבי הגשמי ויתמזג בו עד שיבוא ע\"י לבחי' גילוי גמור כמו כח הראי' הרוחני שמתגלה ע\"י העין הגשמי לראות בדבר נבדל ובלעדי העין לא הי' רואה ומתגלה כלל וכן כח השמיעה באוזן ותנועה ביד. . עיקר כוונת רצון העליון בחיבור זה לקשר גשמי ברוחני היא הגילוי שמתגלה ע\"י אברי הגוף וא\"כ מלובש. . הרצון<sup data-n=\"3149\">29</sup> בבחי' כלים ואברי הגוף יותר מכמו שהוא מלובש ברוחני' הנפש כו', ונמצא באברי הגוף אע\"פ שהמה רחוקים מרוחניות הנפש בתכלית מ\"מ מתייחדים בו בתכלית אבל בחי' לבושי אדם אע\"פ שגם הלבוש עשוי כמדת אבריו וגם מעוררים המשכת חיות הנפש בבחי' גילוי קצת להתיפות ע\"י הלבושים מ\"מ אין לזה ערך לגבי גילוי החיות ע\"י האברים וגם אינו מתייחד עמו כי ביכולתו לפשטו וללבשו כו'.\n<b>והנמשל</b> מזה יובן למעלה בענין ע\"ס דאצי' הנק' חכים ומבין שאין הכוונה חכ' רוחני' כשכל והשגת המלאכים כי כל שכל והשגה מוכרח להיות מוגבלת במקום ומוגבל<sup data-n=\"3150\">30</sup> בזמן משא\"כ בחי' אלקו' אינו בגדר הגבלה והתחלקות כלל רק מה שנק' בשם חכים הוא בחי' כח האלקי המגביל א\"ע מיני' ובי' שלא יתגלה רק להשפיע חכ' ולא שפע אחר זולתה ועד\"מ כח התנועה שביד שבא לידי גילוי תנועה פחות מכפי כחו שהגם שגילוי התנועה כבר היא מוגבלת ולא יתוסף ולא יגרע מ\"מ הכח שהגבילה הוא הרצון שנתלבש בכח התנועה לעוררו בבחי' המשכה מהעלם אל הגילוי והוא הוא עצמו המגביל לגילוי זה שלא יתגלה יותר מכפי רצונו וא\"כ מקור השפע ומקור ההגבלה אחת היא ממש ואין לחלק ביניהם כלל, וכך הוא למעלה עצמו' האור הוא בחי' א\"ס שיכול להתפשט בלי שיעור ולא להשפיע שפע מוגבלת כמו שכל ומדות רק מחמת שבחי' רצה\"ע שפעל התעוררות האור שיבוא מהעלמו לכלל גילוי והתפשטות הוא הוא המגבילו שלא יאיר כמ\"ש רק בבחי' שפע מוגבל שהוא בחי' הנבראים מאין ליש דייקא והכוונה אינה בשביל השפע עצמה המוגבלת רק בכדי שיתגלה על ידם בבחי' גילוי גמור בנבראים המוגבלים דייקא עד שיוכלו",[["3147","27","<b>כמו</b>: אולי כ\"ה בגוכת\"י."],["3148","28","<b>בע\"כ אתה חי</b>: ראה אבות ספ\"ד."],["3149","29","<b>הרצון</b>: תיבה זו איננה ברורה."],["3150","30","<b>ומוגבל</b>: אולי כ\"ה בגוכת\"י."]]]]});
